ALL_MAPPINGS_QUERY="""
WITH workflow_mappings AS (
 SELECT DISTINCT s.SUBJECT_AREA,s.MAPPING_ID,w.WORKFLOW_NAME,
 ti.INSTANCE_NAME AS SESSION_INSTANCE_NAME,s.SESSION_NAME
 FROM {schema}REP_WORKFLOWS w
 JOIN {schema}REP_TASK_INST ti ON ti.WORKFLOW_ID=w.WORKFLOW_ID AND ti.TASK_TYPE=68
 JOIN {schema}REP_LOAD_SESSIONS s ON s.SESSION_ID=ti.TASK_ID
 WHERE w.SUBJECT_AREA=:subject_area AND w.WORKFLOW_NAME=:workflow_name {mapping_filter}
)
SELECT DISTINCT wm.SUBJECT_AREA,wm.WORKFLOW_NAME,wm.SESSION_INSTANCE_NAME,
 wm.SESSION_NAME,m.MAPPING_NAME,wi.INSTANCE_ID,wi.INSTANCE_NAME,wi.WIDGET_ID,
 wi.WIDGET_TYPE,wi.WIDGET_TYPE_NAME
FROM workflow_mappings wm
JOIN {schema}REP_ALL_MAPPINGS m ON m.MAPPING_ID=wm.MAPPING_ID AND m.SUBJECT_AREA=wm.SUBJECT_AREA
JOIN {schema}REP_WIDGET_INST wi ON wi.MAPPING_ID=m.MAPPING_ID
ORDER BY wm.SUBJECT_AREA,wm.WORKFLOW_NAME,wm.SESSION_INSTANCE_NAME,m.MAPPING_NAME,
 wi.WIDGET_TYPE_NAME,wi.INSTANCE_NAME
"""
ALIASES={"LOOKUP":"LOOKUPPROCEDURE","SEQUENCE":"SEQUENCEGENE","SEQUENCEGENERATOR":"SEQUENCEGENE","SEQUENCEGENE":"SEQUENCEGENE","TARGET":"TARGETDEFINITION","TARGETDEFINITION":"TARGETDEFINITION"}
EMBEDDED_QUERIES={'ALLDETAILS': {'label': 'All Details', 'sql': "WITH workflow_mappings AS (\n    SELECT DISTINCT\n           s.SUBJECT_AREA,\n           s.MAPPING_ID,\n           w.WORKFLOW_NAME,\n           ti.INSTANCE_NAME AS SESSION_INSTANCE_NAME,\n           s.SESSION_NAME\n    FROM M2R_REP_1053_P01.REP_WORKFLOWS w\n    JOIN M2R_REP_1053_P01.REP_TASK_INST ti\n      ON ti.WORKFLOW_ID = w.WORKFLOW_ID\n     AND ti.TASK_TYPE = 68\n    JOIN M2R_REP_1053_P01.REP_LOAD_SESSIONS s\n      ON s.SESSION_ID = ti.TASK_ID\n    WHERE w.SUBJECT_AREA = 'M2R_DTM'\n      AND w.WORKFLOW_NAME = 'WF_DTM_MMTR'\n)\nSELECT DISTINCT\n       wm.SUBJECT_AREA,\n       wm.WORKFLOW_NAME,\n       wm.SESSION_INSTANCE_NAME,\n       wm.SESSION_NAME,\n       m.MAPPING_NAME,\n       wi.INSTANCE_ID,\n       wi.INSTANCE_NAME,\n       wi.WIDGET_ID,\n       wi.WIDGET_TYPE,\n       wi.WIDGET_TYPE_NAME\nFROM workflow_mappings wm\nJOIN M2R_REP_1053_P01.REP_ALL_MAPPINGS m\n  ON m.MAPPING_ID = wm.MAPPING_ID\n AND m.SUBJECT_AREA = wm.SUBJECT_AREA\nJOIN M2R_REP_1053_P01.REP_WIDGET_INST wi\n  ON wi.MAPPING_ID = m.MAPPING_ID\nORDER BY\n       wm.SUBJECT_AREA,\n       wm.WORKFLOW_NAME,\n       wm.SESSION_INSTANCE_NAME,\n       m.MAPPING_NAME,\n       wi.WIDGET_TYPE_NAME,\n       wi.INSTANCE_NAME;"}, 'EXPRESSION': {'label': 'Expression', 'sql': "WITH workflow_mappings AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           s.SUBJECT_AREA,\n           s.SUBJECT_ID,\n           s.MAPPING_ID,\n           w.WORKFLOW_NAME,\n           ti.INSTANCE_NAME AS SESSION_INSTANCE_NAME,\n           s.SESSION_NAME\n    FROM M2R_REP_1053_P01.REP_WORKFLOWS w\n    JOIN M2R_REP_1053_P01.REP_TASK_INST ti\n      ON ti.WORKFLOW_ID = w.WORKFLOW_ID\n     AND ti.TASK_TYPE = 68\n    JOIN M2R_REP_1053_P01.REP_LOAD_SESSIONS s\n      ON s.SESSION_ID = ti.TASK_ID\n    WHERE w.SUBJECT_AREA = 'M2R_DTM'\n      AND w.WORKFLOW_NAME = 'WF_DTM_MMTR'\n),\nexpression_instances AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           wm.SUBJECT_AREA,\n           wm.SUBJECT_ID,\n           wm.WORKFLOW_NAME,\n           wm.SESSION_INSTANCE_NAME,\n           wm.SESSION_NAME,\n           wm.MAPPING_ID,\n           m.MAPPING_NAME,\n           wi.INSTANCE_ID,\n           wi.INSTANCE_NAME AS TRANSFORMATION_NAME,\n           wi.WIDGET_ID,\n           wi.WIDGET_TYPE_NAME AS TRANSFORMATION_TYPE,\n           wi.VERSION_NUMBER\n    FROM workflow_mappings wm\n    JOIN M2R_REP_1053_P01.REP_ALL_MAPPINGS m\n      ON m.MAPPING_ID = wm.MAPPING_ID\n     AND m.SUBJECT_AREA = wm.SUBJECT_AREA\n    JOIN M2R_REP_1053_P01.REP_WIDGET_INST wi\n      ON wi.MAPPING_ID = wm.MAPPING_ID\n     AND wi.SUBJECT_ID = wm.SUBJECT_ID\n     AND wi.WIDGET_TYPE = 5\n),\nrelevant_transformations AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER\n    FROM expression_instances\n),\ntracing_property AS\n(\n    SELECT\n           rt.MAPPING_ID,\n           rt.INSTANCE_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           MAX(TRIM(wa.ATTR_VALUE))\n               AS TRACING_LEVEL_CODE\n    FROM relevant_transformations rt\n    LEFT JOIN M2R_REP_1053_P01.REP_WIDGET_ATTR wa\n      ON wa.WIDGET_ID = rt.WIDGET_ID\n     AND wa.VERSION_NUMBER = rt.VERSION_NUMBER\n     AND UPPER(TRIM(wa.ATTR_NAME)) = 'TRACING LEVEL'\n     AND\n         (\n             wa.INSTANCE_ID = rt.INSTANCE_ID\n             OR wa.INSTANCE_ID IS NULL\n             OR wa.INSTANCE_ID = 0\n         )\n     AND\n         (\n             wa.MAPPING_ID = rt.MAPPING_ID\n             OR wa.MAPPING_ID IS NULL\n             OR wa.MAPPING_ID = 0\n         )\n    GROUP BY\n           rt.MAPPING_ID,\n           rt.INSTANCE_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER\n),\nexpression_metadata_extensions AS\n(\n    SELECT\n           rt.SUBJECT_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           mdx.METADATA_EXTN_NAME,\n           mdx.METADATA_EXTN_DATA_TYPE,\n           mdx.METADATA_EXTN_VALUE,\n           mdx.PERMISSIONS,\n           mdx.LINE_NO,\n           mdx.DOMAIN_NAME,\n           mdx.DOMAIN_USAGE,\n           mdx.METADATA_EXTN_DESCRIPTION,\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NOT NULL\n               THEN LENGTH(mdx.METADATA_EXTN_VALUE)\n           END AS METADATA_EXTENSION_PRECISION,\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NULL\n               THEN NULL\n               WHEN mdx.DOMAIN_ID IS NOT NULL\n                 OR mdx.DOMAIN_NAME IS NOT NULL\n               THEN 'YES'\n               ELSE 'NO'\n           END AS REUSABLE\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_METADATA_EXTNS mdx\n      ON mdx.SUBJECT_ID = rt.SUBJECT_ID\n     AND mdx.METADATA_EXTN_OBJECT_ID = rt.WIDGET_ID\n     AND mdx.VERSION_NUMBER = rt.VERSION_NUMBER\n),\nincoming_connections AS\n(\n    SELECT\n           pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.TO_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.TO_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.FROM_OBJECT_NAME\n               || '.'\n               || pc.FROM_OBJECT_FIELD_NAME\n               AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.TO_OBJECT_INSTANCE_ID\n    WHERE pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n),\noutgoing_connections AS\n(\n    SELECT\n           pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.FROM_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.FROM_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.TO_OBJECT_NAME\n               || '.'\n               || pc.TO_OBJECT_FIELD_NAME\n               AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.FROM_OBJECT_INSTANCE_ID\n    WHERE pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.TO_OBJECT_NAME IS NOT NULL\n      AND pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n),\nincoming_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM incoming_connections\n),\noutgoing_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM outgoing_connections\n),\nport_connections AS\n(\n    SELECT\n           k.SUBJECT_ID,\n           k.MAPPING_ID,\n           k.MAPPING_VERSION_NUMBER,\n           k.INSTANCE_ID,\n           k.FIELD_NAME,\n           incoming.PREVIOUS_TRANSFORMATION,\n           outgoing.NEXT_TRANSFORMATION_NAME\n    FROM\n    (\n        SELECT\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM incoming_connections_distinct\n\n        UNION\n\n        SELECT\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM outgoing_connections_distinct\n    ) k\n    LEFT JOIN\n    (\n        SELECT\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS PREVIOUS_TRANSFORMATION\n        FROM incoming_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) incoming\n      ON incoming.SUBJECT_ID = k.SUBJECT_ID\n     AND incoming.MAPPING_ID = k.MAPPING_ID\n     AND incoming.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND incoming.INSTANCE_ID = k.INSTANCE_ID\n     AND incoming.FIELD_NAME = k.FIELD_NAME\n    LEFT JOIN\n    (\n        SELECT\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS NEXT_TRANSFORMATION_NAME\n        FROM outgoing_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) outgoing\n      ON outgoing.SUBJECT_ID = k.SUBJECT_ID\n     AND outgoing.MAPPING_ID = k.MAPPING_ID\n     AND outgoing.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND outgoing.INSTANCE_ID = k.INSTANCE_ID\n     AND outgoing.FIELD_NAME = k.FIELD_NAME\n)\nSELECT DISTINCT\n       ei.SUBJECT_AREA,\n       ei.WORKFLOW_NAME,\n       ei.SESSION_INSTANCE_NAME,\n       ei.SESSION_NAME,\n       ei.MAPPING_NAME,\n\n       /* Transformation tab */\n       ei.TRANSFORMATION_NAME,\n       ei.TRANSFORMATION_TYPE,\n\n       /* Ports tab */\n       wf.FIELD_ORDER AS PORT_ORDER,\n       wf.FIELD_NAME AS PORT_NAME,\n       wf.WGT_DATATYPE AS DATATYPE,\n       wf.WGT_PREC AS PREC,\n       wf.WGT_SCALE AS SCALE,\n\n       CASE\n           WHEN wf.PORTTYPE IN (1, 3) THEN 'YES'\n           ELSE 'NO'\n       END AS I,\n\n       CASE\n           WHEN wf.PORTTYPE IN (2, 3) THEN 'YES'\n           ELSE 'NO'\n       END AS O,\n\n       CASE\n           WHEN wf.PORTTYPE = 32 THEN 'YES'\n           ELSE 'NO'\n       END AS V,\n\n       oe.LINE_NO AS EXPRESSION_LINE_NO,\n       oe.EXPRESSION,\n\n       /* Properties tab */\n       CASE TRIM(tp.TRACING_LEVEL_CODE)\n           WHEN '1' THEN 'Terse'\n           WHEN '2' THEN 'Normal'\n           WHEN '3' THEN 'Verbose Initialization'\n           WHEN '4' THEN 'Verbose Data'\n           WHEN NULL THEN 'Normal'\n           ELSE\n               'Unknown ('\n               || tp.TRACING_LEVEL_CODE\n               || ')'\n       END AS TRACING_LEVEL,\n\n       /* Metadata Extensions tab */\n       eme.METADATA_EXTN_NAME AS EXTENSION_NAME,\n       eme.METADATA_EXTN_DATA_TYPE AS EXTENSION_DATATYPE_CODE,\n\n       CASE eme.METADATA_EXTN_DATA_TYPE\n           WHEN 1 THEN 'String'\n           WHEN 2 THEN 'Number'\n           WHEN 3 THEN 'Boolean'\n           ELSE\n               CASE\n                   WHEN eme.METADATA_EXTN_DATA_TYPE IS NULL\n                   THEN NULL\n                   ELSE\n                       'Other ('\n                       || TO_CHAR(eme.METADATA_EXTN_DATA_TYPE)\n                       || ')'\n               END\n       END AS EXTENSION_DATATYPE,\n\n       eme.METADATA_EXTENSION_PRECISION AS EXTENSION_PREC,\n       eme.METADATA_EXTN_VALUE AS EXTENSION_VALUE,\n       eme.REUSABLE,\n       eme.PERMISSIONS AS EXTENSION_PERMISSIONS,\n       eme.LINE_NO AS EXTENSION_LINE_NO,\n       eme.DOMAIN_NAME AS EXTENSION_DOMAIN_NAME,\n       eme.DOMAIN_USAGE AS EXTENSION_DOMAIN_USAGE,\n       eme.METADATA_EXTN_DESCRIPTION AS EXTENSION_DESCRIPTION,\n\n       /* Connected transformation ports */\n       pc.PREVIOUS_TRANSFORMATION,\n       pc.NEXT_TRANSFORMATION_NAME\n\nFROM expression_instances ei\n\nJOIN M2R_REP_1053_P01.OPB_WIDGET_FIELD wf\n  ON wf.WIDGET_ID = ei.WIDGET_ID\n AND wf.VERSION_NUMBER = ei.VERSION_NUMBER\n\nLEFT JOIN M2R_REP_1053_P01.OPB_WIDGET_EXPR we\n  ON we.WIDGET_ID = wf.WIDGET_ID\n AND we.OUTPUT_FIELD_ID = wf.FIELD_ID\n AND we.VERSION_NUMBER = wf.VERSION_NUMBER\n\nLEFT JOIN M2R_REP_1053_P01.OPB_EXPRESSION oe\n  ON oe.WIDGET_ID = we.WIDGET_ID\n AND oe.EXPR_ID = we.EXPR_ID\n AND oe.VERSION_NUMBER = we.VERSION_NUMBER\n\nLEFT JOIN tracing_property tp\n  ON tp.MAPPING_ID = ei.MAPPING_ID\n AND tp.INSTANCE_ID = ei.INSTANCE_ID\n AND tp.WIDGET_ID = ei.WIDGET_ID\n AND tp.VERSION_NUMBER = ei.VERSION_NUMBER\n\nLEFT JOIN expression_metadata_extensions eme\n  ON eme.SUBJECT_ID = ei.SUBJECT_ID\n AND eme.WIDGET_ID = ei.WIDGET_ID\n AND eme.VERSION_NUMBER = ei.VERSION_NUMBER\n\nLEFT JOIN port_connections pc\n  ON pc.SUBJECT_ID = ei.SUBJECT_ID\n AND pc.MAPPING_ID = ei.MAPPING_ID\n AND pc.MAPPING_VERSION_NUMBER = ei.VERSION_NUMBER\n AND pc.INSTANCE_ID = ei.INSTANCE_ID\n AND pc.FIELD_NAME = wf.FIELD_NAME\n\nORDER BY\n       ei.SUBJECT_AREA,\n       ei.WORKFLOW_NAME,\n       ei.SESSION_INSTANCE_NAME,\n       ei.SESSION_NAME,\n       ei.MAPPING_NAME,\n       ei.TRANSFORMATION_NAME,\n       wf.FIELD_ORDER,\n       wf.FIELD_NAME,\n       oe.LINE_NO,\n       eme.METADATA_EXTN_NAME,\n       eme.LINE_NO;"}, 'LOOKUPPROCEDURE': {'label': 'Lookup Procedure', 'sql': "WITH lookup_base AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           m.SUBJECT_AREA,\n           m.SUBJECT_ID,\n           m.MAPPING_ID,\n           m.MAPPING_NAME,\n           w.WORKFLOW_NAME,\n           ti.INSTANCE_NAME AS SESSION_INSTANCE_NAME,\n           s.SESSION_NAME,\n           wi.INSTANCE_ID,\n           wi.INSTANCE_NAME AS LOOKUP_TRANSFORMATION,\n           wi.WIDGET_ID,\n           wi.VERSION_NUMBER,\n           wi.WIDGET_TYPE_NAME AS TRANSFORMATION_TYPE\n    FROM M2R_REP_1053_P01.REP_ALL_MAPPINGS m\n    JOIN M2R_REP_1053_P01.REP_LOAD_SESSIONS s\n      ON s.MAPPING_ID = m.MAPPING_ID\n     AND s.SUBJECT_AREA = m.SUBJECT_AREA\n    JOIN M2R_REP_1053_P01.REP_TASK_INST ti\n      ON ti.TASK_ID = s.SESSION_ID\n     AND ti.TASK_TYPE = 68\n    JOIN M2R_REP_1053_P01.REP_WORKFLOWS w\n      ON w.WORKFLOW_ID = ti.WORKFLOW_ID\n     AND w.SUBJECT_AREA = m.SUBJECT_AREA\n    JOIN M2R_REP_1053_P01.REP_WIDGET_INST wi\n      ON wi.MAPPING_ID = m.MAPPING_ID\n     AND wi.SUBJECT_ID = m.SUBJECT_ID\n     AND wi.WIDGET_TYPE = 11\n    WHERE m.SUBJECT_AREA = 'M2R_DTM'\n      AND w.WORKFLOW_NAME = 'WF_DTM_MMTR'\n      AND m.MAPPING_NAME = 'M_DTM_MMTR_ELIGIBILITY'\n),\nlookup_attributes AS\n(\n    SELECT\n           lb.SUBJECT_ID,\n           lb.MAPPING_ID,\n           lb.INSTANCE_ID,\n           lb.WIDGET_ID,\n           lb.VERSION_NUMBER,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'LOOKUP SQL OVERRIDE'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS LOOKUP_SQL_OVERRIDE,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) IN\n                        (\n                            'LOOKUP TABLE NAME',\n                            'LOOKUP SOURCE NAME'\n                        )\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS LOOKUP_TABLE_NAME,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'LOOKUP SOURCE FILTER'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS LOOKUP_SOURCE_FILTER,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) IN\n                        (\n                            'LOOKUP CACHING ENABLED',\n                            'LOOKUP CACHE ENABLED'\n                        )\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS LOOKUP_CACHING_ENABLED,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'LOOKUP POLICY ON MULTIPLE MATCH'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS LOOKUP_POLICY_ON_MULTIPLE_MATCH,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'LOOKUP CONDITION'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS LOOKUP_CONDITION,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'CONNECTION INFORMATION'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS CONNECTION_INFORMATION,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'SOURCE TYPE'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS SOURCE_TYPE,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'TRACING LEVEL'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS TRACING_LEVEL_CODE,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'LOOKUP CACHE DIRECTORY NAME'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS LOOKUP_CACHE_DIRECTORY_NAME,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'LOOKUP CACHE PERSISTENT'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS LOOKUP_CACHE_PERSISTENT,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'LOOKUP DATA CACHE SIZE'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS LOOKUP_DATA_CACHE_SIZE,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'LOOKUP INDEX CACHE SIZE'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS LOOKUP_INDEX_CACHE_SIZE,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'DYNAMIC LOOKUP CACHE'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS DYNAMIC_LOOKUP_CACHE,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'SYNCHRONIZE DYNAMIC CACHE'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS SYNCHRONIZE_DYNAMIC_CACHE,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'OUTPUT OLD VALUE ON UPDATE'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS OUTPUT_OLD_VALUE_ON_UPDATE,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'UPDATE DYNAMIC CACHE CONDITION'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS UPDATE_DYNAMIC_CACHE_CONDITION,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'CACHE FILE NAME PREFIX'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS CACHE_FILE_NAME_PREFIX,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'RE-CACHE FROM LOOKUP SOURCE'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS RECACHE_FROM_LOOKUP_SOURCE,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'INSERT ELSE UPDATE'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS INSERT_ELSE_UPDATE,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'UPDATE ELSE INSERT'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS UPDATE_ELSE_INSERT,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'DATETIME FORMAT'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS DATETIME_FORMAT,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'THOUSAND SEPARATOR'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS THOUSAND_SEPARATOR,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'DECIMAL SEPARATOR'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS DECIMAL_SEPARATOR,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'CASE SENSITIVE STRING COMPARISON'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS CASE_SENSITIVE_STRING_COMPARISON,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'NULL ORDERING'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS NULL_ORDERING,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'SORTED INPUT'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS SORTED_INPUT,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'LOOKUP SOURCE IS STATIC'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS LOOKUP_SOURCE_IS_STATIC,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'PRE-BUILD LOOKUP CACHE'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS PRE_BUILD_LOOKUP_CACHE,\n\n           MAX(\n               CASE\n                   WHEN UPPER(TRIM(wa.ATTR_NAME)) =\n                        'SUBSECOND PRECISION'\n                   THEN TRIM(wa.ATTR_VALUE)\n               END\n           ) AS SUBSECOND_PRECISION\n\n    FROM lookup_base lb\n    LEFT JOIN M2R_REP_1053_P01.REP_WIDGET_ATTR wa\n      ON wa.WIDGET_ID = lb.WIDGET_ID\n     AND wa.VERSION_NUMBER = lb.VERSION_NUMBER\n     AND\n         (\n             wa.MAPPING_ID = lb.MAPPING_ID\n             OR wa.MAPPING_ID IS NULL\n             OR wa.MAPPING_ID = 0\n         )\n     AND\n         (\n             wa.INSTANCE_ID = lb.INSTANCE_ID\n             OR wa.INSTANCE_ID IS NULL\n             OR wa.INSTANCE_ID = 0\n         )\n     AND UPPER(TRIM(wa.ATTR_NAME)) IN\n         (\n             'LOOKUP SQL OVERRIDE',\n             'LOOKUP TABLE NAME',\n             'LOOKUP SOURCE NAME',\n             'LOOKUP SOURCE FILTER',\n             'LOOKUP CACHING ENABLED',\n             'LOOKUP CACHE ENABLED',\n             'LOOKUP POLICY ON MULTIPLE MATCH',\n             'LOOKUP CONDITION',\n             'CONNECTION INFORMATION',\n             'SOURCE TYPE',\n             'TRACING LEVEL',\n             'LOOKUP CACHE DIRECTORY NAME',\n             'LOOKUP CACHE PERSISTENT',\n             'LOOKUP DATA CACHE SIZE',\n             'LOOKUP INDEX CACHE SIZE',\n             'DYNAMIC LOOKUP CACHE',\n             'SYNCHRONIZE DYNAMIC CACHE',\n             'OUTPUT OLD VALUE ON UPDATE',\n             'UPDATE DYNAMIC CACHE CONDITION',\n             'CACHE FILE NAME PREFIX',\n             'RE-CACHE FROM LOOKUP SOURCE',\n             'INSERT ELSE UPDATE',\n             'UPDATE ELSE INSERT',\n             'DATETIME FORMAT',\n             'THOUSAND SEPARATOR',\n             'DECIMAL SEPARATOR',\n             'CASE SENSITIVE STRING COMPARISON',\n             'NULL ORDERING',\n             'SORTED INPUT',\n             'LOOKUP SOURCE IS STATIC',\n             'PRE-BUILD LOOKUP CACHE',\n             'SUBSECOND PRECISION'\n         )\n    GROUP BY\n           lb.SUBJECT_ID,\n           lb.MAPPING_ID,\n           lb.INSTANCE_ID,\n           lb.WIDGET_ID,\n           lb.VERSION_NUMBER\n),\nlookup_condition_source AS\n(\n    SELECT\n           la.SUBJECT_ID,\n           la.MAPPING_ID,\n           la.INSTANCE_ID,\n           la.WIDGET_ID,\n           la.VERSION_NUMBER,\n           REGEXP_REPLACE(\n               REPLACE(la.LOOKUP_CONDITION, ';', ' AND '),\n               '[[:space:]]+AND[[:space:]]+',\n               ' AND ',\n               1,\n               0,\n               'i'\n           ) AS NORMALIZED_CONDITION\n    FROM lookup_attributes la\n    WHERE la.LOOKUP_CONDITION IS NOT NULL\n),\nlookup_condition_rows AS\n(\n    SELECT\n           lcs.SUBJECT_ID,\n           lcs.MAPPING_ID,\n           lcs.INSTANCE_ID,\n           lcs.WIDGET_ID,\n           lcs.VERSION_NUMBER,\n           LEVEL AS CONDITION_ORDER,\n           TRIM(\n               REGEXP_SUBSTR(\n                   lcs.NORMALIZED_CONDITION,\n                   '(.*?)([[:space:]]+AND[[:space:]]+|$)',\n                   1,\n                   LEVEL,\n                   'i',\n                   1\n               )\n           ) AS CONDITION_TEXT\n    FROM lookup_condition_source lcs\n    CONNECT BY LEVEL <=\n               REGEXP_COUNT(\n                   lcs.NORMALIZED_CONDITION,\n                   '[[:space:]]+AND[[:space:]]+',\n                   1,\n                   'i'\n               ) + 1\n           AND PRIOR lcs.SUBJECT_ID = lcs.SUBJECT_ID\n           AND PRIOR lcs.MAPPING_ID = lcs.MAPPING_ID\n           AND PRIOR lcs.INSTANCE_ID = lcs.INSTANCE_ID\n           AND PRIOR lcs.WIDGET_ID = lcs.WIDGET_ID\n           AND PRIOR lcs.VERSION_NUMBER = lcs.VERSION_NUMBER\n           AND PRIOR SYS_GUID() IS NOT NULL\n),\nlookup_conditions AS\n(\n    SELECT\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER,\n           CONDITION_ORDER,\n\n           TRIM(\n               REGEXP_SUBSTR(\n                   CONDITION_TEXT,\n                   '^(.+?)[[:space:]]*'\n                   || '(<>|!=|<=|>=|=|<|>)[[:space:]]*',\n                   1,\n                   1,\n                   NULL,\n                   1\n               )\n           ) AS LOOKUP_TABLE_COLUMN,\n\n           REGEXP_SUBSTR(\n               CONDITION_TEXT,\n               '(<>|!=|<=|>=|=|<|>)',\n               1,\n               1\n           ) AS CONDITION_OPERATOR,\n\n           TRIM(\n               REGEXP_REPLACE(\n                   CONDITION_TEXT,\n                   '^.+?[[:space:]]*'\n                   || '(<>|!=|<=|>=|=|<|>)[[:space:]]*',\n                   ''\n               )\n           ) AS TRANSFORMATION_PORT\n\n    FROM lookup_condition_rows\n    WHERE CONDITION_TEXT IS NOT NULL\n),\nlookup_metadata_extensions AS\n(\n    SELECT\n           lb.SUBJECT_ID,\n           lb.MAPPING_ID,\n           lb.INSTANCE_ID,\n           lb.WIDGET_ID,\n           lb.VERSION_NUMBER,\n\n           mdx.METADATA_EXTN_NAME AS EXTENSION_NAME,\n\n           CASE mdx.METADATA_EXTN_DATA_TYPE\n               WHEN 1 THEN 'String'\n               WHEN 2 THEN 'Number'\n               WHEN 3 THEN 'Boolean'\n               ELSE\n                   CASE\n                       WHEN mdx.METADATA_EXTN_DATA_TYPE IS NULL\n                       THEN NULL\n                       ELSE\n                           'Other ('\n                           || TO_CHAR(mdx.METADATA_EXTN_DATA_TYPE)\n                           || ')'\n                   END\n           END AS EXTENSION_DATATYPE,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NOT NULL\n               THEN LENGTH(mdx.METADATA_EXTN_VALUE)\n           END AS EXTENSION_PREC,\n\n           mdx.METADATA_EXTN_VALUE AS EXTENSION_VALUE,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NULL\n               THEN NULL\n               WHEN mdx.DOMAIN_ID IS NOT NULL\n                 OR mdx.DOMAIN_NAME IS NOT NULL\n               THEN 'YES'\n               ELSE 'NO'\n           END AS EXTENSION_REUSABLE,\n\n           mdx.LINE_NO AS EXTENSION_LINE_NO\n\n    FROM lookup_base lb\n    JOIN M2R_REP_1053_P01.REP_METADATA_EXTNS mdx\n      ON mdx.SUBJECT_ID = lb.SUBJECT_ID\n     AND mdx.METADATA_EXTN_OBJECT_ID = lb.WIDGET_ID\n     AND mdx.VERSION_NUMBER = lb.VERSION_NUMBER\n),\nlookup_ports AS\n(\n    SELECT\n           lb.SUBJECT_ID,\n           lb.MAPPING_ID,\n           lb.INSTANCE_ID,\n           lb.WIDGET_ID,\n           lb.VERSION_NUMBER,\n           wf.FIELD_ID,\n           wf.FIELD_ORDER AS PORT_ORDER,\n           wf.FIELD_NAME AS PORT_NAME,\n           wf.WGT_DATATYPE AS DATATYPE,\n           wf.WGT_PREC AS PRECISION,\n           wf.WGT_SCALE AS SCALE,\n           wf.PORTTYPE,\n           oe.LINE_NO AS EXPRESSION_LINE_NO,\n           NVL(oe.EXPRESSION, '- N/A -')\n               AS ASSOCIATED_EXPRESSION\n    FROM lookup_base lb\n    JOIN M2R_REP_1053_P01.OPB_WIDGET_FIELD wf\n      ON wf.WIDGET_ID = lb.WIDGET_ID\n     AND wf.VERSION_NUMBER = lb.VERSION_NUMBER\n    LEFT JOIN M2R_REP_1053_P01.OPB_WIDGET_EXPR we\n      ON we.WIDGET_ID = wf.WIDGET_ID\n     AND we.VERSION_NUMBER = wf.VERSION_NUMBER\n     AND we.OUTPUT_FIELD_ID = wf.FIELD_ID\n    LEFT JOIN M2R_REP_1053_P01.OPB_EXPRESSION oe\n      ON oe.WIDGET_ID = we.WIDGET_ID\n     AND oe.VERSION_NUMBER = we.VERSION_NUMBER\n     AND oe.EXPR_ID = we.EXPR_ID\n)\nSELECT\n       lb.SUBJECT_AREA,\n       lb.WORKFLOW_NAME,\n       lb.SESSION_INSTANCE_NAME,\n       lb.SESSION_NAME,\n       lb.MAPPING_NAME,\n\n       /* Transformation tab */\n       lb.LOOKUP_TRANSFORMATION,\n       lb.TRANSFORMATION_TYPE,\n\n       CASE\n           WHEN UPPER(lb.TRANSFORMATION_TYPE) LIKE '%REUSABLE%'\n           THEN 'YES'\n           ELSE 'NO'\n       END AS TRANSFORMATION_REUSABLE,\n\n       /* Ports tab */\n       lp.PORT_ORDER,\n       lp.PORT_NAME,\n       lp.DATATYPE,\n       lp.PRECISION AS PREC,\n       lp.SCALE,\n\n       CASE\n           WHEN BITAND(lp.PORTTYPE, 1) = 1 THEN 'YES'\n           ELSE 'NO'\n       END AS I,\n\n       CASE\n           WHEN BITAND(lp.PORTTYPE, 2) = 2 THEN 'YES'\n           ELSE 'NO'\n       END AS O,\n\n       CASE\n           WHEN BITAND(lp.PORTTYPE, 4) = 4 THEN 'YES'\n           ELSE 'NO'\n       END AS L,\n\n       CASE\n           WHEN BITAND(lp.PORTTYPE, 8) = 8 THEN 'YES'\n           ELSE 'NO'\n       END AS R,\n\n       lp.EXPRESSION_LINE_NO,\n       lp.ASSOCIATED_EXPRESSION,\n\n       /* Condition tab */\n       lc.CONDITION_ORDER,\n       lc.LOOKUP_TABLE_COLUMN,\n       lc.CONDITION_OPERATOR AS OPERATOR,\n       lc.TRANSFORMATION_PORT,\n\n       /* Properties tab */\n       la.LOOKUP_SQL_OVERRIDE,\n       la.LOOKUP_TABLE_NAME,\n       la.LOOKUP_SOURCE_FILTER,\n\n       CASE\n           WHEN UPPER(la.LOOKUP_CACHING_ENABLED) IN\n                ('1', 'YES', 'TRUE', 'Y')\n           THEN 'YES'\n           WHEN la.LOOKUP_CACHING_ENABLED IS NULL\n           THEN NULL\n           ELSE 'NO'\n       END AS LOOKUP_CACHING_ENABLED,\n\n       la.LOOKUP_POLICY_ON_MULTIPLE_MATCH,\n       la.LOOKUP_CONDITION,\n       la.CONNECTION_INFORMATION,\n       la.SOURCE_TYPE,\n\n       CASE\n           WHEN la.TRACING_LEVEL_CODE IS NULL\n           THEN 'Normal'\n           WHEN UPPER(la.TRACING_LEVEL_CODE) = 'TERSE'\n             OR la.TRACING_LEVEL_CODE = '1'\n           THEN 'Terse'\n           WHEN UPPER(la.TRACING_LEVEL_CODE) = 'NORMAL'\n             OR la.TRACING_LEVEL_CODE = '2'\n           THEN 'Normal'\n           WHEN UPPER(la.TRACING_LEVEL_CODE) =\n                'VERBOSE INITIALIZATION'\n             OR la.TRACING_LEVEL_CODE = '3'\n           THEN 'Verbose Initialization'\n           WHEN UPPER(la.TRACING_LEVEL_CODE) = 'VERBOSE DATA'\n             OR la.TRACING_LEVEL_CODE = '4'\n           THEN 'Verbose Data'\n           ELSE la.TRACING_LEVEL_CODE\n       END AS TRACING_LEVEL,\n\n       la.LOOKUP_CACHE_DIRECTORY_NAME,\n\n       CASE\n           WHEN UPPER(la.LOOKUP_CACHE_PERSISTENT) IN\n                ('1', 'YES', 'TRUE', 'Y')\n           THEN 'YES'\n           WHEN la.LOOKUP_CACHE_PERSISTENT IS NULL\n           THEN NULL\n           ELSE 'NO'\n       END AS LOOKUP_CACHE_PERSISTENT,\n\n       la.LOOKUP_DATA_CACHE_SIZE,\n       la.LOOKUP_INDEX_CACHE_SIZE,\n\n       CASE\n           WHEN UPPER(la.DYNAMIC_LOOKUP_CACHE) IN\n                ('1', 'YES', 'TRUE', 'Y')\n           THEN 'YES'\n           WHEN la.DYNAMIC_LOOKUP_CACHE IS NULL\n           THEN NULL\n           ELSE 'NO'\n       END AS DYNAMIC_LOOKUP_CACHE,\n\n       CASE\n           WHEN UPPER(la.SYNCHRONIZE_DYNAMIC_CACHE) IN\n                ('1', 'YES', 'TRUE', 'Y')\n           THEN 'YES'\n           WHEN la.SYNCHRONIZE_DYNAMIC_CACHE IS NULL\n           THEN NULL\n           ELSE 'NO'\n       END AS SYNCHRONIZE_DYNAMIC_CACHE,\n\n       CASE\n           WHEN UPPER(la.OUTPUT_OLD_VALUE_ON_UPDATE) IN\n                ('1', 'YES', 'TRUE', 'Y')\n           THEN 'YES'\n           WHEN la.OUTPUT_OLD_VALUE_ON_UPDATE IS NULL\n           THEN NULL\n           ELSE 'NO'\n       END AS OUTPUT_OLD_VALUE_ON_UPDATE,\n\n       la.UPDATE_DYNAMIC_CACHE_CONDITION,\n       la.CACHE_FILE_NAME_PREFIX,\n\n       CASE\n           WHEN UPPER(la.RECACHE_FROM_LOOKUP_SOURCE) IN\n                ('1', 'YES', 'TRUE', 'Y')\n           THEN 'YES'\n           WHEN la.RECACHE_FROM_LOOKUP_SOURCE IS NULL\n           THEN NULL\n           ELSE 'NO'\n       END AS RECACHE_FROM_LOOKUP_SOURCE,\n\n       CASE\n           WHEN UPPER(la.INSERT_ELSE_UPDATE) IN\n                ('1', 'YES', 'TRUE', 'Y')\n           THEN 'YES'\n           WHEN la.INSERT_ELSE_UPDATE IS NULL\n           THEN NULL\n           ELSE 'NO'\n       END AS INSERT_ELSE_UPDATE,\n\n       CASE\n           WHEN UPPER(la.UPDATE_ELSE_INSERT) IN\n                ('1', 'YES', 'TRUE', 'Y')\n           THEN 'YES'\n           WHEN la.UPDATE_ELSE_INSERT IS NULL\n           THEN NULL\n           ELSE 'NO'\n       END AS UPDATE_ELSE_INSERT,\n\n       la.DATETIME_FORMAT,\n       la.THOUSAND_SEPARATOR,\n       la.DECIMAL_SEPARATOR,\n\n       CASE\n           WHEN UPPER(la.CASE_SENSITIVE_STRING_COMPARISON) IN\n                ('1', 'YES', 'TRUE', 'Y')\n           THEN 'YES'\n           WHEN la.CASE_SENSITIVE_STRING_COMPARISON IS NULL\n           THEN NULL\n           ELSE 'NO'\n       END AS CASE_SENSITIVE_STRING_COMPARISON,\n\n       la.NULL_ORDERING,\n\n       CASE\n           WHEN UPPER(la.SORTED_INPUT) IN\n                ('1', 'YES', 'TRUE', 'Y')\n           THEN 'YES'\n           WHEN la.SORTED_INPUT IS NULL\n           THEN NULL\n           ELSE 'NO'\n       END AS SORTED_INPUT,\n\n       CASE\n           WHEN UPPER(la.LOOKUP_SOURCE_IS_STATIC) IN\n                ('1', 'YES', 'TRUE', 'Y')\n           THEN 'YES'\n           WHEN la.LOOKUP_SOURCE_IS_STATIC IS NULL\n           THEN NULL\n           ELSE 'NO'\n       END AS LOOKUP_SOURCE_IS_STATIC,\n\n       la.PRE_BUILD_LOOKUP_CACHE,\n       la.SUBSECOND_PRECISION,\n\n       /* Metadata Extensions tab */\n       lme.EXTENSION_NAME,\n       lme.EXTENSION_DATATYPE,\n       lme.EXTENSION_PREC,\n       lme.EXTENSION_VALUE,\n       lme.EXTENSION_REUSABLE\n\nFROM lookup_base lb\n\nJOIN lookup_ports lp\n  ON lp.SUBJECT_ID = lb.SUBJECT_ID\n AND lp.MAPPING_ID = lb.MAPPING_ID\n AND lp.INSTANCE_ID = lb.INSTANCE_ID\n AND lp.WIDGET_ID = lb.WIDGET_ID\n AND lp.VERSION_NUMBER = lb.VERSION_NUMBER\n\nLEFT JOIN lookup_attributes la\n  ON la.SUBJECT_ID = lb.SUBJECT_ID\n AND la.MAPPING_ID = lb.MAPPING_ID\n AND la.INSTANCE_ID = lb.INSTANCE_ID\n AND la.WIDGET_ID = lb.WIDGET_ID\n AND la.VERSION_NUMBER = lb.VERSION_NUMBER\n\nLEFT JOIN lookup_conditions lc\n  ON lc.SUBJECT_ID = lb.SUBJECT_ID\n AND lc.MAPPING_ID = lb.MAPPING_ID\n AND lc.INSTANCE_ID = lb.INSTANCE_ID\n AND lc.WIDGET_ID = lb.WIDGET_ID\n AND lc.VERSION_NUMBER = lb.VERSION_NUMBER\n AND UPPER(TRIM(lc.TRANSFORMATION_PORT)) =\n     UPPER(TRIM(lp.PORT_NAME))\n\nLEFT JOIN lookup_metadata_extensions lme\n  ON lme.SUBJECT_ID = lb.SUBJECT_ID\n AND lme.MAPPING_ID = lb.MAPPING_ID\n AND lme.INSTANCE_ID = lb.INSTANCE_ID\n AND lme.WIDGET_ID = lb.WIDGET_ID\n AND lme.VERSION_NUMBER = lb.VERSION_NUMBER\n\nORDER BY\n       lb.SUBJECT_AREA,\n       lb.WORKFLOW_NAME,\n       lb.SESSION_INSTANCE_NAME,\n       lb.SESSION_NAME,\n       lb.MAPPING_NAME,\n       lb.LOOKUP_TRANSFORMATION,\n       lp.PORT_ORDER,\n       lp.PORT_NAME,\n       lc.CONDITION_ORDER,\n       lp.EXPRESSION_LINE_NO,\n       lme.EXTENSION_NAME,\n       lme.EXTENSION_LINE_NO;"}, 'JOINER': {'label': 'Joiner', 'sql': "WITH workflow_mappings AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           s.SUBJECT_AREA,\n           s.SUBJECT_ID,\n           s.MAPPING_ID,\n           w.WORKFLOW_NAME,\n           ti.INSTANCE_NAME AS SESSION_INSTANCE_NAME,\n           s.SESSION_NAME\n    FROM M2R_REP_1053_P01.REP_WORKFLOWS w\n    JOIN M2R_REP_1053_P01.REP_TASK_INST ti\n      ON ti.WORKFLOW_ID = w.WORKFLOW_ID\n     AND ti.TASK_TYPE = 68\n    JOIN M2R_REP_1053_P01.REP_LOAD_SESSIONS s\n      ON s.SESSION_ID = ti.TASK_ID\n    WHERE w.SUBJECT_AREA = 'M2R_DTM'\n      AND w.WORKFLOW_NAME = 'WF_DTM_MMTR'\n),\n\njoiner_instances AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           wm.SUBJECT_AREA,\n           wm.SUBJECT_ID,\n           wm.WORKFLOW_NAME,\n           wm.SESSION_INSTANCE_NAME,\n           wm.SESSION_NAME,\n           wm.MAPPING_ID,\n           m.MAPPING_NAME,\n           wi.INSTANCE_ID,\n           wi.INSTANCE_NAME AS TRANSFORMATION_NAME,\n           wi.WIDGET_ID,\n           wi.WIDGET_TYPE_NAME AS TRANSFORMATION_TYPE,\n           wi.VERSION_NUMBER\n    FROM workflow_mappings wm\n    JOIN M2R_REP_1053_P01.REP_ALL_MAPPINGS m\n      ON m.MAPPING_ID = wm.MAPPING_ID\n     AND m.SUBJECT_AREA = wm.SUBJECT_AREA\n    JOIN M2R_REP_1053_P01.REP_WIDGET_INST wi\n      ON wi.MAPPING_ID = wm.MAPPING_ID\n     AND wi.SUBJECT_ID = wm.SUBJECT_ID\n\n     /* Informatica PowerCenter Joiner transformation */\n     AND wi.WIDGET_TYPE = 12\n),\n\nrelevant_transformations AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER\n    FROM joiner_instances\n),\n\n/*\n    Retrieve all attributes belonging to each Joiner instance.\n\n    The INSTANCE_ID and MAPPING_ID conditions allow this query\n    to support both transformation-level and instance-level\n    attribute records.\n*/\njoiner_attribute_rows AS\n(\n    SELECT rt.SUBJECT_ID,\n           rt.MAPPING_ID,\n           rt.INSTANCE_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           UPPER(TRIM(wa.ATTR_NAME)) AS ATTR_NAME,\n           TRIM(wa.ATTR_VALUE) AS ATTR_VALUE\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_WIDGET_ATTR wa\n      ON wa.WIDGET_ID = rt.WIDGET_ID\n     AND wa.VERSION_NUMBER = rt.VERSION_NUMBER\n     AND (\n            wa.INSTANCE_ID = rt.INSTANCE_ID\n            OR wa.INSTANCE_ID IS NULL\n            OR wa.INSTANCE_ID = 0\n         )\n     AND (\n            wa.MAPPING_ID = rt.MAPPING_ID\n            OR wa.MAPPING_ID IS NULL\n            OR wa.MAPPING_ID = 0\n         )\n),\n\n/*\n    Pivot the Joiner attributes displayed under the\n    Properties and Condition tabs.\n*/\njoiner_properties AS\n(\n    SELECT SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'CACHE DIRECTORY'\n                   THEN ATTR_VALUE\n               END\n           ) AS CACHE_DIRECTORY,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'JOIN CONDITION'\n                   THEN ATTR_VALUE\n               END\n           ) AS JOIN_CONDITION,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'JOIN TYPE'\n                   THEN ATTR_VALUE\n               END\n           ) AS JOIN_TYPE_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'NULL ORDERING IN MASTER',\n                            'NULL ORDER IN MASTER'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS NULL_ORDERING_IN_MASTER_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'NULL ORDERING IN DETAIL',\n                            'NULL ORDER IN DETAIL'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS NULL_ORDERING_IN_DETAIL_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'TRACING LEVEL'\n                   THEN ATTR_VALUE\n               END\n           ) AS TRACING_LEVEL_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'JOINER DATA CACHE SIZE',\n                            'DATA CACHE SIZE'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS JOINER_DATA_CACHE_SIZE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'JOINER INDEX CACHE SIZE',\n                            'INDEX CACHE SIZE'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS JOINER_INDEX_CACHE_SIZE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'SORTED INPUT'\n                   THEN ATTR_VALUE\n               END\n           ) AS SORTED_INPUT_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'MASTER SORT ORDER'\n                   THEN ATTR_VALUE\n               END\n           ) AS MASTER_SORT_ORDER_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'TRANSFORMATION SCOPE'\n                   THEN ATTR_VALUE\n               END\n           ) AS TRANSFORMATION_SCOPE_CODE\n\n    FROM joiner_attribute_rows\n    GROUP BY\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER\n),\n\n/*\n    Metadata Extensions tab\n*/\njoiner_metadata_extensions AS\n(\n    SELECT rt.SUBJECT_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           mdx.METADATA_EXTN_NAME,\n           mdx.METADATA_EXTN_DATA_TYPE,\n           mdx.METADATA_EXTN_VALUE,\n           mdx.PERMISSIONS,\n           mdx.LINE_NO,\n           mdx.DOMAIN_NAME,\n           mdx.DOMAIN_USAGE,\n           mdx.METADATA_EXTN_DESCRIPTION,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NOT NULL\n               THEN LENGTH(mdx.METADATA_EXTN_VALUE)\n           END AS METADATA_EXTENSION_PRECISION,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NULL\n               THEN NULL\n               WHEN mdx.DOMAIN_ID IS NOT NULL\n                 OR mdx.DOMAIN_NAME IS NOT NULL\n               THEN 'YES'\n               ELSE 'NO'\n           END AS REUSABLE\n\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_METADATA_EXTNS mdx\n      ON mdx.SUBJECT_ID = rt.SUBJECT_ID\n     AND mdx.METADATA_EXTN_OBJECT_ID = rt.WIDGET_ID\n     AND mdx.VERSION_NUMBER = rt.VERSION_NUMBER\n),\n\nincoming_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.TO_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.TO_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.FROM_OBJECT_NAME\n               || '.'\n               || pc.FROM_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.TO_OBJECT_INSTANCE_ID\n    WHERE pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n),\n\noutgoing_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.FROM_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.FROM_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.TO_OBJECT_NAME\n               || '.'\n               || pc.TO_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.FROM_OBJECT_INSTANCE_ID\n    WHERE pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.TO_OBJECT_NAME IS NOT NULL\n      AND pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n),\n\nincoming_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM incoming_connections\n),\n\noutgoing_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM outgoing_connections\n),\n\nport_connections AS\n(\n    SELECT k.SUBJECT_ID,\n           k.MAPPING_ID,\n           k.MAPPING_VERSION_NUMBER,\n           k.INSTANCE_ID,\n           k.FIELD_NAME,\n           incoming.PREVIOUS_TRANSFORMATION,\n           outgoing.NEXT_TRANSFORMATION_NAME\n    FROM\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM incoming_connections_distinct\n\n        UNION\n\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM outgoing_connections_distinct\n    ) k\n\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS PREVIOUS_TRANSFORMATION\n        FROM incoming_connections_distinct\n        GROUP BY SUBJECT_ID,\n                 MAPPING_ID,\n                 MAPPING_VERSION_NUMBER,\n                 INSTANCE_ID,\n                 FIELD_NAME\n    ) incoming\n      ON incoming.SUBJECT_ID = k.SUBJECT_ID\n     AND incoming.MAPPING_ID = k.MAPPING_ID\n     AND incoming.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND incoming.INSTANCE_ID = k.INSTANCE_ID\n     AND incoming.FIELD_NAME = k.FIELD_NAME\n\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS NEXT_TRANSFORMATION_NAME\n        FROM outgoing_connections_distinct\n        GROUP BY SUBJECT_ID,\n                 MAPPING_ID,\n                 MAPPING_VERSION_NUMBER,\n                 INSTANCE_ID,\n                 FIELD_NAME\n    ) outgoing\n      ON outgoing.SUBJECT_ID = k.SUBJECT_ID\n     AND outgoing.MAPPING_ID = k.MAPPING_ID\n     AND outgoing.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND outgoing.INSTANCE_ID = k.INSTANCE_ID\n     AND outgoing.FIELD_NAME = k.FIELD_NAME\n)\n\nSELECT DISTINCT\n       ji.SUBJECT_AREA,\n       ji.WORKFLOW_NAME,\n       ji.SESSION_INSTANCE_NAME,\n       ji.SESSION_NAME,\n       ji.MAPPING_NAME,\n\n       /* Transformation tab */\n       ji.TRANSFORMATION_NAME,\n       ji.TRANSFORMATION_TYPE,\n\n       /* Ports tab */\n       wf.FIELD_ORDER AS PORT_ORDER,\n       wf.FIELD_NAME AS PORT_NAME,\n       wf.WGT_DATATYPE AS DATATYPE,\n       wf.WGT_PREC AS PREC,\n       wf.WGT_SCALE AS SCALE,\n\n       /*\n          PORTTYPE is a bit mask:\n          1  = input\n          2  = output\n          4  = master\n          32 = variable\n       */\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 1) = 1 THEN 'YES'\n           ELSE 'NO'\n       END AS I,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 2) = 2 THEN 'YES'\n           ELSE 'NO'\n       END AS O,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 4) = 4 THEN 'YES'\n           ELSE 'NO'\n       END AS M,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 32) = 32 THEN 'YES'\n           ELSE 'NO'\n       END AS V,\n\n       wf.PORTTYPE AS PORTTYPE_CODE,\n\n       /* Properties tab */\n       jp.CACHE_DIRECTORY,\n\n       jp.JOIN_CONDITION,\n\n       jp.JOIN_TYPE_CODE,\n\n       CASE UPPER(TRIM(jp.JOIN_TYPE_CODE))\n           WHEN '0' THEN 'Normal Join'\n           WHEN '1' THEN 'Master Outer Join'\n           WHEN '2' THEN 'Detail Outer Join'\n           WHEN '3' THEN 'Full Outer Join'\n           WHEN 'NORMAL JOIN' THEN 'Normal Join'\n           WHEN 'MASTER OUTER JOIN' THEN 'Master Outer Join'\n           WHEN 'DETAIL OUTER JOIN' THEN 'Detail Outer Join'\n           WHEN 'FULL OUTER JOIN' THEN 'Full Outer Join'\n           WHEN 'FULL OUTER' THEN 'Full Outer Join'\n           WHEN 'MASTER OUTER' THEN 'Master Outer Join'\n           WHEN 'DETAIL OUTER' THEN 'Detail Outer Join'\n           ELSE jp.JOIN_TYPE_CODE\n       END AS JOIN_TYPE,\n\n       jp.NULL_ORDERING_IN_MASTER_CODE,\n\n       CASE UPPER(TRIM(jp.NULL_ORDERING_IN_MASTER_CODE))\n           WHEN '0' THEN 'Null Is Lowest Value'\n           WHEN '1' THEN 'Null Is Highest Value'\n           WHEN 'NULL IS LOWEST VALUE' THEN 'Null Is Lowest Value'\n           WHEN 'NULL IS HIGHEST VALUE' THEN 'Null Is Highest Value'\n           ELSE jp.NULL_ORDERING_IN_MASTER_CODE\n       END AS NULL_ORDERING_IN_MASTER,\n\n       jp.NULL_ORDERING_IN_DETAIL_CODE,\n\n       CASE UPPER(TRIM(jp.NULL_ORDERING_IN_DETAIL_CODE))\n           WHEN '0' THEN 'Null Is Lowest Value'\n           WHEN '1' THEN 'Null Is Highest Value'\n           WHEN 'NULL IS LOWEST VALUE' THEN 'Null Is Lowest Value'\n           WHEN 'NULL IS HIGHEST VALUE' THEN 'Null Is Highest Value'\n           ELSE jp.NULL_ORDERING_IN_DETAIL_CODE\n       END AS NULL_ORDERING_IN_DETAIL,\n\n       jp.TRACING_LEVEL_CODE,\n\n       CASE TRIM(jp.TRACING_LEVEL_CODE)\n           WHEN '1' THEN 'Terse'\n           WHEN '2' THEN 'Normal'\n           WHEN '3' THEN 'Verbose Initialization'\n           WHEN '4' THEN 'Verbose Data'\n           WHEN 'TERSE' THEN 'Terse'\n           WHEN 'NORMAL' THEN 'Normal'\n           WHEN 'VERBOSE INITIALIZATION'\n               THEN 'Verbose Initialization'\n           WHEN 'VERBOSE DATA'\n               THEN 'Verbose Data'\n           ELSE NVL(jp.TRACING_LEVEL_CODE, 'Normal')\n       END AS TRACING_LEVEL,\n\n       NVL(jp.JOINER_DATA_CACHE_SIZE, 'Auto')\n           AS JOINER_DATA_CACHE_SIZE,\n\n       NVL(jp.JOINER_INDEX_CACHE_SIZE, 'Auto')\n           AS JOINER_INDEX_CACHE_SIZE,\n\n       jp.SORTED_INPUT_CODE,\n\n       CASE UPPER(TRIM(jp.SORTED_INPUT_CODE))\n           WHEN '1' THEN 'YES'\n           WHEN '0' THEN 'NO'\n           WHEN 'YES' THEN 'YES'\n           WHEN 'NO' THEN 'NO'\n           WHEN 'TRUE' THEN 'YES'\n           WHEN 'FALSE' THEN 'NO'\n           ELSE jp.SORTED_INPUT_CODE\n       END AS SORTED_INPUT,\n\n       jp.MASTER_SORT_ORDER_CODE,\n\n       CASE UPPER(TRIM(jp.MASTER_SORT_ORDER_CODE))\n           WHEN '0' THEN 'Auto'\n           WHEN '1' THEN 'Ascending'\n           WHEN '2' THEN 'Descending'\n           WHEN 'AUTO' THEN 'Auto'\n           WHEN 'ASCENDING' THEN 'Ascending'\n           WHEN 'DESCENDING' THEN 'Descending'\n           ELSE jp.MASTER_SORT_ORDER_CODE\n       END AS MASTER_SORT_ORDER,\n\n       jp.TRANSFORMATION_SCOPE_CODE,\n\n       CASE UPPER(TRIM(jp.TRANSFORMATION_SCOPE_CODE))\n           WHEN '0' THEN 'All Input'\n           WHEN '1' THEN 'Transaction'\n           WHEN '2' THEN 'Row'\n           WHEN 'ALL INPUT' THEN 'All Input'\n           WHEN 'TRANSACTION' THEN 'Transaction'\n           WHEN 'ROW' THEN 'Row'\n           ELSE jp.TRANSFORMATION_SCOPE_CODE\n       END AS TRANSFORMATION_SCOPE,\n\n       /*\n          Condition tab.\n\n          These three columns are suitable for a simple condition,\n          such as:\n              PRIORUTI_FULL = UTI_FULL_UTI\n\n          JOIN_CONDITION above remains the authoritative value for\n          compound conditions.\n       */\n       CASE\n           WHEN REGEXP_LIKE(\n                    jp.JOIN_CONDITION,\n                    '<=|>=|<>|!=|=|<|>'\n                )\n           THEN TRIM(\n                    REGEXP_SUBSTR(\n                        jp.JOIN_CONDITION,\n                        '^(.*?)(<=|>=|<>|!=|=|<|>)',\n                        1,\n                        1,\n                        NULL,\n                        1\n                    )\n                )\n       END AS CONDITION_MASTER,\n\n       REGEXP_SUBSTR(\n           jp.JOIN_CONDITION,\n           '<=|>=|<>|!=|=|<|>'\n       ) AS CONDITION_OPERATOR,\n\n       CASE\n           WHEN REGEXP_LIKE(\n                    jp.JOIN_CONDITION,\n                    '<=|>=|<>|!=|=|<|>'\n                )\n           THEN TRIM(\n                    REGEXP_REPLACE(\n                        jp.JOIN_CONDITION,\n                        '^.*?(<=|>=|<>|!=|=|<|>)',\n                        ''\n                    )\n                )\n       END AS CONDITION_DETAIL,\n\n       /* Metadata Extensions tab */\n       jme.METADATA_EXTN_NAME AS EXTENSION_NAME,\n       jme.METADATA_EXTN_DATA_TYPE\n           AS EXTENSION_DATATYPE_CODE,\n\n       CASE jme.METADATA_EXTN_DATA_TYPE\n           WHEN 1 THEN 'String'\n           WHEN 2 THEN 'Number'\n           WHEN 3 THEN 'Boolean'\n           ELSE\n               CASE\n                   WHEN jme.METADATA_EXTN_DATA_TYPE IS NULL\n                   THEN NULL\n                   ELSE\n                       'Other ('\n                       || TO_CHAR(jme.METADATA_EXTN_DATA_TYPE)\n                       || ')'\n               END\n       END AS EXTENSION_DATATYPE,\n\n       jme.METADATA_EXTENSION_PRECISION AS EXTENSION_PREC,\n       jme.METADATA_EXTN_VALUE AS EXTENSION_VALUE,\n       jme.REUSABLE,\n       jme.PERMISSIONS AS EXTENSION_PERMISSIONS,\n       jme.LINE_NO AS EXTENSION_LINE_NO,\n       jme.DOMAIN_NAME AS EXTENSION_DOMAIN_NAME,\n       jme.DOMAIN_USAGE AS EXTENSION_DOMAIN_USAGE,\n       jme.METADATA_EXTN_DESCRIPTION AS EXTENSION_DESCRIPTION,\n\n       /* Connected transformation ports */\n       pc.PREVIOUS_TRANSFORMATION,\n       pc.NEXT_TRANSFORMATION_NAME\n\nFROM joiner_instances ji\n\nJOIN M2R_REP_1053_P01.OPB_WIDGET_FIELD wf\n  ON wf.WIDGET_ID = ji.WIDGET_ID\n AND wf.VERSION_NUMBER = ji.VERSION_NUMBER\n\nLEFT JOIN joiner_properties jp\n  ON jp.SUBJECT_ID = ji.SUBJECT_ID\n AND jp.MAPPING_ID = ji.MAPPING_ID\n AND jp.INSTANCE_ID = ji.INSTANCE_ID\n AND jp.WIDGET_ID = ji.WIDGET_ID\n AND jp.VERSION_NUMBER = ji.VERSION_NUMBER\n\nLEFT JOIN joiner_metadata_extensions jme\n  ON jme.SUBJECT_ID = ji.SUBJECT_ID\n AND jme.WIDGET_ID = ji.WIDGET_ID\n AND jme.VERSION_NUMBER = ji.VERSION_NUMBER\n\nLEFT JOIN port_connections pc\n  ON pc.SUBJECT_ID = ji.SUBJECT_ID\n AND pc.MAPPING_ID = ji.MAPPING_ID\n AND pc.MAPPING_VERSION_NUMBER = ji.VERSION_NUMBER\n AND pc.INSTANCE_ID = ji.INSTANCE_ID\n AND pc.FIELD_NAME = wf.FIELD_NAME\n\nORDER BY\n       ji.SUBJECT_AREA,\n       ji.WORKFLOW_NAME,\n       ji.SESSION_INSTANCE_NAME,\n       ji.SESSION_NAME,\n       ji.MAPPING_NAME,\n       ji.TRANSFORMATION_NAME,\n       wf.FIELD_ORDER,\n       wf.FIELD_NAME,\n       jme.METADATA_EXTN_NAME,\n       jme.LINE_NO;"}, 'SOURCEQUALIFIER': {'label': 'source Qualifier', 'sql': "WITH workflow_mappings AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           s.SUBJECT_AREA,\n           s.SUBJECT_ID,\n           s.MAPPING_ID,\n           w.WORKFLOW_NAME,\n           ti.INSTANCE_NAME AS SESSION_INSTANCE_NAME,\n           s.SESSION_NAME\n    FROM M2R_REP_1053_P01.REP_WORKFLOWS w\n    JOIN M2R_REP_1053_P01.REP_TASK_INST ti\n      ON ti.WORKFLOW_ID = w.WORKFLOW_ID\n     AND ti.TASK_TYPE = 68\n    JOIN M2R_REP_1053_P01.REP_LOAD_SESSIONS s\n      ON s.SESSION_ID = ti.TASK_ID\n    WHERE w.SUBJECT_AREA = 'M2R_DTM'\n      AND w.WORKFLOW_NAME = 'WF_DTM_MMTR'\n),\nsource_qualifier_instances AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           wm.SUBJECT_AREA,\n           wm.SUBJECT_ID,\n           wm.WORKFLOW_NAME,\n           wm.SESSION_INSTANCE_NAME,\n           wm.SESSION_NAME,\n           wm.MAPPING_ID,\n           m.MAPPING_NAME,\n           wi.INSTANCE_ID,\n           wi.INSTANCE_NAME AS TRANSFORMATION_NAME,\n           wi.WIDGET_ID,\n           wi.WIDGET_TYPE,\n           wi.WIDGET_TYPE_NAME AS TRANSFORMATION_TYPE,\n           wi.VERSION_NUMBER\n    FROM workflow_mappings wm\n    JOIN M2R_REP_1053_P01.REP_ALL_MAPPINGS m\n      ON m.MAPPING_ID = wm.MAPPING_ID\n     AND m.SUBJECT_AREA = wm.SUBJECT_AREA\n    JOIN M2R_REP_1053_P01.REP_WIDGET_INST wi\n      ON wi.MAPPING_ID = wm.MAPPING_ID\n     AND wi.SUBJECT_ID = wm.SUBJECT_ID\n     AND wi.WIDGET_TYPE = 3\n),\nrelevant_transformations AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           WIDGET_TYPE,\n           VERSION_NUMBER\n    FROM source_qualifier_instances\n),\nsource_qualifier_attribute_rows AS\n(\n    SELECT rt.SUBJECT_ID,\n           rt.MAPPING_ID,\n           rt.INSTANCE_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           wa.ATTR_ID,\n           UPPER(TRIM(wa.ATTR_NAME)) AS ATTR_NAME,\n           TRIM(wa.ATTR_VALUE) AS ATTR_VALUE\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_WIDGET_ATTR wa\n      ON wa.WIDGET_ID = rt.WIDGET_ID\n     AND wa.VERSION_NUMBER = rt.VERSION_NUMBER\n     AND (\n            wa.WIDGET_TYPE = rt.WIDGET_TYPE\n            OR wa.WIDGET_TYPE IS NULL\n         )\n     AND (\n            wa.INSTANCE_ID = rt.INSTANCE_ID\n            OR wa.INSTANCE_ID IS NULL\n            OR wa.INSTANCE_ID = 0\n         )\n     AND (\n            wa.MAPPING_ID = rt.MAPPING_ID\n            OR wa.MAPPING_ID IS NULL\n            OR wa.MAPPING_ID = 0\n         )\n),\nsource_qualifier_properties AS\n(\n    SELECT SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'SQL QUERY',\n                            'SQL OVERRIDE',\n                            'SQL QUERY OVERRIDE'\n                        )\n                     OR ATTR_ID = 1\n                   THEN ATTR_VALUE\n               END\n           ) AS SQL_QUERY,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'USER DEFINED JOIN',\n                            'USER-DEFINED JOIN'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS USER_DEFINED_JOIN,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'SOURCE FILTER'\n                   THEN ATTR_VALUE\n               END\n           ) AS SOURCE_FILTER,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'NUMBER OF SORTED PORTS',\n                            'NUMBER OF SORTED COLUMNS'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS NUMBER_OF_SORTED_PORTS,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'TRACING LEVEL'\n                   THEN ATTR_VALUE\n               END\n           ) AS TRACING_LEVEL_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'SELECT DISTINCT',\n                            'SELECT DISTINCT OPTION'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS SELECT_DISTINCT_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN ('PRE SQL', 'PRE-SQL')\n                   THEN ATTR_VALUE\n               END\n           ) AS PRE_SQL,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN ('POST SQL', 'POST-SQL')\n                   THEN ATTR_VALUE\n               END\n           ) AS POST_SQL,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'OUTPUT IS DETERMINISTIC',\n                            'OUTPUT IS DETERMINISTIC.'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS OUTPUT_DETERMINISTIC_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'OUTPUT IS REPEATABLE',\n                            'OUTPUT IS REPEATABLE.'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS OUTPUT_REPEATABLE_CODE\n    FROM source_qualifier_attribute_rows\n    GROUP BY\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER\n),\nsource_qualifier_metadata_extensions AS\n(\n    SELECT rt.SUBJECT_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           mdx.METADATA_EXTN_NAME,\n           mdx.METADATA_EXTN_DATA_TYPE,\n           mdx.METADATA_EXTN_VALUE,\n           mdx.PERMISSIONS,\n           mdx.LINE_NO,\n           mdx.DOMAIN_NAME,\n           mdx.DOMAIN_USAGE,\n           mdx.METADATA_EXTN_DESCRIPTION,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NOT NULL\n               THEN LENGTH(mdx.METADATA_EXTN_VALUE)\n           END AS METADATA_EXTENSION_PRECISION,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NULL\n               THEN NULL\n               WHEN mdx.DOMAIN_ID IS NOT NULL\n                 OR mdx.DOMAIN_NAME IS NOT NULL\n               THEN 'YES'\n               ELSE 'NO'\n           END AS REUSABLE\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_METADATA_EXTNS mdx\n      ON mdx.SUBJECT_ID = rt.SUBJECT_ID\n     AND mdx.METADATA_EXTN_OBJECT_ID = rt.WIDGET_ID\n     AND mdx.VERSION_NUMBER = rt.VERSION_NUMBER\n),\nincoming_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.TO_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.TO_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.FROM_OBJECT_NAME,\n           pc.FROM_OBJECT_FIELD_NAME,\n           pc.FROM_OBJECT_NAME\n               || '.'\n               || pc.FROM_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.TO_OBJECT_INSTANCE_ID\n    WHERE pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n),\noutgoing_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.FROM_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.FROM_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.TO_OBJECT_NAME,\n           pc.TO_OBJECT_FIELD_NAME,\n           pc.TO_OBJECT_NAME\n               || '.'\n               || pc.TO_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.FROM_OBJECT_INSTANCE_ID\n    WHERE pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.TO_OBJECT_NAME IS NOT NULL\n      AND pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n),\nincoming_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           FROM_OBJECT_NAME,\n           FROM_OBJECT_FIELD_NAME,\n           CONNECTED_PORT\n    FROM incoming_connections\n),\noutgoing_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           TO_OBJECT_NAME,\n           TO_OBJECT_FIELD_NAME,\n           CONNECTED_PORT\n    FROM outgoing_connections\n),\nassociated_sources AS\n(\n    SELECT SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           LISTAGG(FROM_OBJECT_NAME, ', ')\n               WITHIN GROUP (ORDER BY FROM_OBJECT_NAME)\n               AS ASSOCIATED_SOURCE_DEFINITIONS\n    FROM\n    (\n        SELECT DISTINCT\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FROM_OBJECT_NAME\n        FROM incoming_connections_distinct\n        WHERE FROM_OBJECT_NAME IS NOT NULL\n    )\n    GROUP BY\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID\n),\nport_connections AS\n(\n    SELECT k.SUBJECT_ID,\n           k.MAPPING_ID,\n           k.MAPPING_VERSION_NUMBER,\n           k.INSTANCE_ID,\n           k.FIELD_NAME,\n           incoming.PREVIOUS_TRANSFORMATION,\n           outgoing.NEXT_TRANSFORMATION_NAME\n    FROM\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM incoming_connections_distinct\n\n        UNION\n\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM outgoing_connections_distinct\n    ) k\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS PREVIOUS_TRANSFORMATION\n        FROM incoming_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) incoming\n      ON incoming.SUBJECT_ID = k.SUBJECT_ID\n     AND incoming.MAPPING_ID = k.MAPPING_ID\n     AND incoming.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND incoming.INSTANCE_ID = k.INSTANCE_ID\n     AND incoming.FIELD_NAME = k.FIELD_NAME\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS NEXT_TRANSFORMATION_NAME\n        FROM outgoing_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) outgoing\n      ON outgoing.SUBJECT_ID = k.SUBJECT_ID\n     AND outgoing.MAPPING_ID = k.MAPPING_ID\n     AND outgoing.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND outgoing.INSTANCE_ID = k.INSTANCE_ID\n     AND outgoing.FIELD_NAME = k.FIELD_NAME\n)\nSELECT DISTINCT\n       sqi.SUBJECT_AREA,\n       sqi.WORKFLOW_NAME,\n       sqi.SESSION_INSTANCE_NAME,\n       sqi.SESSION_NAME,\n       sqi.MAPPING_NAME,\n\n       sqi.TRANSFORMATION_NAME,\n       sqi.TRANSFORMATION_TYPE,\n\n       wf.FIELD_ORDER AS PORT_ORDER,\n       wf.FIELD_NAME AS PORT_NAME,\n       wf.WGT_DATATYPE AS DATATYPE,\n       wf.WGT_PREC AS PREC,\n       wf.WGT_SCALE AS SCALE,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 1) = 1 THEN 'YES'\n           ELSE 'NO'\n       END AS I,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 2) = 2 THEN 'YES'\n           ELSE 'NO'\n       END AS O,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 32) = 32 THEN 'YES'\n           ELSE 'NO'\n       END AS V,\n\n       wf.PORTTYPE AS PORTTYPE_CODE,\n\n       sqp.SQL_QUERY,\n       sqp.USER_DEFINED_JOIN,\n       sqp.SOURCE_FILTER,\n\n       NVL(sqp.NUMBER_OF_SORTED_PORTS, '0')\n           AS NUMBER_OF_SORTED_PORTS,\n\n       CASE\n           WHEN sqp.TRACING_LEVEL_CODE IS NULL\n           THEN 'Normal'\n           WHEN UPPER(TRIM(sqp.TRACING_LEVEL_CODE)) = '1'\n           THEN 'Terse'\n           WHEN UPPER(TRIM(sqp.TRACING_LEVEL_CODE)) = '2'\n           THEN 'Normal'\n           WHEN UPPER(TRIM(sqp.TRACING_LEVEL_CODE)) = '3'\n           THEN 'Verbose Initialization'\n           WHEN UPPER(TRIM(sqp.TRACING_LEVEL_CODE)) = '4'\n           THEN 'Verbose Data'\n           WHEN UPPER(TRIM(sqp.TRACING_LEVEL_CODE)) = 'TERSE'\n           THEN 'Terse'\n           WHEN UPPER(TRIM(sqp.TRACING_LEVEL_CODE)) = 'NORMAL'\n           THEN 'Normal'\n           WHEN UPPER(TRIM(sqp.TRACING_LEVEL_CODE)) =\n                'VERBOSE INITIALIZATION'\n           THEN 'Verbose Initialization'\n           WHEN UPPER(TRIM(sqp.TRACING_LEVEL_CODE)) =\n                'VERBOSE DATA'\n           THEN 'Verbose Data'\n           ELSE\n               'Unknown ('\n               || sqp.TRACING_LEVEL_CODE\n               || ')'\n       END AS TRACING_LEVEL,\n\n       CASE\n           WHEN sqp.SELECT_DISTINCT_CODE IS NULL\n           THEN 'NO'\n           WHEN UPPER(TRIM(sqp.SELECT_DISTINCT_CODE))\n                IN ('1', 'YES', 'Y', 'TRUE')\n           THEN 'YES'\n           WHEN UPPER(TRIM(sqp.SELECT_DISTINCT_CODE))\n                IN ('0', 'NO', 'N', 'FALSE')\n           THEN 'NO'\n           ELSE sqp.SELECT_DISTINCT_CODE\n       END AS SELECT_DISTINCT,\n\n       sqp.PRE_SQL,\n       sqp.POST_SQL,\n\n       CASE\n           WHEN sqp.OUTPUT_DETERMINISTIC_CODE IS NULL\n           THEN 'NO'\n           WHEN UPPER(TRIM(sqp.OUTPUT_DETERMINISTIC_CODE))\n                IN ('1', 'YES', 'Y', 'TRUE')\n           THEN 'YES'\n           WHEN UPPER(TRIM(sqp.OUTPUT_DETERMINISTIC_CODE))\n                IN ('0', 'NO', 'N', 'FALSE')\n           THEN 'NO'\n           ELSE sqp.OUTPUT_DETERMINISTIC_CODE\n       END AS OUTPUT_IS_DETERMINISTIC,\n\n       CASE\n           WHEN sqp.OUTPUT_REPEATABLE_CODE IS NULL\n           THEN 'Never'\n           WHEN UPPER(TRIM(sqp.OUTPUT_REPEATABLE_CODE)) = '0'\n           THEN 'Never'\n           WHEN UPPER(TRIM(sqp.OUTPUT_REPEATABLE_CODE)) = '1'\n           THEN 'Always'\n           WHEN UPPER(TRIM(sqp.OUTPUT_REPEATABLE_CODE)) = '2'\n           THEN 'Within Transaction'\n           WHEN UPPER(TRIM(sqp.OUTPUT_REPEATABLE_CODE)) = 'NEVER'\n           THEN 'Never'\n           WHEN UPPER(TRIM(sqp.OUTPUT_REPEATABLE_CODE)) = 'ALWAYS'\n           THEN 'Always'\n           WHEN UPPER(TRIM(sqp.OUTPUT_REPEATABLE_CODE)) =\n                'WITHIN TRANSACTION'\n           THEN 'Within Transaction'\n           ELSE sqp.OUTPUT_REPEATABLE_CODE\n       END AS OUTPUT_IS_REPEATABLE,\n\n       src.ASSOCIATED_SOURCE_DEFINITIONS,\n\n       sme.METADATA_EXTN_NAME AS EXTENSION_NAME,\n       sme.METADATA_EXTN_DATA_TYPE AS EXTENSION_DATATYPE_CODE,\n\n       CASE sme.METADATA_EXTN_DATA_TYPE\n           WHEN 1 THEN 'String'\n           WHEN 2 THEN 'Number'\n           WHEN 3 THEN 'Boolean'\n           ELSE\n               CASE\n                   WHEN sme.METADATA_EXTN_DATA_TYPE IS NULL\n                   THEN NULL\n                   ELSE\n                       'Other ('\n                       || TO_CHAR(sme.METADATA_EXTN_DATA_TYPE)\n                       || ')'\n               END\n       END AS EXTENSION_DATATYPE,\n\n       sme.METADATA_EXTENSION_PRECISION AS EXTENSION_PREC,\n       sme.METADATA_EXTN_VALUE AS EXTENSION_VALUE,\n       sme.REUSABLE,\n       sme.PERMISSIONS AS EXTENSION_PERMISSIONS,\n       sme.LINE_NO AS EXTENSION_LINE_NO,\n       sme.DOMAIN_NAME AS EXTENSION_DOMAIN_NAME,\n       sme.DOMAIN_USAGE AS EXTENSION_DOMAIN_USAGE,\n       sme.METADATA_EXTN_DESCRIPTION AS EXTENSION_DESCRIPTION,\n\n       pc.PREVIOUS_TRANSFORMATION,\n       pc.NEXT_TRANSFORMATION_NAME\n\nFROM source_qualifier_instances sqi\n\nJOIN M2R_REP_1053_P01.OPB_WIDGET_FIELD wf\n  ON wf.WIDGET_ID = sqi.WIDGET_ID\n AND wf.VERSION_NUMBER = sqi.VERSION_NUMBER\n\nLEFT JOIN source_qualifier_properties sqp\n  ON sqp.SUBJECT_ID = sqi.SUBJECT_ID\n AND sqp.MAPPING_ID = sqi.MAPPING_ID\n AND sqp.INSTANCE_ID = sqi.INSTANCE_ID\n AND sqp.WIDGET_ID = sqi.WIDGET_ID\n AND sqp.VERSION_NUMBER = sqi.VERSION_NUMBER\n\nLEFT JOIN associated_sources src\n  ON src.SUBJECT_ID = sqi.SUBJECT_ID\n AND src.MAPPING_ID = sqi.MAPPING_ID\n AND src.MAPPING_VERSION_NUMBER = sqi.VERSION_NUMBER\n AND src.INSTANCE_ID = sqi.INSTANCE_ID\n\nLEFT JOIN source_qualifier_metadata_extensions sme\n  ON sme.SUBJECT_ID = sqi.SUBJECT_ID\n AND sme.WIDGET_ID = sqi.WIDGET_ID\n AND sme.VERSION_NUMBER = sqi.VERSION_NUMBER\n\nLEFT JOIN port_connections pc\n  ON pc.SUBJECT_ID = sqi.SUBJECT_ID\n AND pc.MAPPING_ID = sqi.MAPPING_ID\n AND pc.MAPPING_VERSION_NUMBER = sqi.VERSION_NUMBER\n AND pc.INSTANCE_ID = sqi.INSTANCE_ID\n AND pc.FIELD_NAME = wf.FIELD_NAME\n\nORDER BY\n       sqi.SUBJECT_AREA,\n       sqi.WORKFLOW_NAME,\n       sqi.SESSION_INSTANCE_NAME,\n       sqi.SESSION_NAME,\n       sqi.MAPPING_NAME,\n       sqi.TRANSFORMATION_NAME,\n       wf.FIELD_ORDER,\n       wf.FIELD_NAME,\n       sme.METADATA_EXTN_NAME,\n       sme.LINE_NO;"}, 'SORTER': {'label': 'Sorter', 'sql': "WITH workflow_mappings AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           s.SUBJECT_AREA,\n           s.SUBJECT_ID,\n           s.MAPPING_ID,\n           w.WORKFLOW_NAME,\n           ti.INSTANCE_NAME AS SESSION_INSTANCE_NAME,\n           s.SESSION_NAME\n    FROM M2R_REP_1053_P01.REP_WORKFLOWS w\n    JOIN M2R_REP_1053_P01.REP_TASK_INST ti\n      ON ti.WORKFLOW_ID = w.WORKFLOW_ID\n     AND ti.TASK_TYPE = 68\n    JOIN M2R_REP_1053_P01.REP_LOAD_SESSIONS s\n      ON s.SESSION_ID = ti.TASK_ID\n    WHERE w.SUBJECT_AREA = 'M2R_DTM'\n      AND w.WORKFLOW_NAME = 'WF_DTM_MMTR'\n),\nsorter_instances AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           wm.SUBJECT_AREA,\n           wm.SUBJECT_ID,\n           wm.WORKFLOW_NAME,\n           wm.SESSION_INSTANCE_NAME,\n           wm.SESSION_NAME,\n           wm.MAPPING_ID,\n           m.MAPPING_NAME,\n           wi.INSTANCE_ID,\n           wi.INSTANCE_NAME AS TRANSFORMATION_NAME,\n           wi.WIDGET_ID,\n           wi.WIDGET_TYPE,\n           wi.WIDGET_TYPE_NAME AS TRANSFORMATION_TYPE,\n           wi.VERSION_NUMBER\n    FROM workflow_mappings wm\n    JOIN M2R_REP_1053_P01.REP_ALL_MAPPINGS m\n      ON m.MAPPING_ID = wm.MAPPING_ID\n     AND m.SUBJECT_AREA = wm.SUBJECT_AREA\n    JOIN M2R_REP_1053_P01.REP_WIDGET_INST wi\n      ON wi.MAPPING_ID = wm.MAPPING_ID\n     AND wi.SUBJECT_ID = wm.SUBJECT_ID\n     AND UPPER(TRIM(wi.WIDGET_TYPE_NAME)) = 'SORTER'\n),\nrelevant_transformations AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           WIDGET_TYPE,\n           VERSION_NUMBER\n    FROM sorter_instances\n),\nsorter_attribute_rows AS\n(\n    SELECT rt.SUBJECT_ID,\n           rt.MAPPING_ID,\n           rt.INSTANCE_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           wa.ATTR_ID,\n           UPPER(TRIM(wa.ATTR_NAME)) AS ATTR_NAME,\n           TRIM(wa.ATTR_VALUE) AS ATTR_VALUE\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_WIDGET_ATTR wa\n      ON wa.WIDGET_ID = rt.WIDGET_ID\n     AND wa.VERSION_NUMBER = rt.VERSION_NUMBER\n     AND (\n            wa.WIDGET_TYPE = rt.WIDGET_TYPE\n            OR wa.WIDGET_TYPE IS NULL\n         )\n     AND (\n            wa.INSTANCE_ID = rt.INSTANCE_ID\n            OR wa.INSTANCE_ID IS NULL\n            OR wa.INSTANCE_ID = 0\n         )\n     AND (\n            wa.MAPPING_ID = rt.MAPPING_ID\n            OR wa.MAPPING_ID IS NULL\n            OR wa.MAPPING_ID = 0\n         )\n),\nsorter_properties AS\n(\n    SELECT SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'SORTER CACHE SIZE',\n                            'SORTER DATA CACHE SIZE',\n                            'CACHE SIZE'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS SORTER_CACHE_SIZE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'CASE SENSITIVE',\n                            'CASE-SENSITIVE'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS CASE_SENSITIVE_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'WORK DIRECTORY',\n                            'WORKING DIRECTORY'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS WORK_DIRECTORY,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'DISTINCT',\n                            'DISTINCT OUTPUT ROWS'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS DISTINCT_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'TRACING LEVEL'\n                   THEN ATTR_VALUE\n               END\n           ) AS TRACING_LEVEL_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'NULL TREATED LOW',\n                            'NULL TREATED AS LOW',\n                            'NULL IS LOWEST VALUE'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS NULL_TREATED_LOW_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'TRANSFORMATION SCOPE'\n                   THEN ATTR_VALUE\n               END\n           ) AS TRANSFORMATION_SCOPE_CODE\n\n    FROM sorter_attribute_rows\n    GROUP BY\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER\n),\nsorter_metadata_extensions AS\n(\n    SELECT rt.SUBJECT_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           mdx.METADATA_EXTN_NAME,\n           mdx.METADATA_EXTN_DATA_TYPE,\n           mdx.METADATA_EXTN_VALUE,\n           mdx.PERMISSIONS,\n           mdx.LINE_NO,\n           mdx.DOMAIN_NAME,\n           mdx.DOMAIN_USAGE,\n           mdx.METADATA_EXTN_DESCRIPTION,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NOT NULL\n               THEN LENGTH(mdx.METADATA_EXTN_VALUE)\n           END AS METADATA_EXTENSION_PRECISION,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NULL\n               THEN NULL\n               WHEN mdx.DOMAIN_ID IS NOT NULL\n                 OR mdx.DOMAIN_NAME IS NOT NULL\n               THEN 'YES'\n               ELSE 'NO'\n           END AS REUSABLE\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_METADATA_EXTNS mdx\n      ON mdx.SUBJECT_ID = rt.SUBJECT_ID\n     AND mdx.METADATA_EXTN_OBJECT_ID = rt.WIDGET_ID\n     AND mdx.VERSION_NUMBER = rt.VERSION_NUMBER\n),\nincoming_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.TO_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.TO_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.FROM_OBJECT_NAME\n               || '.'\n               || pc.FROM_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.TO_OBJECT_INSTANCE_ID\n    WHERE pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n),\noutgoing_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.FROM_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.FROM_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.TO_OBJECT_NAME\n               || '.'\n               || pc.TO_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.FROM_OBJECT_INSTANCE_ID\n    WHERE pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.TO_OBJECT_NAME IS NOT NULL\n      AND pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n),\nincoming_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM incoming_connections\n),\noutgoing_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM outgoing_connections\n),\nport_connections AS\n(\n    SELECT k.SUBJECT_ID,\n           k.MAPPING_ID,\n           k.MAPPING_VERSION_NUMBER,\n           k.INSTANCE_ID,\n           k.FIELD_NAME,\n           incoming.PREVIOUS_TRANSFORMATION,\n           outgoing.NEXT_TRANSFORMATION_NAME\n    FROM\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM incoming_connections_distinct\n\n        UNION\n\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM outgoing_connections_distinct\n    ) k\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS PREVIOUS_TRANSFORMATION\n        FROM incoming_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) incoming\n      ON incoming.SUBJECT_ID = k.SUBJECT_ID\n     AND incoming.MAPPING_ID = k.MAPPING_ID\n     AND incoming.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND incoming.INSTANCE_ID = k.INSTANCE_ID\n     AND incoming.FIELD_NAME = k.FIELD_NAME\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS NEXT_TRANSFORMATION_NAME\n        FROM outgoing_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) outgoing\n      ON outgoing.SUBJECT_ID = k.SUBJECT_ID\n     AND outgoing.MAPPING_ID = k.MAPPING_ID\n     AND outgoing.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND outgoing.INSTANCE_ID = k.INSTANCE_ID\n     AND outgoing.FIELD_NAME = k.FIELD_NAME\n)\nSELECT DISTINCT\n       si.SUBJECT_AREA,\n       si.WORKFLOW_NAME,\n       si.SESSION_INSTANCE_NAME,\n       si.SESSION_NAME,\n       si.MAPPING_NAME,\n\n       /* Transformation tab */\n       si.TRANSFORMATION_NAME,\n       si.TRANSFORMATION_TYPE,\n\n       /* Ports tab */\n       wf.FIELD_ORDER AS PORT_ORDER,\n       wf.FIELD_NAME AS PORT_NAME,\n       wf.WGT_DATATYPE AS DATATYPE,\n       wf.WGT_PREC AS PREC,\n       wf.WGT_SCALE AS SCALE,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 1) = 1\n           THEN 'YES'\n           ELSE 'NO'\n       END AS I,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 2) = 2\n           THEN 'YES'\n           ELSE 'NO'\n       END AS O,\n\n       CASE\n           WHEN wf.PROPERTY IN (1, 2)\n           THEN 'YES'\n           ELSE 'NO'\n       END AS SORT_KEY,\n\n       CASE\n           WHEN wf.PROPERTY = 1\n           THEN 'Ascending'\n           WHEN wf.PROPERTY = 2\n           THEN 'Descending'\n           ELSE '- N/A -'\n       END AS SORT_DIRECTION,\n\n       wf.PORTTYPE AS PORTTYPE_CODE,\n       wf.PROPERTY AS PORT_PROPERTY_CODE,\n\n       /* Properties tab */\n       NVL(sp.SORTER_CACHE_SIZE, 'Auto')\n           AS SORTER_CACHE_SIZE,\n\n       CASE\n           WHEN sp.CASE_SENSITIVE_CODE IS NULL\n           THEN 'NO'\n           WHEN UPPER(TRIM(sp.CASE_SENSITIVE_CODE))\n                IN ('1', 'YES', 'Y', 'TRUE')\n           THEN 'YES'\n           WHEN UPPER(TRIM(sp.CASE_SENSITIVE_CODE))\n                IN ('0', 'NO', 'N', 'FALSE')\n           THEN 'NO'\n           ELSE sp.CASE_SENSITIVE_CODE\n       END AS CASE_SENSITIVE,\n\n       sp.WORK_DIRECTORY,\n\n       CASE\n           WHEN sp.DISTINCT_CODE IS NULL\n           THEN 'NO'\n           WHEN UPPER(TRIM(sp.DISTINCT_CODE))\n                IN ('1', 'YES', 'Y', 'TRUE')\n           THEN 'YES'\n           WHEN UPPER(TRIM(sp.DISTINCT_CODE))\n                IN ('0', 'NO', 'N', 'FALSE')\n           THEN 'NO'\n           ELSE sp.DISTINCT_CODE\n       END AS DISTINCT_ROWS,\n\n       CASE\n           WHEN sp.TRACING_LEVEL_CODE IS NULL\n           THEN 'Normal'\n           WHEN UPPER(TRIM(sp.TRACING_LEVEL_CODE)) = '1'\n           THEN 'Terse'\n           WHEN UPPER(TRIM(sp.TRACING_LEVEL_CODE)) = '2'\n           THEN 'Normal'\n           WHEN UPPER(TRIM(sp.TRACING_LEVEL_CODE)) = '3'\n           THEN 'Verbose Initialization'\n           WHEN UPPER(TRIM(sp.TRACING_LEVEL_CODE)) = '4'\n           THEN 'Verbose Data'\n           WHEN UPPER(TRIM(sp.TRACING_LEVEL_CODE)) = 'TERSE'\n           THEN 'Terse'\n           WHEN UPPER(TRIM(sp.TRACING_LEVEL_CODE)) = 'NORMAL'\n           THEN 'Normal'\n           WHEN UPPER(TRIM(sp.TRACING_LEVEL_CODE)) =\n                'VERBOSE INITIALIZATION'\n           THEN 'Verbose Initialization'\n           WHEN UPPER(TRIM(sp.TRACING_LEVEL_CODE)) =\n                'VERBOSE DATA'\n           THEN 'Verbose Data'\n           ELSE\n               'Unknown ('\n               || sp.TRACING_LEVEL_CODE\n               || ')'\n       END AS TRACING_LEVEL,\n\n       CASE\n           WHEN sp.NULL_TREATED_LOW_CODE IS NULL\n           THEN 'NO'\n           WHEN UPPER(TRIM(sp.NULL_TREATED_LOW_CODE))\n                IN ('1', 'YES', 'Y', 'TRUE')\n           THEN 'YES'\n           WHEN UPPER(TRIM(sp.NULL_TREATED_LOW_CODE))\n                IN ('0', 'NO', 'N', 'FALSE')\n           THEN 'NO'\n           ELSE sp.NULL_TREATED_LOW_CODE\n       END AS NULL_TREATED_LOW,\n\n       CASE\n           WHEN sp.TRANSFORMATION_SCOPE_CODE IS NULL\n           THEN 'All Input'\n           WHEN UPPER(TRIM(sp.TRANSFORMATION_SCOPE_CODE)) = '0'\n           THEN 'All Input'\n           WHEN UPPER(TRIM(sp.TRANSFORMATION_SCOPE_CODE)) = '1'\n           THEN 'Transaction'\n           WHEN UPPER(TRIM(sp.TRANSFORMATION_SCOPE_CODE)) = '2'\n           THEN 'Row'\n           WHEN UPPER(TRIM(sp.TRANSFORMATION_SCOPE_CODE)) =\n                'ALL INPUT'\n           THEN 'All Input'\n           WHEN UPPER(TRIM(sp.TRANSFORMATION_SCOPE_CODE)) =\n                'TRANSACTION'\n           THEN 'Transaction'\n           WHEN UPPER(TRIM(sp.TRANSFORMATION_SCOPE_CODE)) = 'ROW'\n           THEN 'Row'\n           ELSE sp.TRANSFORMATION_SCOPE_CODE\n       END AS TRANSFORMATION_SCOPE,\n\n       /* Metadata Extensions tab */\n       sme.METADATA_EXTN_NAME AS EXTENSION_NAME,\n       sme.METADATA_EXTN_DATA_TYPE AS EXTENSION_DATATYPE_CODE,\n\n       CASE sme.METADATA_EXTN_DATA_TYPE\n           WHEN 1 THEN 'String'\n           WHEN 2 THEN 'Number'\n           WHEN 3 THEN 'Boolean'\n           ELSE\n               CASE\n                   WHEN sme.METADATA_EXTN_DATA_TYPE IS NULL\n                   THEN NULL\n                   ELSE\n                       'Other ('\n                       || TO_CHAR(sme.METADATA_EXTN_DATA_TYPE)\n                       || ')'\n               END\n       END AS EXTENSION_DATATYPE,\n\n       sme.METADATA_EXTENSION_PRECISION AS EXTENSION_PREC,\n       sme.METADATA_EXTN_VALUE AS EXTENSION_VALUE,\n       sme.REUSABLE,\n       sme.PERMISSIONS AS EXTENSION_PERMISSIONS,\n       sme.LINE_NO AS EXTENSION_LINE_NO,\n       sme.DOMAIN_NAME AS EXTENSION_DOMAIN_NAME,\n       sme.DOMAIN_USAGE AS EXTENSION_DOMAIN_USAGE,\n       sme.METADATA_EXTN_DESCRIPTION AS EXTENSION_DESCRIPTION,\n\n       /* Connected transformation ports */\n       pc.PREVIOUS_TRANSFORMATION,\n       pc.NEXT_TRANSFORMATION_NAME\n\nFROM sorter_instances si\n\nJOIN M2R_REP_1053_P01.REP_WIDGET_FIELD wf\n  ON wf.WIDGET_ID = si.WIDGET_ID\n AND wf.VERSION_NUMBER = si.VERSION_NUMBER\n\nLEFT JOIN sorter_properties sp\n  ON sp.SUBJECT_ID = si.SUBJECT_ID\n AND sp.MAPPING_ID = si.MAPPING_ID\n AND sp.INSTANCE_ID = si.INSTANCE_ID\n AND sp.WIDGET_ID = si.WIDGET_ID\n AND sp.VERSION_NUMBER = si.VERSION_NUMBER\n\nLEFT JOIN sorter_metadata_extensions sme\n  ON sme.SUBJECT_ID = si.SUBJECT_ID\n AND sme.WIDGET_ID = si.WIDGET_ID\n AND sme.VERSION_NUMBER = si.VERSION_NUMBER\n\nLEFT JOIN port_connections pc\n  ON pc.SUBJECT_ID = si.SUBJECT_ID\n AND pc.MAPPING_ID = si.MAPPING_ID\n AND pc.MAPPING_VERSION_NUMBER = si.VERSION_NUMBER\n AND pc.INSTANCE_ID = si.INSTANCE_ID\n AND pc.FIELD_NAME = wf.FIELD_NAME\n\nORDER BY\n       si.SUBJECT_AREA,\n       si.WORKFLOW_NAME,\n       si.SESSION_INSTANCE_NAME,\n       si.SESSION_NAME,\n       si.MAPPING_NAME,\n       si.TRANSFORMATION_NAME,\n       wf.FIELD_ORDER,\n       wf.FIELD_NAME,\n       sme.METADATA_EXTN_NAME,\n       sme.LINE_NO;"}, 'SOURCEDEFINITION': {'label': 'Source definition', 'sql': "WITH workflow_mappings AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           s.SUBJECT_AREA,\n           s.SUBJECT_ID,\n           s.MAPPING_ID,\n           w.WORKFLOW_NAME,\n           ti.INSTANCE_NAME AS SESSION_INSTANCE_NAME,\n           s.SESSION_NAME\n    FROM M2R_REP_1053_P01.REP_WORKFLOWS w\n    JOIN M2R_REP_1053_P01.REP_TASK_INST ti\n      ON ti.WORKFLOW_ID = w.WORKFLOW_ID\n     AND ti.TASK_TYPE = 68\n    JOIN M2R_REP_1053_P01.REP_LOAD_SESSIONS s\n      ON s.SESSION_ID = ti.TASK_ID\n    WHERE w.SUBJECT_AREA = 'M2R_DTM'\n      AND w.WORKFLOW_NAME = 'WF_DTM_MMTR'\n),\nsource_definition_instances AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           wm.SUBJECT_AREA,\n           wm.SUBJECT_ID,\n           wm.WORKFLOW_NAME,\n           wm.SESSION_INSTANCE_NAME,\n           wm.SESSION_NAME,\n           wm.MAPPING_ID,\n           m.MAPPING_NAME,\n           wi.INSTANCE_ID,\n           wi.INSTANCE_NAME AS TRANSFORMATION_NAME,\n           wi.WIDGET_ID,\n           wi.WIDGET_TYPE,\n           wi.WIDGET_TYPE_NAME AS TRANSFORMATION_TYPE,\n           wi.VERSION_NUMBER\n    FROM workflow_mappings wm\n    JOIN M2R_REP_1053_P01.REP_ALL_MAPPINGS m\n      ON m.MAPPING_ID = wm.MAPPING_ID\n     AND m.SUBJECT_AREA = wm.SUBJECT_AREA\n    JOIN M2R_REP_1053_P01.REP_WIDGET_INST wi\n      ON wi.MAPPING_ID = wm.MAPPING_ID\n     AND wi.SUBJECT_ID = wm.SUBJECT_ID\n     AND UPPER(TRIM(wi.WIDGET_TYPE_NAME)) = 'SOURCE DEFINITION'\n),\nrelevant_transformations AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           WIDGET_TYPE,\n           VERSION_NUMBER\n    FROM source_definition_instances\n),\nsource_definition_attribute_rows AS\n(\n    SELECT rt.SUBJECT_ID,\n           rt.MAPPING_ID,\n           rt.INSTANCE_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           wa.ATTR_ID,\n           UPPER(TRIM(wa.ATTR_NAME)) AS ATTR_NAME,\n           TRIM(wa.ATTR_VALUE) AS ATTR_VALUE\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_WIDGET_ATTR wa\n      ON wa.WIDGET_ID = rt.WIDGET_ID\n     AND wa.VERSION_NUMBER = rt.VERSION_NUMBER\n     AND (\n            wa.WIDGET_TYPE = rt.WIDGET_TYPE\n            OR wa.WIDGET_TYPE IS NULL\n         )\n     AND (\n            wa.INSTANCE_ID = rt.INSTANCE_ID\n            OR wa.INSTANCE_ID IS NULL\n            OR wa.INSTANCE_ID = 0\n         )\n     AND (\n            wa.MAPPING_ID = rt.MAPPING_ID\n            OR wa.MAPPING_ID IS NULL\n            OR wa.MAPPING_ID = 0\n         )\n),\nsource_definition_properties AS\n(\n    SELECT SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'OWNER NAME',\n                            'OWNER'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS OWNER_NAME,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'SOURCE TABLE NAME',\n                            'TABLE NAME',\n                            'SOURCE NAME'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS SOURCE_TABLE_NAME,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'SOURCE TIMESTAMP',\n                            'SOURCE TIME STAMP',\n                            'SOURCE TIME'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS SOURCE_TIMESTAMP\n\n    FROM source_definition_attribute_rows\n    GROUP BY\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER\n),\nsource_definition_metadata_extensions AS\n(\n    SELECT rt.SUBJECT_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           mdx.METADATA_EXTN_NAME,\n           mdx.METADATA_EXTN_DATA_TYPE,\n           mdx.METADATA_EXTN_VALUE,\n           mdx.PERMISSIONS,\n           mdx.LINE_NO,\n           mdx.DOMAIN_NAME,\n           mdx.DOMAIN_USAGE,\n           mdx.METADATA_EXTN_DESCRIPTION,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NOT NULL\n               THEN LENGTH(mdx.METADATA_EXTN_VALUE)\n           END AS METADATA_EXTENSION_PRECISION,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NULL\n               THEN NULL\n               WHEN mdx.DOMAIN_ID IS NOT NULL\n                 OR mdx.DOMAIN_NAME IS NOT NULL\n               THEN 'YES'\n               ELSE 'NO'\n           END AS REUSABLE\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_METADATA_EXTNS mdx\n      ON mdx.SUBJECT_ID = rt.SUBJECT_ID\n     AND mdx.METADATA_EXTN_OBJECT_ID = rt.WIDGET_ID\n     AND mdx.VERSION_NUMBER = rt.VERSION_NUMBER\n),\nincoming_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.TO_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.TO_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.FROM_OBJECT_NAME\n               || '.'\n               || pc.FROM_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.TO_OBJECT_INSTANCE_ID\n    WHERE pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n),\noutgoing_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.FROM_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.FROM_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.TO_OBJECT_NAME\n               || '.'\n               || pc.TO_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.FROM_OBJECT_INSTANCE_ID\n    WHERE pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.TO_OBJECT_NAME IS NOT NULL\n      AND pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n),\nincoming_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM incoming_connections\n),\noutgoing_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM outgoing_connections\n),\nport_connections AS\n(\n    SELECT k.SUBJECT_ID,\n           k.MAPPING_ID,\n           k.MAPPING_VERSION_NUMBER,\n           k.INSTANCE_ID,\n           k.FIELD_NAME,\n           incoming.PREVIOUS_TRANSFORMATION,\n           outgoing.NEXT_TRANSFORMATION_NAME\n    FROM\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM incoming_connections_distinct\n\n        UNION\n\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM outgoing_connections_distinct\n    ) k\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS PREVIOUS_TRANSFORMATION\n        FROM incoming_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) incoming\n      ON incoming.SUBJECT_ID = k.SUBJECT_ID\n     AND incoming.MAPPING_ID = k.MAPPING_ID\n     AND incoming.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND incoming.INSTANCE_ID = k.INSTANCE_ID\n     AND incoming.FIELD_NAME = k.FIELD_NAME\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS NEXT_TRANSFORMATION_NAME\n        FROM outgoing_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) outgoing\n      ON outgoing.SUBJECT_ID = k.SUBJECT_ID\n     AND outgoing.MAPPING_ID = k.MAPPING_ID\n     AND outgoing.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND outgoing.INSTANCE_ID = k.INSTANCE_ID\n     AND outgoing.FIELD_NAME = k.FIELD_NAME\n)\nSELECT DISTINCT\n       sdi.SUBJECT_AREA,\n       sdi.WORKFLOW_NAME,\n       sdi.SESSION_INSTANCE_NAME,\n       sdi.SESSION_NAME,\n       sdi.MAPPING_NAME,\n\n       /* Transformation tab */\n       sdi.TRANSFORMATION_NAME,\n       sdi.TRANSFORMATION_TYPE,\n\n       /* Ports tab */\n       wf.FIELD_ORDER AS PORT_ORDER,\n       wf.FIELD_NAME AS PORT_NAME,\n       wf.WGT_DATATYPE AS DATATYPE,\n       wf.WGT_PREC AS PREC,\n       wf.WGT_SCALE AS SCALE,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 1) = 1\n           THEN 'YES'\n           ELSE 'NO'\n       END AS I,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 2) = 2\n           THEN 'YES'\n           ELSE 'NO'\n       END AS O,\n\n       wf.PORTTYPE AS PORTTYPE_CODE,\n\n       /* Properties tab */\n       sdp.OWNER_NAME,\n       NVL(\n           sdp.SOURCE_TABLE_NAME,\n           sdi.TRANSFORMATION_NAME\n       ) AS SOURCE_TABLE_NAME,\n       sdp.SOURCE_TIMESTAMP,\n\n       /* Metadata Extensions tab */\n       sdme.METADATA_EXTN_NAME AS EXTENSION_NAME,\n       sdme.METADATA_EXTN_DATA_TYPE AS EXTENSION_DATATYPE_CODE,\n\n       CASE sdme.METADATA_EXTN_DATA_TYPE\n           WHEN 1 THEN 'String'\n           WHEN 2 THEN 'Number'\n           WHEN 3 THEN 'Boolean'\n           ELSE\n               CASE\n                   WHEN sdme.METADATA_EXTN_DATA_TYPE IS NULL\n                   THEN NULL\n                   ELSE\n                       'Other ('\n                       || TO_CHAR(sdme.METADATA_EXTN_DATA_TYPE)\n                       || ')'\n               END\n       END AS EXTENSION_DATATYPE,\n\n       sdme.METADATA_EXTENSION_PRECISION AS EXTENSION_PREC,\n       sdme.METADATA_EXTN_VALUE AS EXTENSION_VALUE,\n       sdme.REUSABLE,\n       sdme.PERMISSIONS AS EXTENSION_PERMISSIONS,\n       sdme.LINE_NO AS EXTENSION_LINE_NO,\n       sdme.DOMAIN_NAME AS EXTENSION_DOMAIN_NAME,\n       sdme.DOMAIN_USAGE AS EXTENSION_DOMAIN_USAGE,\n       sdme.METADATA_EXTN_DESCRIPTION AS EXTENSION_DESCRIPTION,\n\n       /* Connected transformation ports */\n       pc.PREVIOUS_TRANSFORMATION,\n       pc.NEXT_TRANSFORMATION_NAME\n\nFROM source_definition_instances sdi\n\nJOIN M2R_REP_1053_P01.OPB_WIDGET_FIELD wf\n  ON wf.WIDGET_ID = sdi.WIDGET_ID\n AND wf.VERSION_NUMBER = sdi.VERSION_NUMBER\n\nLEFT JOIN source_definition_properties sdp\n  ON sdp.SUBJECT_ID = sdi.SUBJECT_ID\n AND sdp.MAPPING_ID = sdi.MAPPING_ID\n AND sdp.INSTANCE_ID = sdi.INSTANCE_ID\n AND sdp.WIDGET_ID = sdi.WIDGET_ID\n AND sdp.VERSION_NUMBER = sdi.VERSION_NUMBER\n\nLEFT JOIN source_definition_metadata_extensions sdme\n  ON sdme.SUBJECT_ID = sdi.SUBJECT_ID\n AND sdme.WIDGET_ID = sdi.WIDGET_ID\n AND sdme.VERSION_NUMBER = sdi.VERSION_NUMBER\n\nLEFT JOIN port_connections pc\n  ON pc.SUBJECT_ID = sdi.SUBJECT_ID\n AND pc.MAPPING_ID = sdi.MAPPING_ID\n AND pc.MAPPING_VERSION_NUMBER = sdi.VERSION_NUMBER\n AND pc.INSTANCE_ID = sdi.INSTANCE_ID\n AND pc.FIELD_NAME = wf.FIELD_NAME\n\nORDER BY\n       sdi.SUBJECT_AREA,\n       sdi.WORKFLOW_NAME,\n       sdi.SESSION_INSTANCE_NAME,\n       sdi.SESSION_NAME,\n       sdi.MAPPING_NAME,\n       sdi.TRANSFORMATION_NAME,\n       wf.FIELD_ORDER,\n       wf.FIELD_NAME,\n       sdme.METADATA_EXTN_NAME,\n       sdme.LINE_NO;"}, 'TARGETDEFINITION': {'label': 'Target Definition', 'sql': "WITH workflow_mappings AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           s.SUBJECT_AREA,\n           s.SUBJECT_ID,\n           s.MAPPING_ID,\n           w.WORKFLOW_NAME,\n           ti.INSTANCE_NAME AS SESSION_INSTANCE_NAME,\n           s.SESSION_NAME\n    FROM M2R_REP_1053_P01.REP_WORKFLOWS w\n    JOIN M2R_REP_1053_P01.REP_TASK_INST ti\n      ON ti.WORKFLOW_ID = w.WORKFLOW_ID\n     AND ti.TASK_TYPE = 68\n    JOIN M2R_REP_1053_P01.REP_LOAD_SESSIONS s\n      ON s.SESSION_ID = ti.TASK_ID\n    WHERE w.SUBJECT_AREA = 'M2R_DTM'\n      AND w.WORKFLOW_NAME = 'WF_DTM_MMTR'\n),\ntarget_definition_instances AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           wm.SUBJECT_AREA,\n           wm.SUBJECT_ID,\n           wm.WORKFLOW_NAME,\n           wm.SESSION_INSTANCE_NAME,\n           wm.SESSION_NAME,\n           wm.MAPPING_ID,\n           m.MAPPING_NAME,\n           wi.INSTANCE_ID,\n           wi.INSTANCE_NAME AS TRANSFORMATION_NAME,\n           wi.WIDGET_ID,\n           wi.WIDGET_TYPE,\n           wi.WIDGET_TYPE_NAME AS TRANSFORMATION_TYPE,\n           wi.VERSION_NUMBER\n    FROM workflow_mappings wm\n    JOIN M2R_REP_1053_P01.REP_ALL_MAPPINGS m\n      ON m.MAPPING_ID = wm.MAPPING_ID\n     AND m.SUBJECT_AREA = wm.SUBJECT_AREA\n    JOIN M2R_REP_1053_P01.REP_WIDGET_INST wi\n      ON wi.MAPPING_ID = wm.MAPPING_ID\n     AND wi.SUBJECT_ID = wm.SUBJECT_ID\n     AND UPPER(TRIM(wi.WIDGET_TYPE_NAME)) = 'TARGET DEFINITION'\n),\nrelevant_transformations AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           WIDGET_TYPE,\n           VERSION_NUMBER\n    FROM target_definition_instances\n),\ntarget_definition_attribute_rows AS\n(\n    SELECT rt.SUBJECT_ID,\n           rt.MAPPING_ID,\n           rt.INSTANCE_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           wa.ATTR_ID,\n           UPPER(TRIM(wa.ATTR_NAME)) AS ATTR_NAME,\n           TRIM(wa.ATTR_VALUE) AS ATTR_VALUE\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_WIDGET_ATTR wa\n      ON wa.WIDGET_ID = rt.WIDGET_ID\n     AND wa.VERSION_NUMBER = rt.VERSION_NUMBER\n     AND (\n            wa.WIDGET_TYPE = rt.WIDGET_TYPE\n            OR wa.WIDGET_TYPE IS NULL\n         )\n     AND (\n            wa.INSTANCE_ID = rt.INSTANCE_ID\n            OR wa.INSTANCE_ID IS NULL\n            OR wa.INSTANCE_ID = 0\n         )\n     AND (\n            wa.MAPPING_ID = rt.MAPPING_ID\n            OR wa.MAPPING_ID IS NULL\n            OR wa.MAPPING_ID = 0\n         )\n),\ntarget_definition_properties AS\n(\n    SELECT SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'REJECT TRUNCATED/OVERFLOWED ROWS',\n                            'REJECT TRUNCATED OR OVERFLOWED ROWS',\n                            'REJECT TRUNCATED/OVERFLOW ROWS',\n                            'REJECT OVERFLOWED ROWS'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS REJECT_TRUNCATED_ROWS_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'UPDATE OVERRIDE',\n                            'UPDATE OVERRIDE SQL'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS UPDATE_OVERRIDE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'TABLE NAME PREFIX',\n                            'TARGET TABLE NAME PREFIX'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS TABLE_NAME_PREFIX,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'PRE SQL',\n                            'PRE-SQL'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS PRE_SQL,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'POST SQL',\n                            'POST-SQL'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS POST_SQL,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'TARGET TABLE NAME',\n                            'TABLE NAME',\n                            'TARGET NAME'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS TARGET_TABLE_NAME\n\n    FROM target_definition_attribute_rows\n    GROUP BY\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER\n),\ntarget_definition_metadata_extensions AS\n(\n    SELECT rt.SUBJECT_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           mdx.METADATA_EXTN_NAME,\n           mdx.METADATA_EXTN_DATA_TYPE,\n           mdx.METADATA_EXTN_VALUE,\n           mdx.PERMISSIONS,\n           mdx.LINE_NO,\n           mdx.DOMAIN_NAME,\n           mdx.DOMAIN_USAGE,\n           mdx.METADATA_EXTN_DESCRIPTION,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NOT NULL\n               THEN LENGTH(mdx.METADATA_EXTN_VALUE)\n           END AS METADATA_EXTENSION_PRECISION,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NULL\n               THEN NULL\n               WHEN mdx.DOMAIN_ID IS NOT NULL\n                 OR mdx.DOMAIN_NAME IS NOT NULL\n               THEN 'YES'\n               ELSE 'NO'\n           END AS REUSABLE\n\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_METADATA_EXTNS mdx\n      ON mdx.SUBJECT_ID = rt.SUBJECT_ID\n     AND mdx.METADATA_EXTN_OBJECT_ID = rt.WIDGET_ID\n     AND mdx.VERSION_NUMBER = rt.VERSION_NUMBER\n),\nincoming_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.TO_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.TO_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.FROM_OBJECT_NAME\n               || '.'\n               || pc.FROM_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.TO_OBJECT_INSTANCE_ID\n    WHERE pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n),\noutgoing_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.FROM_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.FROM_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.TO_OBJECT_NAME\n               || '.'\n               || pc.TO_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.FROM_OBJECT_INSTANCE_ID\n    WHERE pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.TO_OBJECT_NAME IS NOT NULL\n      AND pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n),\nincoming_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM incoming_connections\n),\noutgoing_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM outgoing_connections\n),\nport_connections AS\n(\n    SELECT k.SUBJECT_ID,\n           k.MAPPING_ID,\n           k.MAPPING_VERSION_NUMBER,\n           k.INSTANCE_ID,\n           k.FIELD_NAME,\n           incoming.PREVIOUS_TRANSFORMATION,\n           outgoing.NEXT_TRANSFORMATION_NAME\n    FROM\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM incoming_connections_distinct\n\n        UNION\n\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM outgoing_connections_distinct\n    ) k\n\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS PREVIOUS_TRANSFORMATION\n        FROM incoming_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) incoming\n      ON incoming.SUBJECT_ID = k.SUBJECT_ID\n     AND incoming.MAPPING_ID = k.MAPPING_ID\n     AND incoming.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND incoming.INSTANCE_ID = k.INSTANCE_ID\n     AND incoming.FIELD_NAME = k.FIELD_NAME\n\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS NEXT_TRANSFORMATION_NAME\n        FROM outgoing_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) outgoing\n      ON outgoing.SUBJECT_ID = k.SUBJECT_ID\n     AND outgoing.MAPPING_ID = k.MAPPING_ID\n     AND outgoing.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND outgoing.INSTANCE_ID = k.INSTANCE_ID\n     AND outgoing.FIELD_NAME = k.FIELD_NAME\n)\nSELECT DISTINCT\n       tdi.SUBJECT_AREA,\n       tdi.WORKFLOW_NAME,\n       tdi.SESSION_INSTANCE_NAME,\n       tdi.SESSION_NAME,\n       tdi.MAPPING_NAME,\n\n       /* Transformation tab */\n       tdi.TRANSFORMATION_NAME,\n       tdi.TRANSFORMATION_TYPE,\n\n       /* Ports tab */\n       wf.FIELD_ORDER AS PORT_ORDER,\n       wf.FIELD_NAME AS PORT_NAME,\n       wf.WGT_DATATYPE AS DATATYPE,\n       wf.WGT_PREC AS PREC,\n       wf.WGT_SCALE AS SCALE,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 1) = 1\n           THEN 'YES'\n           ELSE 'NO'\n       END AS I,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 2) = 2\n           THEN 'YES'\n           ELSE 'NO'\n       END AS O,\n\n       wf.PORTTYPE AS PORTTYPE_CODE,\n\n       /* Properties tab */\n       CASE\n           WHEN tdp.REJECT_TRUNCATED_ROWS_CODE IS NULL\n           THEN 'NO'\n           WHEN UPPER(TRIM(tdp.REJECT_TRUNCATED_ROWS_CODE))\n                IN ('1', 'YES', 'Y', 'TRUE', 'CHECKED')\n           THEN 'YES'\n           WHEN UPPER(TRIM(tdp.REJECT_TRUNCATED_ROWS_CODE))\n                IN ('0', 'NO', 'N', 'FALSE', 'UNCHECKED')\n           THEN 'NO'\n           ELSE tdp.REJECT_TRUNCATED_ROWS_CODE\n       END AS REJECT_TRUNCATED_OVERFLOWED_ROWS,\n\n       tdp.UPDATE_OVERRIDE,\n       tdp.TABLE_NAME_PREFIX,\n       tdp.PRE_SQL,\n       tdp.POST_SQL,\n\n       NVL(\n           tdp.TARGET_TABLE_NAME,\n           tdi.TRANSFORMATION_NAME\n       ) AS TARGET_TABLE_NAME,\n\n       /* Metadata Extensions tab */\n       tdme.METADATA_EXTN_NAME AS EXTENSION_NAME,\n       tdme.METADATA_EXTN_DATA_TYPE AS EXTENSION_DATATYPE_CODE,\n\n       CASE tdme.METADATA_EXTN_DATA_TYPE\n           WHEN 1 THEN 'String'\n           WHEN 2 THEN 'Number'\n           WHEN 3 THEN 'Boolean'\n           ELSE\n               CASE\n                   WHEN tdme.METADATA_EXTN_DATA_TYPE IS NULL\n                   THEN NULL\n                   ELSE\n                       'Other ('\n                       || TO_CHAR(tdme.METADATA_EXTN_DATA_TYPE)\n                       || ')'\n               END\n       END AS EXTENSION_DATATYPE,\n\n       tdme.METADATA_EXTENSION_PRECISION AS EXTENSION_PREC,\n       tdme.METADATA_EXTN_VALUE AS EXTENSION_VALUE,\n       tdme.REUSABLE,\n       tdme.PERMISSIONS AS EXTENSION_PERMISSIONS,\n       tdme.LINE_NO AS EXTENSION_LINE_NO,\n       tdme.DOMAIN_NAME AS EXTENSION_DOMAIN_NAME,\n       tdme.DOMAIN_USAGE AS EXTENSION_DOMAIN_USAGE,\n       tdme.METADATA_EXTN_DESCRIPTION AS EXTENSION_DESCRIPTION,\n\n       /* Connected transformation ports */\n       pc.PREVIOUS_TRANSFORMATION,\n       pc.NEXT_TRANSFORMATION_NAME\n\nFROM target_definition_instances tdi\n\nJOIN M2R_REP_1053_P01.OPB_WIDGET_FIELD wf\n  ON wf.WIDGET_ID = tdi.WIDGET_ID\n AND wf.VERSION_NUMBER = tdi.VERSION_NUMBER\n\nLEFT JOIN target_definition_properties tdp\n  ON tdp.SUBJECT_ID = tdi.SUBJECT_ID\n AND tdp.MAPPING_ID = tdi.MAPPING_ID\n AND tdp.INSTANCE_ID = tdi.INSTANCE_ID\n AND tdp.WIDGET_ID = tdi.WIDGET_ID\n AND tdp.VERSION_NUMBER = tdi.VERSION_NUMBER\n\nLEFT JOIN target_definition_metadata_extensions tdme\n  ON tdme.SUBJECT_ID = tdi.SUBJECT_ID\n AND tdme.WIDGET_ID = tdi.WIDGET_ID\n AND tdme.VERSION_NUMBER = tdi.VERSION_NUMBER\n\nLEFT JOIN port_connections pc\n  ON pc.SUBJECT_ID = tdi.SUBJECT_ID\n AND pc.MAPPING_ID = tdi.MAPPING_ID\n AND pc.MAPPING_VERSION_NUMBER = tdi.VERSION_NUMBER\n AND pc.INSTANCE_ID = tdi.INSTANCE_ID\n AND pc.FIELD_NAME = wf.FIELD_NAME\n\nORDER BY\n       tdi.SUBJECT_AREA,\n       tdi.WORKFLOW_NAME,\n       tdi.SESSION_INSTANCE_NAME,\n       tdi.SESSION_NAME,\n       tdi.MAPPING_NAME,\n       tdi.TRANSFORMATION_NAME,\n       wf.FIELD_ORDER,\n       wf.FIELD_NAME,\n       tdme.METADATA_EXTN_NAME,\n       tdme.LINE_NO;"}, 'SEQUENCEGENE': {'label': 'sequence gene', 'sql': "WITH workflow_mappings AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           s.SUBJECT_AREA,\n           s.SUBJECT_ID,\n           s.MAPPING_ID,\n           w.WORKFLOW_NAME,\n           ti.INSTANCE_NAME AS SESSION_INSTANCE_NAME,\n           s.SESSION_NAME\n    FROM M2R_REP_1053_P01.REP_WORKFLOWS w\n    JOIN M2R_REP_1053_P01.REP_TASK_INST ti\n      ON ti.WORKFLOW_ID = w.WORKFLOW_ID\n     AND ti.TASK_TYPE = 68\n    JOIN M2R_REP_1053_P01.REP_LOAD_SESSIONS s\n      ON s.SESSION_ID = ti.TASK_ID\n    WHERE w.SUBJECT_AREA = 'M2R_DTM'\n      AND w.WORKFLOW_NAME = 'WF_DTM_MMTR'\n),\nsequence_generator_instances AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           wm.SUBJECT_AREA,\n           wm.SUBJECT_ID,\n           wm.WORKFLOW_NAME,\n           wm.SESSION_INSTANCE_NAME,\n           wm.SESSION_NAME,\n           wm.MAPPING_ID,\n           m.MAPPING_NAME,\n           wi.INSTANCE_ID,\n           wi.INSTANCE_NAME AS TRANSFORMATION_NAME,\n           wi.WIDGET_ID,\n           wi.WIDGET_TYPE,\n           wi.WIDGET_TYPE_NAME AS TRANSFORMATION_TYPE,\n           wi.VERSION_NUMBER\n    FROM workflow_mappings wm\n    JOIN M2R_REP_1053_P01.REP_ALL_MAPPINGS m\n      ON m.MAPPING_ID = wm.MAPPING_ID\n     AND m.SUBJECT_AREA = wm.SUBJECT_AREA\n    JOIN M2R_REP_1053_P01.REP_WIDGET_INST wi\n      ON wi.MAPPING_ID = wm.MAPPING_ID\n     AND wi.SUBJECT_ID = wm.SUBJECT_ID\n     AND UPPER(TRIM(wi.WIDGET_TYPE_NAME)) LIKE 'SEQUENCE%'\n),\nrelevant_transformations AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           WIDGET_TYPE,\n           VERSION_NUMBER\n    FROM sequence_generator_instances\n),\nsequence_attribute_rows AS\n(\n    SELECT rt.SUBJECT_ID,\n           rt.MAPPING_ID,\n           rt.INSTANCE_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           wa.ATTR_ID,\n           UPPER(TRIM(wa.ATTR_NAME)) AS ATTR_NAME,\n           TRIM(wa.ATTR_VALUE) AS ATTR_VALUE\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_WIDGET_ATTR wa\n      ON wa.WIDGET_ID = rt.WIDGET_ID\n     AND wa.VERSION_NUMBER = rt.VERSION_NUMBER\n     AND (\n            wa.WIDGET_TYPE = rt.WIDGET_TYPE\n            OR wa.WIDGET_TYPE IS NULL\n         )\n     AND (\n            wa.INSTANCE_ID = rt.INSTANCE_ID\n            OR wa.INSTANCE_ID IS NULL\n            OR wa.INSTANCE_ID = 0\n         )\n     AND (\n            wa.MAPPING_ID = rt.MAPPING_ID\n            OR wa.MAPPING_ID IS NULL\n            OR wa.MAPPING_ID = 0\n         )\n),\nsequence_properties AS\n(\n    SELECT SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'START VALUE',\n                            'STARTVALUE'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS START_VALUE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'INCREMENT BY',\n                            'INCREMENTBY',\n                            'INCREMENT'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS INCREMENT_BY,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'END VALUE',\n                            'ENDVALUE',\n                            'MAXIMUM VALUE'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS END_VALUE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'CURRENT VALUE',\n                            'CURRENTVALUE'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS CURRENT_VALUE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'CYCLE',\n                            'CYCLE OPTION'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS CYCLE_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'NUMBER OF CACHED VALUES',\n                            'NUMBER OF CACHE VALUES',\n                            'CACHE SIZE'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS NUMBER_OF_CACHED_VALUES,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'RESET',\n                            'RESET SEQUENCE'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS RESET_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'TRACING LEVEL'\n                   THEN ATTR_VALUE\n               END\n           ) AS TRACING_LEVEL_CODE\n\n    FROM sequence_attribute_rows\n    GROUP BY\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER\n),\nsequence_metadata_extensions AS\n(\n    SELECT rt.SUBJECT_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           mdx.METADATA_EXTN_NAME,\n           mdx.METADATA_EXTN_DATA_TYPE,\n           mdx.METADATA_EXTN_VALUE,\n           mdx.PERMISSIONS,\n           mdx.LINE_NO,\n           mdx.DOMAIN_NAME,\n           mdx.DOMAIN_USAGE,\n           mdx.METADATA_EXTN_DESCRIPTION,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NOT NULL\n               THEN LENGTH(mdx.METADATA_EXTN_VALUE)\n           END AS METADATA_EXTENSION_PRECISION,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NULL\n               THEN NULL\n               WHEN mdx.DOMAIN_ID IS NOT NULL\n                 OR mdx.DOMAIN_NAME IS NOT NULL\n               THEN 'YES'\n               ELSE 'NO'\n           END AS REUSABLE\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_METADATA_EXTNS mdx\n      ON mdx.SUBJECT_ID = rt.SUBJECT_ID\n     AND mdx.METADATA_EXTN_OBJECT_ID = rt.WIDGET_ID\n     AND mdx.VERSION_NUMBER = rt.VERSION_NUMBER\n),\nincoming_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.TO_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.TO_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.FROM_OBJECT_NAME\n               || '.'\n               || pc.FROM_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.TO_OBJECT_INSTANCE_ID\n    WHERE pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n),\noutgoing_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.FROM_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.FROM_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.TO_OBJECT_NAME\n               || '.'\n               || pc.TO_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.FROM_OBJECT_INSTANCE_ID\n    WHERE pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.TO_OBJECT_NAME IS NOT NULL\n      AND pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n),\nincoming_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM incoming_connections\n),\noutgoing_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM outgoing_connections\n),\nport_connections AS\n(\n    SELECT k.SUBJECT_ID,\n           k.MAPPING_ID,\n           k.MAPPING_VERSION_NUMBER,\n           k.INSTANCE_ID,\n           k.FIELD_NAME,\n           incoming.PREVIOUS_TRANSFORMATION,\n           outgoing.NEXT_TRANSFORMATION_NAME\n    FROM\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM incoming_connections_distinct\n\n        UNION\n\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM outgoing_connections_distinct\n    ) k\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS PREVIOUS_TRANSFORMATION\n        FROM incoming_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) incoming\n      ON incoming.SUBJECT_ID = k.SUBJECT_ID\n     AND incoming.MAPPING_ID = k.MAPPING_ID\n     AND incoming.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND incoming.INSTANCE_ID = k.INSTANCE_ID\n     AND incoming.FIELD_NAME = k.FIELD_NAME\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS NEXT_TRANSFORMATION_NAME\n        FROM outgoing_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) outgoing\n      ON outgoing.SUBJECT_ID = k.SUBJECT_ID\n     AND outgoing.MAPPING_ID = k.MAPPING_ID\n     AND outgoing.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND outgoing.INSTANCE_ID = k.INSTANCE_ID\n     AND outgoing.FIELD_NAME = k.FIELD_NAME\n)\nSELECT DISTINCT\n       sgi.SUBJECT_AREA,\n       sgi.WORKFLOW_NAME,\n       sgi.SESSION_INSTANCE_NAME,\n       sgi.SESSION_NAME,\n       sgi.MAPPING_NAME,\n\n       /* Transformation tab */\n       sgi.TRANSFORMATION_NAME,\n       sgi.TRANSFORMATION_TYPE,\n\n       CASE\n           WHEN UPPER(TRIM(sgi.TRANSFORMATION_TYPE))\n                LIKE '%REUSABLE%'\n           THEN 'YES'\n           ELSE 'NO'\n       END AS TRANSFORMATION_REUSABLE,\n\n       /* Ports tab */\n       wf.FIELD_ORDER AS PORT_ORDER,\n       wf.FIELD_NAME AS PORT_NAME,\n       CASE wf.WGT_DATATYPE\n    WHEN -5 THEN 'string'\n    WHEN -4 THEN 'text'\n    WHEN -3 THEN 'binary'\n    WHEN -2 THEN 'varbinary'\n    WHEN -1 THEN 'long varbinary'\n    WHEN 0  THEN 'unknown'\n    WHEN 1  THEN 'small integer'\n    WHEN 2  THEN 'integer'\n    WHEN 3  THEN 'decimal'\n    WHEN 4  THEN 'real'\n    WHEN 5  THEN 'double'\n    WHEN 6  THEN 'date/time'\n    WHEN 7  THEN 'date/time'\n    WHEN 8  THEN 'date/time'\n    WHEN 9  THEN 'date/time'\n    WHEN 10 THEN 'string'\n    WHEN 11 THEN 'string'\n    WHEN 12 THEN 'string'\n    WHEN 13 THEN 'binary'\n    WHEN 14 THEN 'bigint'\n    WHEN 15 THEN 'double'\n    WHEN 16 THEN 'decimal'\n    WHEN 17 THEN 'boolean'\n    ELSE\n        'Unknown ('\n        || TO_CHAR(wf.WGT_DATATYPE)\n        || ')'\nEND AS DATATYPE,      \n       wf.WGT_PREC AS PREC,\n       wf.WGT_SCALE AS SCALE,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 1) = 1\n           THEN 'YES'\n           ELSE 'NO'\n       END AS I,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 2) = 2\n           THEN 'YES'\n           ELSE 'NO'\n       END AS O,\n\n       wf.PORTTYPE AS PORTTYPE_CODE,\n\n       /* Properties tab */\n       NVL(sp.START_VALUE, '0') AS START_VALUE,\n       NVL(sp.INCREMENT_BY, '1') AS INCREMENT_BY,\n       NVL(sp.END_VALUE, '9223372036854775807') AS END_VALUE,\n       sp.CURRENT_VALUE,\n\n       CASE\n           WHEN sp.CYCLE_CODE IS NULL\n           THEN 'NO'\n           WHEN UPPER(TRIM(sp.CYCLE_CODE))\n                IN ('1', 'YES', 'Y', 'TRUE', 'CHECKED')\n           THEN 'YES'\n           WHEN UPPER(TRIM(sp.CYCLE_CODE))\n                IN ('0', 'NO', 'N', 'FALSE', 'UNCHECKED')\n           THEN 'NO'\n           ELSE sp.CYCLE_CODE\n       END AS CYCLE,\n\n       NVL(\n           sp.NUMBER_OF_CACHED_VALUES,\n           '1000'\n       ) AS NUMBER_OF_CACHED_VALUES,\n\n       CASE\n           WHEN sp.RESET_CODE IS NULL\n           THEN 'NO'\n           WHEN UPPER(TRIM(sp.RESET_CODE))\n                IN ('1', 'YES', 'Y', 'TRUE', 'CHECKED')\n           THEN 'YES'\n           WHEN UPPER(TRIM(sp.RESET_CODE))\n                IN ('0', 'NO', 'N', 'FALSE', 'UNCHECKED')\n           THEN 'NO'\n           ELSE sp.RESET_CODE\n       END AS RESET,\n\n       CASE\n           WHEN sp.TRACING_LEVEL_CODE IS NULL\n           THEN 'Normal'\n           WHEN UPPER(TRIM(sp.TRACING_LEVEL_CODE)) = '1'\n           THEN 'Terse'\n           WHEN UPPER(TRIM(sp.TRACING_LEVEL_CODE)) = '2'\n           THEN 'Normal'\n           WHEN UPPER(TRIM(sp.TRACING_LEVEL_CODE)) = '3'\n           THEN 'Verbose Initialization'\n           WHEN UPPER(TRIM(sp.TRACING_LEVEL_CODE)) = '4'\n           THEN 'Verbose Data'\n           WHEN UPPER(TRIM(sp.TRACING_LEVEL_CODE)) = 'TERSE'\n           THEN 'Terse'\n           WHEN UPPER(TRIM(sp.TRACING_LEVEL_CODE)) = 'NORMAL'\n           THEN 'Normal'\n           WHEN UPPER(TRIM(sp.TRACING_LEVEL_CODE)) =\n                'VERBOSE INITIALIZATION'\n           THEN 'Verbose Initialization'\n           WHEN UPPER(TRIM(sp.TRACING_LEVEL_CODE)) =\n                'VERBOSE DATA'\n           THEN 'Verbose Data'\n           ELSE\n               'Unknown ('\n               || sp.TRACING_LEVEL_CODE\n               || ')'\n       END AS TRACING_LEVEL,\n\n       /* Metadata Extensions tab */\n       sme.METADATA_EXTN_NAME AS EXTENSION_NAME,\n       sme.METADATA_EXTN_DATA_TYPE AS EXTENSION_DATATYPE_CODE,\n\n       CASE sme.METADATA_EXTN_DATA_TYPE\n           WHEN 1 THEN 'String'\n           WHEN 2 THEN 'Number'\n           WHEN 3 THEN 'Boolean'\n           ELSE\n               CASE\n                   WHEN sme.METADATA_EXTN_DATA_TYPE IS NULL\n                   THEN NULL\n                   ELSE\n                       'Other ('\n                       || TO_CHAR(sme.METADATA_EXTN_DATA_TYPE)\n                       || ')'\n               END\n       END AS EXTENSION_DATATYPE,\n\n       sme.METADATA_EXTENSION_PRECISION AS EXTENSION_PREC,\n       sme.METADATA_EXTN_VALUE AS EXTENSION_VALUE,\n       sme.REUSABLE,\n       sme.PERMISSIONS AS EXTENSION_PERMISSIONS,\n       sme.LINE_NO AS EXTENSION_LINE_NO,\n       sme.DOMAIN_NAME AS EXTENSION_DOMAIN_NAME,\n       sme.DOMAIN_USAGE AS EXTENSION_DOMAIN_USAGE,\n       sme.METADATA_EXTN_DESCRIPTION AS EXTENSION_DESCRIPTION,\n\n       /* Connected transformation ports */\n       pc.PREVIOUS_TRANSFORMATION,\n       pc.NEXT_TRANSFORMATION_NAME\n\nFROM sequence_generator_instances sgi\n\nJOIN M2R_REP_1053_P01.OPB_WIDGET_FIELD wf\n  ON wf.WIDGET_ID = sgi.WIDGET_ID\n AND wf.VERSION_NUMBER = sgi.VERSION_NUMBER\n\nLEFT JOIN sequence_properties sp\n  ON sp.SUBJECT_ID = sgi.SUBJECT_ID\n AND sp.MAPPING_ID = sgi.MAPPING_ID\n AND sp.INSTANCE_ID = sgi.INSTANCE_ID\n AND sp.WIDGET_ID = sgi.WIDGET_ID\n AND sp.VERSION_NUMBER = sgi.VERSION_NUMBER\n\nLEFT JOIN sequence_metadata_extensions sme\n  ON sme.SUBJECT_ID = sgi.SUBJECT_ID\n AND sme.WIDGET_ID = sgi.WIDGET_ID\n AND sme.VERSION_NUMBER = sgi.VERSION_NUMBER\n\nLEFT JOIN port_connections pc\n  ON pc.SUBJECT_ID = sgi.SUBJECT_ID\n AND pc.MAPPING_ID = sgi.MAPPING_ID\n AND pc.MAPPING_VERSION_NUMBER = sgi.VERSION_NUMBER\n AND pc.INSTANCE_ID = sgi.INSTANCE_ID\n AND pc.FIELD_NAME = wf.FIELD_NAME\n\nORDER BY\n       sgi.SUBJECT_AREA,\n       sgi.WORKFLOW_NAME,\n       sgi.SESSION_INSTANCE_NAME,\n       sgi.SESSION_NAME,\n       sgi.MAPPING_NAME,\n       sgi.TRANSFORMATION_NAME,\n       wf.FIELD_ORDER,\n       wf.FIELD_NAME,\n       sme.METADATA_EXTN_NAME,\n       sme.LINE_NO;"}, 'FILTER': {'label': 'Filter', 'sql': "WITH workflow_mappings AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           s.SUBJECT_AREA,\n           s.SUBJECT_ID,\n           s.MAPPING_ID,\n           w.WORKFLOW_NAME,\n           ti.INSTANCE_NAME AS SESSION_INSTANCE_NAME,\n           s.SESSION_NAME\n    FROM M2R_REP_1053_P01.REP_WORKFLOWS w\n    JOIN M2R_REP_1053_P01.REP_TASK_INST ti\n      ON ti.WORKFLOW_ID = w.WORKFLOW_ID\n     AND ti.TASK_TYPE = 68\n    JOIN M2R_REP_1053_P01.REP_LOAD_SESSIONS s\n      ON s.SESSION_ID = ti.TASK_ID\n    WHERE w.SUBJECT_AREA = 'M2R_DTM'\n      AND w.WORKFLOW_NAME = 'WF_DTM_MMTR'\n),\nfilter_instances AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           wm.SUBJECT_AREA,\n           wm.SUBJECT_ID,\n           wm.WORKFLOW_NAME,\n           wm.SESSION_INSTANCE_NAME,\n           wm.SESSION_NAME,\n           wm.MAPPING_ID,\n           m.MAPPING_NAME,\n           wi.INSTANCE_ID,\n           wi.INSTANCE_NAME AS TRANSFORMATION_NAME,\n           wi.WIDGET_ID,\n           wi.WIDGET_TYPE,\n           wi.WIDGET_TYPE_NAME AS TRANSFORMATION_TYPE,\n           wi.VERSION_NUMBER\n    FROM workflow_mappings wm\n    JOIN M2R_REP_1053_P01.REP_ALL_MAPPINGS m\n      ON m.MAPPING_ID = wm.MAPPING_ID\n     AND m.SUBJECT_AREA = wm.SUBJECT_AREA\n    JOIN M2R_REP_1053_P01.REP_WIDGET_INST wi\n      ON wi.MAPPING_ID = wm.MAPPING_ID\n     AND wi.SUBJECT_ID = wm.SUBJECT_ID\n     AND UPPER(TRIM(wi.WIDGET_TYPE_NAME)) = 'FILTER'\n),\nrelevant_transformations AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           WIDGET_TYPE,\n           VERSION_NUMBER\n    FROM filter_instances\n),\nfilter_attribute_rows AS\n(\n    SELECT rt.SUBJECT_ID,\n           rt.MAPPING_ID,\n           rt.INSTANCE_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           wa.ATTR_ID,\n           UPPER(TRIM(wa.ATTR_NAME)) AS ATTR_NAME,\n           TRIM(wa.ATTR_VALUE) AS ATTR_VALUE\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_WIDGET_ATTR wa\n      ON wa.WIDGET_ID = rt.WIDGET_ID\n     AND wa.VERSION_NUMBER = rt.VERSION_NUMBER\n     AND (\n            wa.WIDGET_TYPE = rt.WIDGET_TYPE\n            OR wa.WIDGET_TYPE IS NULL\n         )\n     AND (\n            wa.INSTANCE_ID = rt.INSTANCE_ID\n            OR wa.INSTANCE_ID IS NULL\n            OR wa.INSTANCE_ID = 0\n         )\n     AND (\n            wa.MAPPING_ID = rt.MAPPING_ID\n            OR wa.MAPPING_ID IS NULL\n            OR wa.MAPPING_ID = 0\n         )\n),\nfilter_properties AS\n(\n    SELECT SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER,\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'FILTER CONDITION',\n                            'FILTERCONDITION',\n                            'FILTER CONDITION EXPRESSION'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS FILTER_CONDITION,\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'TRACING LEVEL'\n                   THEN ATTR_VALUE\n               END\n           ) AS TRACING_LEVEL_CODE\n    FROM filter_attribute_rows\n    GROUP BY\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER\n),\nfilter_metadata_extensions AS\n(\n    SELECT DISTINCT\n           rt.SUBJECT_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           mdx.METADATA_EXTN_NAME AS EXTENSION_NAME,\n           mdx.METADATA_EXTN_DATA_TYPE AS EXTENSION_DATATYPE_CODE,\n           mdx.METADATA_EXTN_VALUE AS EXTENSION_VALUE,\n           mdx.PERMISSIONS AS EXTENSION_PERMISSIONS,\n           mdx.LINE_NO AS EXTENSION_LINE_NO,\n           mdx.DOMAIN_NAME AS EXTENSION_DOMAIN_NAME,\n           mdx.DOMAIN_USAGE AS EXTENSION_DOMAIN_USAGE,\n           mdx.METADATA_EXTN_DESCRIPTION AS EXTENSION_DESCRIPTION,\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NOT NULL\n               THEN LENGTH(mdx.METADATA_EXTN_VALUE)\n               ELSE NULL\n           END AS EXTENSION_PREC,\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NULL\n               THEN NULL\n               WHEN mdx.DOMAIN_ID IS NOT NULL\n                 OR mdx.DOMAIN_NAME IS NOT NULL\n               THEN 'YES'\n               ELSE 'NO'\n           END AS EXTENSION_REUSABLE\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_METADATA_EXTNS mdx\n      ON mdx.SUBJECT_ID = rt.SUBJECT_ID\n     AND mdx.METADATA_EXTN_OBJECT_ID = rt.WIDGET_ID\n     AND mdx.VERSION_NUMBER = rt.VERSION_NUMBER\n),\nincoming_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.TO_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.TO_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.FROM_OBJECT_NAME\n               || '.'\n               || pc.FROM_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.TO_OBJECT_INSTANCE_ID\n    WHERE pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n),\noutgoing_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.FROM_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.FROM_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.TO_OBJECT_NAME\n               || '.'\n               || pc.TO_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.FROM_OBJECT_INSTANCE_ID\n    WHERE pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.TO_OBJECT_NAME IS NOT NULL\n      AND pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n),\nincoming_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM incoming_connections\n),\noutgoing_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM outgoing_connections\n),\nport_connections AS\n(\n    SELECT k.SUBJECT_ID,\n           k.MAPPING_ID,\n           k.MAPPING_VERSION_NUMBER,\n           k.INSTANCE_ID,\n           k.FIELD_NAME,\n           incoming.PREVIOUS_TRANSFORMATION,\n           outgoing.NEXT_TRANSFORMATION_NAME\n    FROM\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM incoming_connections_distinct\n\n        UNION\n\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM outgoing_connections_distinct\n    ) k\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS PREVIOUS_TRANSFORMATION\n        FROM incoming_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) incoming\n      ON incoming.SUBJECT_ID = k.SUBJECT_ID\n     AND incoming.MAPPING_ID = k.MAPPING_ID\n     AND incoming.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND incoming.INSTANCE_ID = k.INSTANCE_ID\n     AND incoming.FIELD_NAME = k.FIELD_NAME\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS NEXT_TRANSFORMATION_NAME\n        FROM outgoing_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) outgoing\n      ON outgoing.SUBJECT_ID = k.SUBJECT_ID\n     AND outgoing.MAPPING_ID = k.MAPPING_ID\n     AND outgoing.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND outgoing.INSTANCE_ID = k.INSTANCE_ID\n     AND outgoing.FIELD_NAME = k.FIELD_NAME\n)\nSELECT DISTINCT\n       fi.SUBJECT_AREA,\n       fi.WORKFLOW_NAME,\n       fi.SESSION_INSTANCE_NAME,\n       fi.SESSION_NAME,\n       fi.MAPPING_NAME,\n\n       /* Transformation tab */\n       fi.TRANSFORMATION_NAME,\n       fi.TRANSFORMATION_TYPE,\n\n       /* Ports tab */\n       wf.FIELD_ORDER AS PORT_ORDER,\n       wf.FIELD_NAME AS PORT_NAME,\n\n       CASE wf.WGT_DATATYPE\n           WHEN -5 THEN 'string'\n           WHEN -4 THEN 'text'\n           WHEN -3 THEN 'binary'\n           WHEN -2 THEN 'varbinary'\n           WHEN -1 THEN 'long varbinary'\n           WHEN 0  THEN 'unknown'\n           WHEN 1  THEN 'small integer'\n           WHEN 2  THEN 'integer'\n           WHEN 3  THEN 'decimal'\n           WHEN 4  THEN 'real'\n           WHEN 5  THEN 'double'\n           WHEN 6  THEN 'date/time'\n           WHEN 7  THEN 'date/time'\n           WHEN 8  THEN 'date/time'\n           WHEN 9  THEN 'date/time'\n           WHEN 10 THEN 'string'\n           WHEN 11 THEN 'string'\n           WHEN 12 THEN 'string'\n           WHEN 13 THEN 'binary'\n           WHEN 14 THEN 'bigint'\n           WHEN 15 THEN 'double'\n           WHEN 16 THEN 'decimal'\n           WHEN 17 THEN 'boolean'\n           ELSE\n               'Unknown ('\n               || TO_CHAR(wf.WGT_DATATYPE)\n               || ')'\n       END AS DATATYPE,\n\n       wf.WGT_DATATYPE AS DATATYPE_CODE,\n       wf.WGT_PREC AS PREC,\n       wf.WGT_SCALE AS SCALE,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 1) = 1\n           THEN 'YES'\n           ELSE 'NO'\n       END AS I,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 2) = 2\n           THEN 'YES'\n           ELSE 'NO'\n       END AS O,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 32) = 32\n           THEN 'YES'\n           ELSE 'NO'\n       END AS V,\n\n       wf.PORTTYPE AS PORTTYPE_CODE,\n\n       /* Properties tab */\n       fp.FILTER_CONDITION,\n\n       CASE\n           WHEN fp.TRACING_LEVEL_CODE IS NULL\n           THEN 'Normal'\n           WHEN UPPER(TRIM(fp.TRACING_LEVEL_CODE)) = '1'\n           THEN 'Terse'\n           WHEN UPPER(TRIM(fp.TRACING_LEVEL_CODE)) = '2'\n           THEN 'Normal'\n           WHEN UPPER(TRIM(fp.TRACING_LEVEL_CODE)) = '3'\n           THEN 'Verbose Initialization'\n           WHEN UPPER(TRIM(fp.TRACING_LEVEL_CODE)) = '4'\n           THEN 'Verbose Data'\n           WHEN UPPER(TRIM(fp.TRACING_LEVEL_CODE)) = 'TERSE'\n           THEN 'Terse'\n           WHEN UPPER(TRIM(fp.TRACING_LEVEL_CODE)) = 'NORMAL'\n           THEN 'Normal'\n           WHEN UPPER(TRIM(fp.TRACING_LEVEL_CODE)) =\n                'VERBOSE INITIALIZATION'\n           THEN 'Verbose Initialization'\n           WHEN UPPER(TRIM(fp.TRACING_LEVEL_CODE)) =\n                'VERBOSE DATA'\n           THEN 'Verbose Data'\n           ELSE\n               'Unknown ('\n               || fp.TRACING_LEVEL_CODE\n               || ')'\n       END AS TRACING_LEVEL,\n\n       /* Metadata Extensions tab */\n       fme.EXTENSION_NAME,\n       fme.EXTENSION_DATATYPE_CODE,\n\n       CASE fme.EXTENSION_DATATYPE_CODE\n           WHEN 1 THEN 'String'\n           WHEN 2 THEN 'Number'\n           WHEN 3 THEN 'Boolean'\n           ELSE\n               CASE\n                   WHEN fme.EXTENSION_DATATYPE_CODE IS NULL\n                   THEN NULL\n                   ELSE\n                       'Other ('\n                       || TO_CHAR(fme.EXTENSION_DATATYPE_CODE)\n                       || ')'\n               END\n       END AS EXTENSION_DATATYPE,\n\n       fme.EXTENSION_PREC,\n       fme.EXTENSION_VALUE,\n       fme.EXTENSION_REUSABLE AS REUSABLE,\n       fme.EXTENSION_PERMISSIONS,\n       fme.EXTENSION_LINE_NO,\n       fme.EXTENSION_DOMAIN_NAME,\n       fme.EXTENSION_DOMAIN_USAGE,\n       fme.EXTENSION_DESCRIPTION,\n\n       /* Connected transformation ports */\n       pc.PREVIOUS_TRANSFORMATION,\n       pc.NEXT_TRANSFORMATION_NAME\n\nFROM filter_instances fi\n\nJOIN M2R_REP_1053_P01.OPB_WIDGET_FIELD wf\n  ON wf.WIDGET_ID = fi.WIDGET_ID\n AND wf.VERSION_NUMBER = fi.VERSION_NUMBER\n\nLEFT JOIN filter_properties fp\n  ON fp.SUBJECT_ID = fi.SUBJECT_ID\n AND fp.MAPPING_ID = fi.MAPPING_ID\n AND fp.INSTANCE_ID = fi.INSTANCE_ID\n AND fp.WIDGET_ID = fi.WIDGET_ID\n AND fp.VERSION_NUMBER = fi.VERSION_NUMBER\n\nLEFT JOIN filter_metadata_extensions fme\n  ON fme.SUBJECT_ID = fi.SUBJECT_ID\n AND fme.WIDGET_ID = fi.WIDGET_ID\n AND fme.VERSION_NUMBER = fi.VERSION_NUMBER\n\nLEFT JOIN port_connections pc\n  ON pc.SUBJECT_ID = fi.SUBJECT_ID\n AND pc.MAPPING_ID = fi.MAPPING_ID\n AND pc.MAPPING_VERSION_NUMBER = fi.VERSION_NUMBER\n AND pc.INSTANCE_ID = fi.INSTANCE_ID\n AND pc.FIELD_NAME = wf.FIELD_NAME\n\nORDER BY\n       fi.SUBJECT_AREA,\n       fi.WORKFLOW_NAME,\n       fi.SESSION_INSTANCE_NAME,\n       fi.SESSION_NAME,\n       fi.MAPPING_NAME,\n       fi.TRANSFORMATION_NAME,\n       wf.FIELD_ORDER,\n       wf.FIELD_NAME,\n       fme.EXTENSION_NAME,\n       fme.EXTENSION_LINE_NO;"}, 'NORMALIZER': {'label': 'Normalizer', 'sql': "WITH workflow_mappings AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           s.SUBJECT_AREA,\n           s.SUBJECT_ID,\n           s.MAPPING_ID,\n           w.WORKFLOW_NAME,\n           ti.INSTANCE_NAME AS SESSION_INSTANCE_NAME,\n           s.SESSION_NAME\n    FROM M2R_REP_1053_P01.REP_WORKFLOWS w\n    JOIN M2R_REP_1053_P01.REP_TASK_INST ti\n      ON ti.WORKFLOW_ID = w.WORKFLOW_ID\n     AND ti.TASK_TYPE = 68\n    JOIN M2R_REP_1053_P01.REP_LOAD_SESSIONS s\n      ON s.SESSION_ID = ti.TASK_ID\n    WHERE w.SUBJECT_AREA = 'M2R_DTM'\n      AND w.WORKFLOW_NAME = 'WF_DTM_MMTR'\n),\nnormalizer_instances AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           wm.SUBJECT_AREA,\n           wm.SUBJECT_ID,\n           wm.WORKFLOW_NAME,\n           wm.SESSION_INSTANCE_NAME,\n           wm.SESSION_NAME,\n           wm.MAPPING_ID,\n           m.MAPPING_NAME,\n           wi.INSTANCE_ID,\n           wi.INSTANCE_NAME AS TRANSFORMATION_NAME,\n           wi.WIDGET_ID,\n           wi.WIDGET_TYPE,\n           wi.WIDGET_TYPE_NAME AS TRANSFORMATION_TYPE,\n           wi.VERSION_NUMBER\n    FROM workflow_mappings wm\n    JOIN M2R_REP_1053_P01.REP_ALL_MAPPINGS m\n      ON m.MAPPING_ID = wm.MAPPING_ID\n     AND m.SUBJECT_AREA = wm.SUBJECT_AREA\n    JOIN M2R_REP_1053_P01.REP_WIDGET_INST wi\n      ON wi.MAPPING_ID = wm.MAPPING_ID\n     AND wi.SUBJECT_ID = wm.SUBJECT_ID\n     AND UPPER(TRIM(wi.WIDGET_TYPE_NAME)) = 'NORMALIZER'\n),\nrelevant_transformations AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           WIDGET_TYPE,\n           VERSION_NUMBER\n    FROM normalizer_instances\n),\nnormalizer_attribute_rows AS\n(\n    SELECT rt.SUBJECT_ID,\n           rt.MAPPING_ID,\n           rt.INSTANCE_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           wa.ATTR_ID,\n           UPPER(TRIM(wa.ATTR_NAME)) AS ATTR_NAME,\n           TRIM(wa.ATTR_VALUE) AS ATTR_VALUE\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_WIDGET_ATTR wa\n      ON wa.WIDGET_ID = rt.WIDGET_ID\n     AND wa.VERSION_NUMBER = rt.VERSION_NUMBER\n     AND (\n            wa.WIDGET_TYPE = rt.WIDGET_TYPE\n            OR wa.WIDGET_TYPE IS NULL\n         )\n     AND (\n            wa.INSTANCE_ID = rt.INSTANCE_ID\n            OR wa.INSTANCE_ID IS NULL\n            OR wa.INSTANCE_ID = 0\n         )\n     AND (\n            wa.MAPPING_ID = rt.MAPPING_ID\n            OR wa.MAPPING_ID IS NULL\n            OR wa.MAPPING_ID = 0\n         )\n),\nnormalizer_properties AS\n(\n    SELECT SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'RESET',\n                            'RESET SEQUENCE'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS RESET_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'RESTART',\n                            'RESTART SEQUENCE'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS RESTART_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'TRACING LEVEL'\n                   THEN ATTR_VALUE\n               END\n           ) AS TRACING_LEVEL_CODE\n\n    FROM normalizer_attribute_rows\n    GROUP BY\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER\n),\nnormalizer_ports AS\n(\n    SELECT rt.SUBJECT_ID,\n           rt.MAPPING_ID,\n           rt.INSTANCE_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           wf.FIELD_ID,\n           wf.FIELD_ORDER,\n           wf.FIELD_NAME,\n           wf.WGT_DATATYPE,\n           wf.WGT_PREC,\n           wf.WGT_SCALE,\n           wf.PORTTYPE,\n\n           CASE\n               WHEN REGEXP_LIKE(\n                        wf.FIELD_NAME,\n                        '_in[0-9]*$',\n                        'i'\n                    )\n               THEN REGEXP_REPLACE(\n                        wf.FIELD_NAME,\n                        '_in[0-9]*$',\n                        '',\n                        1,\n                        0,\n                        'i'\n                    )\n               ELSE wf.FIELD_NAME\n           END AS NORMALIZER_COLUMN_NAME,\n\n           CASE\n               WHEN REGEXP_LIKE(\n                        wf.FIELD_NAME,\n                        '_in[0-9]*$',\n                        'i'\n                    )\n               THEN 'INPUT_OCCURRENCE'\n               WHEN UPPER(wf.FIELD_NAME) LIKE 'GK_%'\n               THEN 'GENERATED_KEY'\n               WHEN UPPER(wf.FIELD_NAME) LIKE 'GCID_%'\n               THEN 'GENERATED_COLUMN_ID'\n               ELSE 'OUTPUT'\n           END AS NORMALIZER_PORT_CATEGORY\n\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.OPB_WIDGET_FIELD wf\n      ON wf.WIDGET_ID = rt.WIDGET_ID\n     AND wf.VERSION_NUMBER = rt.VERSION_NUMBER\n),\nnormalizer_column_summary AS\n(\n    SELECT SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER,\n           NORMALIZER_COLUMN_NAME,\n\n           MIN(\n               CASE\n                   WHEN NORMALIZER_PORT_CATEGORY =\n                        'INPUT_OCCURRENCE'\n                   THEN FIELD_ORDER\n               END\n           ) AS FIRST_INPUT_FIELD_ORDER,\n\n           COUNT(\n               CASE\n                   WHEN NORMALIZER_PORT_CATEGORY =\n                        'INPUT_OCCURRENCE'\n                   THEN 1\n               END\n           ) AS INPUT_OCCURRENCE_COUNT,\n\n           MAX(\n               CASE\n                   WHEN NORMALIZER_PORT_CATEGORY = 'OUTPUT'\n                   THEN WGT_DATATYPE\n               END\n           ) AS OUTPUT_DATATYPE_CODE,\n\n           MAX(\n               CASE\n                   WHEN NORMALIZER_PORT_CATEGORY = 'OUTPUT'\n                   THEN WGT_PREC\n               END\n           ) AS OUTPUT_PRECISION,\n\n           MAX(\n               CASE\n                   WHEN NORMALIZER_PORT_CATEGORY = 'OUTPUT'\n                   THEN WGT_SCALE\n               END\n           ) AS OUTPUT_SCALE\n\n    FROM normalizer_ports\n    WHERE NORMALIZER_PORT_CATEGORY IN\n          (\n              'INPUT_OCCURRENCE',\n              'OUTPUT'\n          )\n    GROUP BY\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER,\n           NORMALIZER_COLUMN_NAME\n),\nnormalizer_tab AS\n(\n    SELECT SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER,\n           NORMALIZER_COLUMN_NAME AS COLUMN_NAME,\n\n           0 AS NORMALIZER_LEVEL,\n\n           CASE\n               WHEN INPUT_OCCURRENCE_COUNT > 1\n               THEN INPUT_OCCURRENCE_COUNT\n               ELSE 0\n           END AS OCCURS,\n\n           OUTPUT_DATATYPE_CODE AS DATATYPE_CODE,\n           OUTPUT_PRECISION AS PRECISION,\n           OUTPUT_SCALE AS SCALE,\n\n           FIRST_INPUT_FIELD_ORDER AS NORMALIZER_COLUMN_ORDER\n\n    FROM normalizer_column_summary\n),\nnormalizer_metadata_extensions AS\n(\n    SELECT DISTINCT\n           rt.SUBJECT_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           mdx.METADATA_EXTN_NAME AS EXTENSION_NAME,\n           mdx.METADATA_EXTN_DATA_TYPE AS EXTENSION_DATATYPE_CODE,\n           mdx.METADATA_EXTN_VALUE AS EXTENSION_VALUE,\n           mdx.PERMISSIONS AS EXTENSION_PERMISSIONS,\n           mdx.LINE_NO AS EXTENSION_LINE_NO,\n           mdx.DOMAIN_NAME AS EXTENSION_DOMAIN_NAME,\n           mdx.DOMAIN_USAGE AS EXTENSION_DOMAIN_USAGE,\n           mdx.METADATA_EXTN_DESCRIPTION AS EXTENSION_DESCRIPTION,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NOT NULL\n               THEN LENGTH(mdx.METADATA_EXTN_VALUE)\n               ELSE NULL\n           END AS EXTENSION_PREC,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NULL\n               THEN NULL\n               WHEN mdx.DOMAIN_ID IS NOT NULL\n                 OR mdx.DOMAIN_NAME IS NOT NULL\n               THEN 'YES'\n               ELSE 'NO'\n           END AS EXTENSION_REUSABLE\n\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_METADATA_EXTNS mdx\n      ON mdx.SUBJECT_ID = rt.SUBJECT_ID\n     AND mdx.METADATA_EXTN_OBJECT_ID = rt.WIDGET_ID\n     AND mdx.VERSION_NUMBER = rt.VERSION_NUMBER\n),\nincoming_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.TO_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.TO_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.FROM_OBJECT_NAME\n               || '.'\n               || pc.FROM_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.TO_OBJECT_INSTANCE_ID\n    WHERE pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n),\noutgoing_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.FROM_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.FROM_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.TO_OBJECT_NAME\n               || '.'\n               || pc.TO_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.FROM_OBJECT_INSTANCE_ID\n    WHERE pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.TO_OBJECT_NAME IS NOT NULL\n      AND pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n),\nincoming_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM incoming_connections\n),\noutgoing_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM outgoing_connections\n),\nport_connections AS\n(\n    SELECT k.SUBJECT_ID,\n           k.MAPPING_ID,\n           k.MAPPING_VERSION_NUMBER,\n           k.INSTANCE_ID,\n           k.FIELD_NAME,\n           incoming.PREVIOUS_TRANSFORMATION,\n           outgoing.NEXT_TRANSFORMATION_NAME\n    FROM\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM incoming_connections_distinct\n\n        UNION\n\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM outgoing_connections_distinct\n    ) k\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS PREVIOUS_TRANSFORMATION\n        FROM incoming_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) incoming\n      ON incoming.SUBJECT_ID = k.SUBJECT_ID\n     AND incoming.MAPPING_ID = k.MAPPING_ID\n     AND incoming.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND incoming.INSTANCE_ID = k.INSTANCE_ID\n     AND incoming.FIELD_NAME = k.FIELD_NAME\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS NEXT_TRANSFORMATION_NAME\n        FROM outgoing_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) outgoing\n      ON outgoing.SUBJECT_ID = k.SUBJECT_ID\n     AND outgoing.MAPPING_ID = k.MAPPING_ID\n     AND outgoing.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND outgoing.INSTANCE_ID = k.INSTANCE_ID\n     AND outgoing.FIELD_NAME = k.FIELD_NAME\n)\nSELECT DISTINCT\n       ni.SUBJECT_AREA,\n       ni.WORKFLOW_NAME,\n       ni.SESSION_INSTANCE_NAME,\n       ni.SESSION_NAME,\n       ni.MAPPING_NAME,\n\n       /* Transformation tab */\n       ni.TRANSFORMATION_NAME,\n       ni.TRANSFORMATION_TYPE,\n\n       /* Ports tab */\n       np.FIELD_ORDER AS PORT_ORDER,\n       np.FIELD_NAME AS PORT_NAME,\n\n       CASE np.WGT_DATATYPE\n           WHEN -5 THEN 'string'\n           WHEN -4 THEN 'text'\n           WHEN -3 THEN 'binary'\n           WHEN -2 THEN 'varbinary'\n           WHEN -1 THEN 'long varbinary'\n           WHEN 0  THEN 'unknown'\n           WHEN 1  THEN 'small integer'\n           WHEN 2  THEN 'integer'\n           WHEN 3  THEN 'decimal'\n           WHEN 4  THEN 'real'\n           WHEN 5  THEN 'double'\n           WHEN 6  THEN 'date/time'\n           WHEN 7  THEN 'date/time'\n           WHEN 8  THEN 'date/time'\n           WHEN 9  THEN 'date/time'\n           WHEN 10 THEN 'string'\n           WHEN 11 THEN 'string'\n           WHEN 12 THEN 'string'\n           WHEN 13 THEN 'binary'\n           WHEN 14 THEN 'bigint'\n           WHEN 15 THEN 'double'\n           WHEN 16 THEN 'decimal'\n           WHEN 17 THEN 'boolean'\n           ELSE\n               'Unknown ('\n               || TO_CHAR(np.WGT_DATATYPE)\n               || ')'\n       END AS DATATYPE,\n\n       np.WGT_DATATYPE AS DATATYPE_CODE,\n       np.WGT_PREC AS PREC,\n       np.WGT_SCALE AS SCALE,\n\n       CASE\n           WHEN BITAND(np.PORTTYPE, 1) = 1\n           THEN 'YES'\n           ELSE 'NO'\n       END AS I,\n\n       CASE\n           WHEN BITAND(np.PORTTYPE, 2) = 2\n           THEN 'YES'\n           ELSE 'NO'\n       END AS O,\n\n       CASE\n           WHEN BITAND(np.PORTTYPE, 32) = 32\n           THEN 'YES'\n           ELSE 'NO'\n       END AS V,\n\n       CASE\n           WHEN UPPER(np.FIELD_NAME) LIKE 'GK_%'\n           THEN 1\n           ELSE NULL\n       END AS SEQUENCE,\n\n       np.PORTTYPE AS PORTTYPE_CODE,\n\n       /* Properties tab */\n       CASE\n           WHEN npr.RESET_CODE IS NULL\n           THEN 'NO'\n           WHEN UPPER(TRIM(npr.RESET_CODE))\n                IN ('1', 'YES', 'Y', 'TRUE', 'CHECKED')\n           THEN 'YES'\n           WHEN UPPER(TRIM(npr.RESET_CODE))\n                IN ('0', 'NO', 'N', 'FALSE', 'UNCHECKED')\n           THEN 'NO'\n           ELSE npr.RESET_CODE\n       END AS RESET,\n\n       CASE\n           WHEN npr.RESTART_CODE IS NULL\n           THEN 'NO'\n           WHEN UPPER(TRIM(npr.RESTART_CODE))\n                IN ('1', 'YES', 'Y', 'TRUE', 'CHECKED')\n           THEN 'YES'\n           WHEN UPPER(TRIM(npr.RESTART_CODE))\n                IN ('0', 'NO', 'N', 'FALSE', 'UNCHECKED')\n           THEN 'NO'\n           ELSE npr.RESTART_CODE\n       END AS RESTART,\n\n       CASE\n           WHEN npr.TRACING_LEVEL_CODE IS NULL\n           THEN 'Normal'\n           WHEN UPPER(TRIM(npr.TRACING_LEVEL_CODE)) = '1'\n           THEN 'Terse'\n           WHEN UPPER(TRIM(npr.TRACING_LEVEL_CODE)) = '2'\n           THEN 'Normal'\n           WHEN UPPER(TRIM(npr.TRACING_LEVEL_CODE)) = '3'\n           THEN 'Verbose Initialization'\n           WHEN UPPER(TRIM(npr.TRACING_LEVEL_CODE)) = '4'\n           THEN 'Verbose Data'\n           WHEN UPPER(TRIM(npr.TRACING_LEVEL_CODE)) = 'TERSE'\n           THEN 'Terse'\n           WHEN UPPER(TRIM(npr.TRACING_LEVEL_CODE)) = 'NORMAL'\n           THEN 'Normal'\n           WHEN UPPER(TRIM(npr.TRACING_LEVEL_CODE)) =\n                'VERBOSE INITIALIZATION'\n           THEN 'Verbose Initialization'\n           WHEN UPPER(TRIM(npr.TRACING_LEVEL_CODE)) =\n                'VERBOSE DATA'\n           THEN 'Verbose Data'\n           ELSE\n               'Unknown ('\n               || npr.TRACING_LEVEL_CODE\n               || ')'\n       END AS TRACING_LEVEL,\n\n       /* Normalizer tab */\n       nt.COLUMN_NAME AS NORMALIZER_COLUMN_NAME,\n       nt.NORMALIZER_LEVEL,\n       nt.OCCURS AS NORMALIZER_OCCURS,\n\n       CASE nt.DATATYPE_CODE\n           WHEN -5 THEN 'string'\n           WHEN -4 THEN 'text'\n           WHEN -3 THEN 'binary'\n           WHEN -2 THEN 'varbinary'\n           WHEN -1 THEN 'long varbinary'\n           WHEN 0  THEN 'unknown'\n           WHEN 1  THEN 'small integer'\n           WHEN 2  THEN 'integer'\n           WHEN 3  THEN 'decimal'\n           WHEN 4  THEN 'real'\n           WHEN 5  THEN 'double'\n           WHEN 6  THEN 'date/time'\n           WHEN 7  THEN 'date/time'\n           WHEN 8  THEN 'date/time'\n           WHEN 9  THEN 'date/time'\n           WHEN 10 THEN 'string'\n           WHEN 11 THEN 'string'\n           WHEN 12 THEN 'string'\n           WHEN 13 THEN 'binary'\n           WHEN 14 THEN 'bigint'\n           WHEN 15 THEN 'double'\n           WHEN 16 THEN 'decimal'\n           WHEN 17 THEN 'boolean'\n           ELSE\n               CASE\n                   WHEN nt.DATATYPE_CODE IS NULL\n                   THEN NULL\n                   ELSE\n                       'Unknown ('\n                       || TO_CHAR(nt.DATATYPE_CODE)\n                       || ')'\n               END\n       END AS NORMALIZER_DATATYPE,\n\n       nt.DATATYPE_CODE AS NORMALIZER_DATATYPE_CODE,\n       nt.PRECISION AS NORMALIZER_PREC,\n       nt.SCALE AS NORMALIZER_SCALE,\n\n       /* Metadata Extensions tab */\n       nme.EXTENSION_NAME,\n       nme.EXTENSION_DATATYPE_CODE,\n\n       CASE nme.EXTENSION_DATATYPE_CODE\n           WHEN 1 THEN 'String'\n           WHEN 2 THEN 'Number'\n           WHEN 3 THEN 'Boolean'\n           ELSE\n               CASE\n                   WHEN nme.EXTENSION_DATATYPE_CODE IS NULL\n                   THEN NULL\n                   ELSE\n                       'Other ('\n                       || TO_CHAR(nme.EXTENSION_DATATYPE_CODE)\n                       || ')'\n               END\n       END AS EXTENSION_DATATYPE,\n\n       nme.EXTENSION_PREC,\n       nme.EXTENSION_VALUE,\n       nme.EXTENSION_REUSABLE AS REUSABLE,\n       nme.EXTENSION_PERMISSIONS,\n       nme.EXTENSION_LINE_NO,\n       nme.EXTENSION_DOMAIN_NAME,\n       nme.EXTENSION_DOMAIN_USAGE,\n       nme.EXTENSION_DESCRIPTION,\n\n       /* Connected transformation ports */\n       pc.PREVIOUS_TRANSFORMATION,\n       pc.NEXT_TRANSFORMATION_NAME\n\nFROM normalizer_instances ni\n\nJOIN normalizer_ports np\n  ON np.SUBJECT_ID = ni.SUBJECT_ID\n AND np.MAPPING_ID = ni.MAPPING_ID\n AND np.INSTANCE_ID = ni.INSTANCE_ID\n AND np.WIDGET_ID = ni.WIDGET_ID\n AND np.VERSION_NUMBER = ni.VERSION_NUMBER\n\nLEFT JOIN normalizer_properties npr\n  ON npr.SUBJECT_ID = ni.SUBJECT_ID\n AND npr.MAPPING_ID = ni.MAPPING_ID\n AND npr.INSTANCE_ID = ni.INSTANCE_ID\n AND npr.WIDGET_ID = ni.WIDGET_ID\n AND npr.VERSION_NUMBER = ni.VERSION_NUMBER\n\nLEFT JOIN normalizer_tab nt\n  ON nt.SUBJECT_ID = ni.SUBJECT_ID\n AND nt.MAPPING_ID = ni.MAPPING_ID\n AND nt.INSTANCE_ID = ni.INSTANCE_ID\n AND nt.WIDGET_ID = ni.WIDGET_ID\n AND nt.VERSION_NUMBER = ni.VERSION_NUMBER\n AND nt.COLUMN_NAME = np.NORMALIZER_COLUMN_NAME\n\nLEFT JOIN normalizer_metadata_extensions nme\n  ON nme.SUBJECT_ID = ni.SUBJECT_ID\n AND nme.WIDGET_ID = ni.WIDGET_ID\n AND nme.VERSION_NUMBER = ni.VERSION_NUMBER\n\nLEFT JOIN port_connections pc\n  ON pc.SUBJECT_ID = ni.SUBJECT_ID\n AND pc.MAPPING_ID = ni.MAPPING_ID\n AND pc.MAPPING_VERSION_NUMBER = ni.VERSION_NUMBER\n AND pc.INSTANCE_ID = ni.INSTANCE_ID\n AND pc.FIELD_NAME = np.FIELD_NAME\n\nORDER BY\n       ni.SUBJECT_AREA,\n       ni.WORKFLOW_NAME,\n       ni.SESSION_INSTANCE_NAME,\n       ni.SESSION_NAME,\n       ni.MAPPING_NAME,\n       ni.TRANSFORMATION_NAME,\n       np.FIELD_ORDER,\n       np.FIELD_NAME,\n       nme.EXTENSION_NAME,\n       nme.EXTENSION_LINE_NO;"}, 'ROUTER': {'label': 'Router', 'sql': "WITH workflow_mappings AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           s.SUBJECT_AREA,\n           s.SUBJECT_ID,\n           s.MAPPING_ID,\n           w.WORKFLOW_NAME,\n           ti.INSTANCE_NAME AS SESSION_INSTANCE_NAME,\n           s.SESSION_NAME\n    FROM M2R_REP_1053_P01.REP_WORKFLOWS w\n    JOIN M2R_REP_1053_P01.REP_TASK_INST ti\n      ON ti.WORKFLOW_ID = w.WORKFLOW_ID\n     AND ti.TASK_TYPE = 68\n    JOIN M2R_REP_1053_P01.REP_LOAD_SESSIONS s\n      ON s.SESSION_ID = ti.TASK_ID\n    WHERE w.SUBJECT_AREA = 'M2R_DTM'\n      AND w.WORKFLOW_NAME = 'WF_DTM_MMTR'\n),\nrouter_instances AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           wm.SUBJECT_AREA,\n           wm.SUBJECT_ID,\n           wm.WORKFLOW_NAME,\n           wm.SESSION_INSTANCE_NAME,\n           wm.SESSION_NAME,\n           wm.MAPPING_ID,\n           m.MAPPING_NAME,\n           wi.INSTANCE_ID,\n           wi.INSTANCE_NAME AS TRANSFORMATION_NAME,\n           wi.WIDGET_ID,\n           wi.WIDGET_TYPE,\n           wi.WIDGET_TYPE_NAME AS TRANSFORMATION_TYPE,\n           wi.VERSION_NUMBER\n    FROM workflow_mappings wm\n    JOIN M2R_REP_1053_P01.REP_ALL_MAPPINGS m\n      ON m.MAPPING_ID = wm.MAPPING_ID\n     AND m.SUBJECT_AREA = wm.SUBJECT_AREA\n    JOIN M2R_REP_1053_P01.REP_WIDGET_INST wi\n      ON wi.MAPPING_ID = wm.MAPPING_ID\n     AND wi.SUBJECT_ID = wm.SUBJECT_ID\n     AND UPPER(TRIM(wi.WIDGET_TYPE_NAME)) = 'ROUTER'\n),\nrelevant_transformations AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           WIDGET_TYPE,\n           VERSION_NUMBER\n    FROM router_instances\n),\nrouter_attribute_rows AS\n(\n    SELECT rt.SUBJECT_ID,\n           rt.MAPPING_ID,\n           rt.INSTANCE_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           wa.ATTR_ID,\n           UPPER(TRIM(wa.ATTR_NAME)) AS ATTR_NAME,\n           TRIM(wa.ATTR_VALUE) AS ATTR_VALUE\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_WIDGET_ATTR wa\n      ON wa.WIDGET_ID = rt.WIDGET_ID\n     AND wa.VERSION_NUMBER = rt.VERSION_NUMBER\n     AND (\n            wa.WIDGET_TYPE = rt.WIDGET_TYPE\n            OR wa.WIDGET_TYPE IS NULL\n         )\n     AND (\n            wa.INSTANCE_ID = rt.INSTANCE_ID\n            OR wa.INSTANCE_ID IS NULL\n            OR wa.INSTANCE_ID = 0\n         )\n     AND (\n            wa.MAPPING_ID = rt.MAPPING_ID\n            OR wa.MAPPING_ID IS NULL\n            OR wa.MAPPING_ID = 0\n         )\n),\nrouter_properties AS\n(\n    SELECT SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER,\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'TRACING LEVEL'\n                   THEN ATTR_VALUE\n               END\n           ) AS TRACING_LEVEL_CODE\n    FROM router_attribute_rows\n    GROUP BY\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER\n),\nrouter_groups AS\n(\n    SELECT rt.SUBJECT_ID,\n           rt.MAPPING_ID,\n           rt.INSTANCE_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           tg.GROUP_ID,\n\n           MAX(\n               CASE\n                   WHEN tg.ATTR_ID = 1\n                   THEN TRIM(tg.ATTR_VALUE)\n               END\n           ) AS GROUP_NAME,\n\n           MAX(\n               CASE\n                   WHEN tg.ATTR_ID = 3\n                   THEN TRIM(tg.ATTR_VALUE)\n               END\n           ) AS GROUP_FILTER_CONDITION\n\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.OPB_TABLE_GROUP tg\n      ON tg.OBJECT_ID = rt.WIDGET_ID\n     AND tg.VERSION_NUMBER = rt.VERSION_NUMBER\n     AND tg.OBJECT_TYPE = 15\n     AND tg.ATTR_ID IN (1, 3)\n    GROUP BY\n           rt.SUBJECT_ID,\n           rt.MAPPING_ID,\n           rt.INSTANCE_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           tg.GROUP_ID\n),\nrouter_metadata_extensions AS\n(\n    SELECT DISTINCT\n           rt.SUBJECT_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           mdx.METADATA_EXTN_NAME AS EXTENSION_NAME,\n           mdx.METADATA_EXTN_DATA_TYPE AS EXTENSION_DATATYPE_CODE,\n           mdx.METADATA_EXTN_VALUE AS EXTENSION_VALUE,\n           mdx.PERMISSIONS AS EXTENSION_PERMISSIONS,\n           mdx.LINE_NO AS EXTENSION_LINE_NO,\n           mdx.DOMAIN_NAME AS EXTENSION_DOMAIN_NAME,\n           mdx.DOMAIN_USAGE AS EXTENSION_DOMAIN_USAGE,\n           mdx.METADATA_EXTN_DESCRIPTION AS EXTENSION_DESCRIPTION,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NOT NULL\n               THEN LENGTH(mdx.METADATA_EXTN_VALUE)\n               ELSE NULL\n           END AS EXTENSION_PREC,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NULL\n               THEN NULL\n               WHEN mdx.DOMAIN_ID IS NOT NULL\n                 OR mdx.DOMAIN_NAME IS NOT NULL\n               THEN 'YES'\n               ELSE 'NO'\n           END AS EXTENSION_REUSABLE\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_METADATA_EXTNS mdx\n      ON mdx.SUBJECT_ID = rt.SUBJECT_ID\n     AND mdx.METADATA_EXTN_OBJECT_ID = rt.WIDGET_ID\n     AND mdx.VERSION_NUMBER = rt.VERSION_NUMBER\n),\nincoming_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.TO_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.TO_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.FROM_OBJECT_NAME\n               || '.'\n               || pc.FROM_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.TO_OBJECT_INSTANCE_ID\n    WHERE pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n),\noutgoing_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.FROM_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.FROM_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.TO_OBJECT_NAME\n               || '.'\n               || pc.TO_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.FROM_OBJECT_INSTANCE_ID\n    WHERE pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.TO_OBJECT_NAME IS NOT NULL\n      AND pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n),\nincoming_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM incoming_connections\n),\noutgoing_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM outgoing_connections\n),\nport_connections AS\n(\n    SELECT k.SUBJECT_ID,\n           k.MAPPING_ID,\n           k.MAPPING_VERSION_NUMBER,\n           k.INSTANCE_ID,\n           k.FIELD_NAME,\n           incoming.PREVIOUS_TRANSFORMATION,\n           outgoing.NEXT_TRANSFORMATION_NAME\n    FROM\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM incoming_connections_distinct\n\n        UNION\n\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM outgoing_connections_distinct\n    ) k\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS PREVIOUS_TRANSFORMATION\n        FROM incoming_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) incoming\n      ON incoming.SUBJECT_ID = k.SUBJECT_ID\n     AND incoming.MAPPING_ID = k.MAPPING_ID\n     AND incoming.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND incoming.INSTANCE_ID = k.INSTANCE_ID\n     AND incoming.FIELD_NAME = k.FIELD_NAME\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS NEXT_TRANSFORMATION_NAME\n        FROM outgoing_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) outgoing\n      ON outgoing.SUBJECT_ID = k.SUBJECT_ID\n     AND outgoing.MAPPING_ID = k.MAPPING_ID\n     AND outgoing.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND outgoing.INSTANCE_ID = k.INSTANCE_ID\n     AND outgoing.FIELD_NAME = k.FIELD_NAME\n)\nSELECT DISTINCT\n       ri.SUBJECT_AREA,\n       ri.WORKFLOW_NAME,\n       ri.SESSION_INSTANCE_NAME,\n       ri.SESSION_NAME,\n       ri.MAPPING_NAME,\n\n       /* Transformation tab */\n       ri.TRANSFORMATION_NAME,\n       ri.TRANSFORMATION_TYPE,\n\n       /* Ports tab */\n       wf.FIELD_ORDER AS PORT_ORDER,\n       wf.FIELD_NAME AS PORT_NAME,\n\n       CASE wf.WGT_DATATYPE\n           WHEN -5 THEN 'string'\n           WHEN -4 THEN 'text'\n           WHEN -3 THEN 'binary'\n           WHEN -2 THEN 'varbinary'\n           WHEN -1 THEN 'long varbinary'\n           WHEN 0  THEN 'unknown'\n           WHEN 1  THEN 'small integer'\n           WHEN 2  THEN 'integer'\n           WHEN 3  THEN 'decimal'\n           WHEN 4  THEN 'real'\n           WHEN 5  THEN 'double'\n           WHEN 6  THEN 'date/time'\n           WHEN 7  THEN 'date/time'\n           WHEN 8  THEN 'date/time'\n           WHEN 9  THEN 'date/time'\n           WHEN 10 THEN 'string'\n           WHEN 11 THEN 'string'\n           WHEN 12 THEN 'string'\n           WHEN 13 THEN 'binary'\n           WHEN 14 THEN 'bigint'\n           WHEN 15 THEN 'double'\n           WHEN 16 THEN 'decimal'\n           WHEN 17 THEN 'boolean'\n           ELSE\n               'Unknown ('\n               || TO_CHAR(wf.WGT_DATATYPE)\n               || ')'\n       END AS DATATYPE,\n\n       wf.WGT_DATATYPE AS DATATYPE_CODE,\n       wf.WGT_PREC AS PREC,\n       wf.WGT_SCALE AS SCALE,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 1) = 1\n           THEN 'YES'\n           ELSE 'NO'\n       END AS I,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 2) = 2\n           THEN 'YES'\n           ELSE 'NO'\n       END AS O,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 32) = 32\n           THEN 'YES'\n           ELSE 'NO'\n       END AS V,\n\n       wf.PORTTYPE AS PORTTYPE_CODE,\n\n       /* Properties tab */\n       CASE\n           WHEN rp.TRACING_LEVEL_CODE IS NULL\n           THEN 'Normal'\n           WHEN UPPER(TRIM(rp.TRACING_LEVEL_CODE)) = '1'\n           THEN 'Terse'\n           WHEN UPPER(TRIM(rp.TRACING_LEVEL_CODE)) = '2'\n           THEN 'Normal'\n           WHEN UPPER(TRIM(rp.TRACING_LEVEL_CODE)) = '3'\n           THEN 'Verbose Initialization'\n           WHEN UPPER(TRIM(rp.TRACING_LEVEL_CODE)) = '4'\n           THEN 'Verbose Data'\n           WHEN UPPER(TRIM(rp.TRACING_LEVEL_CODE)) = 'TERSE'\n           THEN 'Terse'\n           WHEN UPPER(TRIM(rp.TRACING_LEVEL_CODE)) = 'NORMAL'\n           THEN 'Normal'\n           WHEN UPPER(TRIM(rp.TRACING_LEVEL_CODE)) =\n                'VERBOSE INITIALIZATION'\n           THEN 'Verbose Initialization'\n           WHEN UPPER(TRIM(rp.TRACING_LEVEL_CODE)) =\n                'VERBOSE DATA'\n           THEN 'Verbose Data'\n           ELSE\n               'Unknown ('\n               || rp.TRACING_LEVEL_CODE\n               || ')'\n       END AS TRACING_LEVEL,\n\n       /* Groups tab */\n       rg.GROUP_ID,\n       rg.GROUP_NAME,\n       rg.GROUP_FILTER_CONDITION,\n\n       /* Metadata Extensions tab */\n       rme.EXTENSION_NAME,\n       rme.EXTENSION_DATATYPE_CODE,\n\n       CASE rme.EXTENSION_DATATYPE_CODE\n           WHEN 1 THEN 'String'\n           WHEN 2 THEN 'Number'\n           WHEN 3 THEN 'Boolean'\n           ELSE\n               CASE\n                   WHEN rme.EXTENSION_DATATYPE_CODE IS NULL\n                   THEN NULL\n                   ELSE\n                       'Other ('\n                       || TO_CHAR(rme.EXTENSION_DATATYPE_CODE)\n                       || ')'\n               END\n       END AS EXTENSION_DATATYPE,\n\n       rme.EXTENSION_PREC,\n       rme.EXTENSION_VALUE,\n       rme.EXTENSION_REUSABLE AS REUSABLE,\n       rme.EXTENSION_PERMISSIONS,\n       rme.EXTENSION_LINE_NO,\n       rme.EXTENSION_DOMAIN_NAME,\n       rme.EXTENSION_DOMAIN_USAGE,\n       rme.EXTENSION_DESCRIPTION,\n\n       /* Connected transformation ports */\n       pc.PREVIOUS_TRANSFORMATION,\n       pc.NEXT_TRANSFORMATION_NAME\n\nFROM router_instances ri\n\nJOIN M2R_REP_1053_P01.OPB_WIDGET_FIELD wf\n  ON wf.WIDGET_ID = ri.WIDGET_ID\n AND wf.VERSION_NUMBER = ri.VERSION_NUMBER\n\nLEFT JOIN router_properties rp\n  ON rp.SUBJECT_ID = ri.SUBJECT_ID\n AND rp.MAPPING_ID = ri.MAPPING_ID\n AND rp.INSTANCE_ID = ri.INSTANCE_ID\n AND rp.WIDGET_ID = ri.WIDGET_ID\n AND rp.VERSION_NUMBER = ri.VERSION_NUMBER\n\nLEFT JOIN router_groups rg\n  ON rg.SUBJECT_ID = ri.SUBJECT_ID\n AND rg.MAPPING_ID = ri.MAPPING_ID\n AND rg.INSTANCE_ID = ri.INSTANCE_ID\n AND rg.WIDGET_ID = ri.WIDGET_ID\n AND rg.VERSION_NUMBER = ri.VERSION_NUMBER\n\nLEFT JOIN router_metadata_extensions rme\n  ON rme.SUBJECT_ID = ri.SUBJECT_ID\n AND rme.WIDGET_ID = ri.WIDGET_ID\n AND rme.VERSION_NUMBER = ri.VERSION_NUMBER\n\nLEFT JOIN port_connections pc\n  ON pc.SUBJECT_ID = ri.SUBJECT_ID\n AND pc.MAPPING_ID = ri.MAPPING_ID\n AND pc.MAPPING_VERSION_NUMBER = ri.VERSION_NUMBER\n AND pc.INSTANCE_ID = ri.INSTANCE_ID\n AND pc.FIELD_NAME = wf.FIELD_NAME\n\nORDER BY\n       ri.SUBJECT_AREA,\n       ri.WORKFLOW_NAME,\n       ri.SESSION_INSTANCE_NAME,\n       ri.SESSION_NAME,\n       ri.MAPPING_NAME,\n       ri.TRANSFORMATION_NAME,\n       wf.FIELD_ORDER,\n       wf.FIELD_NAME,\n       rg.GROUP_ID,\n       rme.EXTENSION_NAME,\n       rme.EXTENSION_LINE_NO;"}, 'AGGREGATOR': {'label': 'Aggregator', 'sql': "WITH workflow_mappings AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           s.SUBJECT_AREA,\n           s.SUBJECT_ID,\n           s.MAPPING_ID,\n           w.WORKFLOW_NAME,\n           ti.INSTANCE_NAME AS SESSION_INSTANCE_NAME,\n           s.SESSION_NAME\n    FROM M2R_REP_1053_P01.REP_WORKFLOWS w\n    JOIN M2R_REP_1053_P01.REP_TASK_INST ti\n      ON ti.WORKFLOW_ID = w.WORKFLOW_ID\n     AND ti.TASK_TYPE = 68\n    JOIN M2R_REP_1053_P01.REP_LOAD_SESSIONS s\n      ON s.SESSION_ID = ti.TASK_ID\n    WHERE w.SUBJECT_AREA = 'M2R_DTM'\n      AND w.WORKFLOW_NAME = 'WF_DTM_MMTR'\n),\naggregator_instances AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           wm.SUBJECT_AREA,\n           wm.SUBJECT_ID,\n           wm.WORKFLOW_NAME,\n           wm.SESSION_INSTANCE_NAME,\n           wm.SESSION_NAME,\n           wm.MAPPING_ID,\n           m.MAPPING_NAME,\n           wi.INSTANCE_ID,\n           wi.INSTANCE_NAME AS TRANSFORMATION_NAME,\n           wi.WIDGET_ID,\n           wi.WIDGET_TYPE,\n           wi.WIDGET_TYPE_NAME AS TRANSFORMATION_TYPE,\n           wi.VERSION_NUMBER\n    FROM workflow_mappings wm\n    JOIN M2R_REP_1053_P01.REP_ALL_MAPPINGS m\n      ON m.MAPPING_ID = wm.MAPPING_ID\n     AND m.SUBJECT_AREA = wm.SUBJECT_AREA\n    JOIN M2R_REP_1053_P01.REP_WIDGET_INST wi\n      ON wi.MAPPING_ID = wm.MAPPING_ID\n     AND wi.SUBJECT_ID = wm.SUBJECT_ID\n     AND UPPER(TRIM(wi.WIDGET_TYPE_NAME)) = 'AGGREGATOR'\n),\nrelevant_transformations AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           WIDGET_TYPE,\n           VERSION_NUMBER\n    FROM aggregator_instances\n),\naggregator_attribute_rows AS\n(\n    SELECT rt.SUBJECT_ID,\n           rt.MAPPING_ID,\n           rt.INSTANCE_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           wa.ATTR_ID,\n           UPPER(TRIM(wa.ATTR_NAME)) AS ATTR_NAME,\n           TRIM(wa.ATTR_VALUE) AS ATTR_VALUE\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_WIDGET_ATTR wa\n      ON wa.WIDGET_ID = rt.WIDGET_ID\n     AND wa.VERSION_NUMBER = rt.VERSION_NUMBER\n     AND\n         (\n             wa.WIDGET_TYPE = rt.WIDGET_TYPE\n             OR wa.WIDGET_TYPE IS NULL\n         )\n     AND\n         (\n             wa.INSTANCE_ID = rt.INSTANCE_ID\n             OR wa.INSTANCE_ID IS NULL\n             OR wa.INSTANCE_ID = 0\n         )\n     AND\n         (\n             wa.MAPPING_ID = rt.MAPPING_ID\n             OR wa.MAPPING_ID IS NULL\n             OR wa.MAPPING_ID = 0\n         )\n),\naggregator_properties AS\n(\n    SELECT SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'CACHE DIRECTORY',\n                            'CACHE DIR'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS CACHE_DIRECTORY,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'TRACING LEVEL'\n                   THEN ATTR_VALUE\n               END\n           ) AS TRACING_LEVEL_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'SORTED INPUT',\n                            'SORTED INPUT OPTION'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS SORTED_INPUT_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'AGGREGATOR DATA CACHE SIZE',\n                            'DATA CACHE SIZE'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS AGGREGATOR_DATA_CACHE_SIZE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'AGGREGATOR INDEX CACHE SIZE',\n                            'INDEX CACHE SIZE'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS AGGREGATOR_INDEX_CACHE_SIZE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'TRANSFORMATION SCOPE'\n                   THEN ATTR_VALUE\n               END\n           ) AS TRANSFORMATION_SCOPE_CODE\n\n    FROM aggregator_attribute_rows\n    GROUP BY\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER\n),\naggregator_port_expressions AS\n(\n    SELECT wf.WIDGET_ID,\n           wf.VERSION_NUMBER,\n           wf.FIELD_ID,\n           LISTAGG(oe.EXPRESSION, ' ')\n               WITHIN GROUP (ORDER BY oe.LINE_NO) AS EXPRESSION\n    FROM M2R_REP_1053_P01.OPB_WIDGET_FIELD wf\n    JOIN relevant_transformations rt\n      ON rt.WIDGET_ID = wf.WIDGET_ID\n     AND rt.VERSION_NUMBER = wf.VERSION_NUMBER\n    LEFT JOIN M2R_REP_1053_P01.OPB_WIDGET_EXPR we\n      ON we.WIDGET_ID = wf.WIDGET_ID\n     AND we.OUTPUT_FIELD_ID = wf.FIELD_ID\n     AND we.VERSION_NUMBER = wf.VERSION_NUMBER\n    LEFT JOIN M2R_REP_1053_P01.OPB_EXPRESSION oe\n      ON oe.WIDGET_ID = we.WIDGET_ID\n     AND oe.EXPR_ID = we.EXPR_ID\n     AND oe.VERSION_NUMBER = we.VERSION_NUMBER\n    GROUP BY\n           wf.WIDGET_ID,\n           wf.VERSION_NUMBER,\n           wf.FIELD_ID\n),\naggregator_metadata_extensions AS\n(\n    SELECT DISTINCT\n           rt.SUBJECT_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           mdx.METADATA_EXTN_NAME AS EXTENSION_NAME,\n           mdx.METADATA_EXTN_DATA_TYPE AS EXTENSION_DATATYPE_CODE,\n           mdx.METADATA_EXTN_VALUE AS EXTENSION_VALUE,\n           mdx.PERMISSIONS AS EXTENSION_PERMISSIONS,\n           mdx.LINE_NO AS EXTENSION_LINE_NO,\n           mdx.DOMAIN_NAME AS EXTENSION_DOMAIN_NAME,\n           mdx.DOMAIN_USAGE AS EXTENSION_DOMAIN_USAGE,\n           mdx.METADATA_EXTN_DESCRIPTION AS EXTENSION_DESCRIPTION,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NOT NULL\n               THEN LENGTH(mdx.METADATA_EXTN_VALUE)\n           END AS EXTENSION_PREC,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NULL\n               THEN NULL\n               WHEN mdx.DOMAIN_ID IS NOT NULL\n                 OR mdx.DOMAIN_NAME IS NOT NULL\n               THEN 'YES'\n               ELSE 'NO'\n           END AS EXTENSION_REUSABLE\n\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_METADATA_EXTNS mdx\n      ON mdx.SUBJECT_ID = rt.SUBJECT_ID\n     AND mdx.METADATA_EXTN_OBJECT_ID = rt.WIDGET_ID\n     AND mdx.VERSION_NUMBER = rt.VERSION_NUMBER\n),\nincoming_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.TO_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.TO_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.FROM_OBJECT_NAME\n               || '.'\n               || pc.FROM_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.TO_OBJECT_INSTANCE_ID\n    WHERE pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n),\noutgoing_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.FROM_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.FROM_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.TO_OBJECT_NAME\n               || '.'\n               || pc.TO_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.FROM_OBJECT_INSTANCE_ID\n    WHERE pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.TO_OBJECT_NAME IS NOT NULL\n      AND pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n),\nincoming_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM incoming_connections\n),\noutgoing_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM outgoing_connections\n),\nport_connections AS\n(\n    SELECT k.SUBJECT_ID,\n           k.MAPPING_ID,\n           k.MAPPING_VERSION_NUMBER,\n           k.INSTANCE_ID,\n           k.FIELD_NAME,\n           incoming.PREVIOUS_TRANSFORMATION,\n           outgoing.NEXT_TRANSFORMATION_NAME\n    FROM\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM incoming_connections_distinct\n\n        UNION\n\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM outgoing_connections_distinct\n    ) k\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS PREVIOUS_TRANSFORMATION\n        FROM incoming_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) incoming\n      ON incoming.SUBJECT_ID = k.SUBJECT_ID\n     AND incoming.MAPPING_ID = k.MAPPING_ID\n     AND incoming.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND incoming.INSTANCE_ID = k.INSTANCE_ID\n     AND incoming.FIELD_NAME = k.FIELD_NAME\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS NEXT_TRANSFORMATION_NAME\n        FROM outgoing_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) outgoing\n      ON outgoing.SUBJECT_ID = k.SUBJECT_ID\n     AND outgoing.MAPPING_ID = k.MAPPING_ID\n     AND outgoing.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND outgoing.INSTANCE_ID = k.INSTANCE_ID\n     AND outgoing.FIELD_NAME = k.FIELD_NAME\n)\nSELECT DISTINCT\n       ai.SUBJECT_AREA,\n       ai.WORKFLOW_NAME,\n       ai.SESSION_INSTANCE_NAME,\n       ai.SESSION_NAME,\n       ai.MAPPING_NAME,\n\n       /* Transformation tab */\n       ai.TRANSFORMATION_NAME,\n       ai.TRANSFORMATION_TYPE,\n\n       /* Ports tab */\n       wf.FIELD_ORDER AS PORT_ORDER,\n       wf.FIELD_NAME AS PORT_NAME,\n\n       CASE wf.WGT_DATATYPE\n           WHEN -5 THEN 'string'\n           WHEN -4 THEN 'text'\n           WHEN -3 THEN 'binary'\n           WHEN -2 THEN 'varbinary'\n           WHEN -1 THEN 'long varbinary'\n           WHEN 0  THEN 'unknown'\n           WHEN 1  THEN 'small integer'\n           WHEN 2  THEN 'integer'\n           WHEN 3  THEN 'decimal'\n           WHEN 4  THEN 'real'\n           WHEN 5  THEN 'double'\n           WHEN 6  THEN 'date/time'\n           WHEN 7  THEN 'date/time'\n           WHEN 8  THEN 'date/time'\n           WHEN 9  THEN 'date/time'\n           WHEN 10 THEN 'string'\n           WHEN 11 THEN 'string'\n           WHEN 12 THEN 'string'\n           WHEN 13 THEN 'binary'\n           WHEN 14 THEN 'bigint'\n           WHEN 15 THEN 'double'\n           WHEN 16 THEN 'decimal'\n           WHEN 17 THEN 'boolean'\n           ELSE\n               'Unknown ('\n               || TO_CHAR(wf.WGT_DATATYPE)\n               || ')'\n       END AS DATATYPE,\n\n       wf.WGT_DATATYPE AS DATATYPE_CODE,\n       wf.WGT_PREC AS PREC,\n       wf.WGT_SCALE AS SCALE,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 1) = 1\n           THEN 'YES'\n           ELSE 'NO'\n       END AS I,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 2) = 2\n           THEN 'YES'\n           ELSE 'NO'\n       END AS O,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 32) = 32\n           THEN 'YES'\n           ELSE 'NO'\n       END AS V,\n\n       ape.EXPRESSION,\n\n       CAST(NULL AS VARCHAR2(3)) AS GROUP_BY,\n\n       wf.PORTTYPE AS PORTTYPE_CODE,\n\n       /* Properties tab */\n       NVL(\n           ap.CACHE_DIRECTORY,\n           '$PMCacheDir'\n       ) AS CACHE_DIRECTORY,\n\n       CASE\n           WHEN ap.TRACING_LEVEL_CODE IS NULL\n           THEN 'Normal'\n           WHEN UPPER(TRIM(ap.TRACING_LEVEL_CODE)) = '1'\n           THEN 'Terse'\n           WHEN UPPER(TRIM(ap.TRACING_LEVEL_CODE)) = '2'\n           THEN 'Normal'\n           WHEN UPPER(TRIM(ap.TRACING_LEVEL_CODE)) = '3'\n           THEN 'Verbose Initialization'\n           WHEN UPPER(TRIM(ap.TRACING_LEVEL_CODE)) = '4'\n           THEN 'Verbose Data'\n           WHEN UPPER(TRIM(ap.TRACING_LEVEL_CODE)) = 'TERSE'\n           THEN 'Terse'\n           WHEN UPPER(TRIM(ap.TRACING_LEVEL_CODE)) = 'NORMAL'\n           THEN 'Normal'\n           WHEN UPPER(TRIM(ap.TRACING_LEVEL_CODE)) =\n                'VERBOSE INITIALIZATION'\n           THEN 'Verbose Initialization'\n           WHEN UPPER(TRIM(ap.TRACING_LEVEL_CODE)) =\n                'VERBOSE DATA'\n           THEN 'Verbose Data'\n           ELSE\n               'Unknown ('\n               || ap.TRACING_LEVEL_CODE\n               || ')'\n       END AS TRACING_LEVEL,\n\n       CASE\n           WHEN ap.SORTED_INPUT_CODE IS NULL\n           THEN 'NO'\n           WHEN UPPER(TRIM(ap.SORTED_INPUT_CODE))\n                IN ('1', 'YES', 'Y', 'TRUE', 'CHECKED')\n           THEN 'YES'\n           WHEN UPPER(TRIM(ap.SORTED_INPUT_CODE))\n                IN ('0', 'NO', 'N', 'FALSE', 'UNCHECKED')\n           THEN 'NO'\n           ELSE ap.SORTED_INPUT_CODE\n       END AS SORTED_INPUT,\n\n       NVL(\n           ap.AGGREGATOR_DATA_CACHE_SIZE,\n           'Auto'\n       ) AS AGGREGATOR_DATA_CACHE_SIZE,\n\n       NVL(\n           ap.AGGREGATOR_INDEX_CACHE_SIZE,\n           'Auto'\n       ) AS AGGREGATOR_INDEX_CACHE_SIZE,\n\n       CASE\n           WHEN ap.TRANSFORMATION_SCOPE_CODE IS NULL\n           THEN 'All Input'\n           WHEN UPPER(TRIM(ap.TRANSFORMATION_SCOPE_CODE)) = '0'\n           THEN 'All Input'\n           WHEN UPPER(TRIM(ap.TRANSFORMATION_SCOPE_CODE)) = '1'\n           THEN 'Transaction'\n           WHEN UPPER(TRIM(ap.TRANSFORMATION_SCOPE_CODE)) = '2'\n           THEN 'Row'\n           WHEN UPPER(TRIM(ap.TRANSFORMATION_SCOPE_CODE)) =\n                'ALL INPUT'\n           THEN 'All Input'\n           WHEN UPPER(TRIM(ap.TRANSFORMATION_SCOPE_CODE)) =\n                'TRANSACTION'\n           THEN 'Transaction'\n           WHEN UPPER(TRIM(ap.TRANSFORMATION_SCOPE_CODE)) = 'ROW'\n           THEN 'Row'\n           ELSE ap.TRANSFORMATION_SCOPE_CODE\n       END AS TRANSFORMATION_SCOPE,\n\n       /* Metadata Extensions tab */\n       ame.EXTENSION_NAME,\n       ame.EXTENSION_DATATYPE_CODE,\n\n       CASE ame.EXTENSION_DATATYPE_CODE\n           WHEN 1 THEN 'String'\n           WHEN 2 THEN 'Number'\n           WHEN 3 THEN 'Boolean'\n           ELSE\n               CASE\n                   WHEN ame.EXTENSION_DATATYPE_CODE IS NULL\n                   THEN NULL\n                   ELSE\n                       'Other ('\n                       || TO_CHAR(ame.EXTENSION_DATATYPE_CODE)\n                       || ')'\n               END\n       END AS EXTENSION_DATATYPE,\n\n       ame.EXTENSION_PREC,\n       ame.EXTENSION_VALUE,\n       ame.EXTENSION_REUSABLE AS REUSABLE,\n       ame.EXTENSION_PERMISSIONS,\n       ame.EXTENSION_LINE_NO,\n       ame.EXTENSION_DOMAIN_NAME,\n       ame.EXTENSION_DOMAIN_USAGE,\n       ame.EXTENSION_DESCRIPTION,\n\n       /* Connected transformation ports */\n       pc.PREVIOUS_TRANSFORMATION,\n       pc.NEXT_TRANSFORMATION_NAME\n\nFROM aggregator_instances ai\n\nJOIN M2R_REP_1053_P01.OPB_WIDGET_FIELD wf\n  ON wf.WIDGET_ID = ai.WIDGET_ID\n AND wf.VERSION_NUMBER = ai.VERSION_NUMBER\n\nLEFT JOIN aggregator_port_expressions ape\n  ON ape.WIDGET_ID = wf.WIDGET_ID\n AND ape.VERSION_NUMBER = wf.VERSION_NUMBER\n AND ape.FIELD_ID = wf.FIELD_ID\n\nLEFT JOIN aggregator_properties ap\n  ON ap.SUBJECT_ID = ai.SUBJECT_ID\n AND ap.MAPPING_ID = ai.MAPPING_ID\n AND ap.INSTANCE_ID = ai.INSTANCE_ID\n AND ap.WIDGET_ID = ai.WIDGET_ID\n AND ap.VERSION_NUMBER = ai.VERSION_NUMBER\n\nLEFT JOIN aggregator_metadata_extensions ame\n  ON ame.SUBJECT_ID = ai.SUBJECT_ID\n AND ame.WIDGET_ID = ai.WIDGET_ID\n AND ame.VERSION_NUMBER = ai.VERSION_NUMBER\n\nLEFT JOIN port_connections pc\n  ON pc.SUBJECT_ID = ai.SUBJECT_ID\n AND pc.MAPPING_ID = ai.MAPPING_ID\n AND pc.MAPPING_VERSION_NUMBER = ai.VERSION_NUMBER\n AND pc.INSTANCE_ID = ai.INSTANCE_ID\n AND pc.FIELD_NAME = wf.FIELD_NAME\n\nORDER BY\n       ai.SUBJECT_AREA,\n       ai.WORKFLOW_NAME,\n       ai.SESSION_INSTANCE_NAME,\n       ai.SESSION_NAME,\n       ai.MAPPING_NAME,\n       ai.TRANSFORMATION_NAME,\n       wf.FIELD_ORDER,\n       wf.FIELD_NAME,\n       ame.EXTENSION_NAME,\n       ame.EXTENSION_LINE_NO;"}, 'UPDATESTRATEGY': {'label': 'Update strategy', 'sql': "WITH workflow_mappings AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           s.SUBJECT_AREA,\n           s.SUBJECT_ID,\n           s.MAPPING_ID,\n           w.WORKFLOW_NAME,\n           ti.INSTANCE_NAME AS SESSION_INSTANCE_NAME,\n           s.SESSION_NAME\n    FROM M2R_REP_1053_P01.REP_WORKFLOWS w\n    JOIN M2R_REP_1053_P01.REP_TASK_INST ti\n      ON ti.WORKFLOW_ID = w.WORKFLOW_ID\n     AND ti.TASK_TYPE = 68\n    JOIN M2R_REP_1053_P01.REP_LOAD_SESSIONS s\n      ON s.SESSION_ID = ti.TASK_ID\n    WHERE w.SUBJECT_AREA = 'M2R_DTM'\n      AND w.WORKFLOW_NAME = 'WF_DTM_MMTR'\n),\nupdate_strategy_instances AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           wm.SUBJECT_AREA,\n           wm.SUBJECT_ID,\n           wm.WORKFLOW_NAME,\n           wm.SESSION_INSTANCE_NAME,\n           wm.SESSION_NAME,\n           wm.MAPPING_ID,\n           m.MAPPING_NAME,\n           wi.INSTANCE_ID,\n           wi.INSTANCE_NAME AS TRANSFORMATION_NAME,\n           wi.WIDGET_ID,\n           wi.WIDGET_TYPE,\n           wi.WIDGET_TYPE_NAME AS TRANSFORMATION_TYPE,\n           wi.VERSION_NUMBER\n    FROM workflow_mappings wm\n    JOIN M2R_REP_1053_P01.REP_ALL_MAPPINGS m\n      ON m.MAPPING_ID = wm.MAPPING_ID\n     AND m.SUBJECT_AREA = wm.SUBJECT_AREA\n    JOIN M2R_REP_1053_P01.REP_WIDGET_INST wi\n      ON wi.MAPPING_ID = wm.MAPPING_ID\n     AND wi.SUBJECT_ID = wm.SUBJECT_ID\n     AND UPPER(TRIM(wi.WIDGET_TYPE_NAME)) = 'UPDATE STRATEGY'\n),\nrelevant_transformations AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           WIDGET_TYPE,\n           VERSION_NUMBER\n    FROM update_strategy_instances\n),\nupdate_strategy_attribute_rows AS\n(\n    SELECT rt.SUBJECT_ID,\n           rt.MAPPING_ID,\n           rt.INSTANCE_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           wa.ATTR_ID,\n           UPPER(TRIM(wa.ATTR_NAME)) AS ATTR_NAME,\n           TRIM(wa.ATTR_VALUE) AS ATTR_VALUE\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_WIDGET_ATTR wa\n      ON wa.WIDGET_ID = rt.WIDGET_ID\n     AND wa.VERSION_NUMBER = rt.VERSION_NUMBER\n     AND\n         (\n             wa.WIDGET_TYPE = rt.WIDGET_TYPE\n             OR wa.WIDGET_TYPE IS NULL\n         )\n     AND\n         (\n             wa.INSTANCE_ID = rt.INSTANCE_ID\n             OR wa.INSTANCE_ID IS NULL\n             OR wa.INSTANCE_ID = 0\n         )\n     AND\n         (\n             wa.MAPPING_ID = rt.MAPPING_ID\n             OR wa.MAPPING_ID IS NULL\n             OR wa.MAPPING_ID = 0\n         )\n),\nupdate_strategy_properties AS\n(\n    SELECT SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'UPDATE STRATEGY EXPRESSION',\n                            'UPDATE STRATEGY',\n                            'UPDATE EXPRESSION'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS UPDATE_STRATEGY_EXPRESSION,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'FORWARD REJECTED ROWS',\n                            'FORWARD REJECTED ROW'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS FORWARD_REJECTED_ROWS_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'TRACING LEVEL'\n                   THEN ATTR_VALUE\n               END\n           ) AS TRACING_LEVEL_CODE\n\n    FROM update_strategy_attribute_rows\n    GROUP BY\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER\n),\nupdate_strategy_metadata_extensions AS\n(\n    SELECT DISTINCT\n           rt.SUBJECT_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           mdx.METADATA_EXTN_NAME AS EXTENSION_NAME,\n           mdx.METADATA_EXTN_DATA_TYPE AS EXTENSION_DATATYPE_CODE,\n           mdx.METADATA_EXTN_VALUE AS EXTENSION_VALUE,\n           mdx.PERMISSIONS AS EXTENSION_PERMISSIONS,\n           mdx.LINE_NO AS EXTENSION_LINE_NO,\n           mdx.DOMAIN_NAME AS EXTENSION_DOMAIN_NAME,\n           mdx.DOMAIN_USAGE AS EXTENSION_DOMAIN_USAGE,\n           mdx.METADATA_EXTN_DESCRIPTION AS EXTENSION_DESCRIPTION,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NOT NULL\n               THEN LENGTH(mdx.METADATA_EXTN_VALUE)\n               ELSE NULL\n           END AS EXTENSION_PREC,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NULL\n               THEN NULL\n               WHEN mdx.DOMAIN_ID IS NOT NULL\n                 OR mdx.DOMAIN_NAME IS NOT NULL\n               THEN 'YES'\n               ELSE 'NO'\n           END AS EXTENSION_REUSABLE\n\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_METADATA_EXTNS mdx\n      ON mdx.SUBJECT_ID = rt.SUBJECT_ID\n     AND mdx.METADATA_EXTN_OBJECT_ID = rt.WIDGET_ID\n     AND mdx.VERSION_NUMBER = rt.VERSION_NUMBER\n),\nincoming_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.TO_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.TO_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.FROM_OBJECT_NAME\n               || '.'\n               || pc.FROM_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.TO_OBJECT_INSTANCE_ID\n    WHERE pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n),\noutgoing_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.FROM_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.FROM_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.TO_OBJECT_NAME\n               || '.'\n               || pc.TO_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.FROM_OBJECT_INSTANCE_ID\n    WHERE pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.TO_OBJECT_NAME IS NOT NULL\n      AND pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n),\nincoming_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM incoming_connections\n),\noutgoing_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           CONNECTED_PORT\n    FROM outgoing_connections\n),\nport_connections AS\n(\n    SELECT k.SUBJECT_ID,\n           k.MAPPING_ID,\n           k.MAPPING_VERSION_NUMBER,\n           k.INSTANCE_ID,\n           k.FIELD_NAME,\n           incoming.PREVIOUS_TRANSFORMATION,\n           outgoing.NEXT_TRANSFORMATION_NAME\n    FROM\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM incoming_connections_distinct\n\n        UNION\n\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM outgoing_connections_distinct\n    ) k\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS PREVIOUS_TRANSFORMATION\n        FROM incoming_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) incoming\n      ON incoming.SUBJECT_ID = k.SUBJECT_ID\n     AND incoming.MAPPING_ID = k.MAPPING_ID\n     AND incoming.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND incoming.INSTANCE_ID = k.INSTANCE_ID\n     AND incoming.FIELD_NAME = k.FIELD_NAME\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS NEXT_TRANSFORMATION_NAME\n        FROM outgoing_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) outgoing\n      ON outgoing.SUBJECT_ID = k.SUBJECT_ID\n     AND outgoing.MAPPING_ID = k.MAPPING_ID\n     AND outgoing.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND outgoing.INSTANCE_ID = k.INSTANCE_ID\n     AND outgoing.FIELD_NAME = k.FIELD_NAME\n)\nSELECT DISTINCT\n       usi.SUBJECT_AREA,\n       usi.WORKFLOW_NAME,\n       usi.SESSION_INSTANCE_NAME,\n       usi.SESSION_NAME,\n       usi.MAPPING_NAME,\n\n       /* Transformation tab */\n       usi.TRANSFORMATION_NAME,\n       usi.TRANSFORMATION_TYPE,\n\n       /* Ports tab */\n       wf.FIELD_ORDER AS PORT_ORDER,\n       wf.FIELD_NAME AS PORT_NAME,\n\n       CASE wf.WGT_DATATYPE\n           WHEN -5 THEN 'string'\n           WHEN -4 THEN 'text'\n           WHEN -3 THEN 'binary'\n           WHEN -2 THEN 'varbinary'\n           WHEN -1 THEN 'long varbinary'\n           WHEN 0  THEN 'unknown'\n           WHEN 1  THEN 'small integer'\n           WHEN 2  THEN 'integer'\n           WHEN 3  THEN 'decimal'\n           WHEN 4  THEN 'real'\n           WHEN 5  THEN 'double'\n           WHEN 6  THEN 'date/time'\n           WHEN 7  THEN 'date/time'\n           WHEN 8  THEN 'date/time'\n           WHEN 9  THEN 'date/time'\n           WHEN 10 THEN 'string'\n           WHEN 11 THEN 'string'\n           WHEN 12 THEN 'string'\n           WHEN 13 THEN 'binary'\n           WHEN 14 THEN 'bigint'\n           WHEN 15 THEN 'double'\n           WHEN 16 THEN 'decimal'\n           WHEN 17 THEN 'boolean'\n           ELSE\n               'Unknown ('\n               || TO_CHAR(wf.WGT_DATATYPE)\n               || ')'\n       END AS DATATYPE,\n\n       wf.WGT_DATATYPE AS DATATYPE_CODE,\n       wf.WGT_PREC AS PREC,\n       wf.WGT_SCALE AS SCALE,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 1) = 1\n           THEN 'YES'\n           ELSE 'NO'\n       END AS I,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 2) = 2\n           THEN 'YES'\n           ELSE 'NO'\n       END AS O,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 32) = 32\n           THEN 'YES'\n           ELSE 'NO'\n       END AS V,\n\n       wf.PORTTYPE AS PORTTYPE_CODE,\n\n       /* Properties tab */\n       usp.UPDATE_STRATEGY_EXPRESSION,\n\n       CASE\n           WHEN usp.FORWARD_REJECTED_ROWS_CODE IS NULL\n           THEN 'NO'\n           WHEN UPPER(TRIM(usp.FORWARD_REJECTED_ROWS_CODE))\n                IN ('1', 'YES', 'Y', 'TRUE', 'CHECKED')\n           THEN 'YES'\n           WHEN UPPER(TRIM(usp.FORWARD_REJECTED_ROWS_CODE))\n                IN ('0', 'NO', 'N', 'FALSE', 'UNCHECKED')\n           THEN 'NO'\n           ELSE usp.FORWARD_REJECTED_ROWS_CODE\n       END AS FORWARD_REJECTED_ROWS,\n\n       CASE\n           WHEN usp.TRACING_LEVEL_CODE IS NULL\n           THEN 'Normal'\n           WHEN UPPER(TRIM(usp.TRACING_LEVEL_CODE)) = '1'\n           THEN 'Terse'\n           WHEN UPPER(TRIM(usp.TRACING_LEVEL_CODE)) = '2'\n           THEN 'Normal'\n           WHEN UPPER(TRIM(usp.TRACING_LEVEL_CODE)) = '3'\n           THEN 'Verbose Initialization'\n           WHEN UPPER(TRIM(usp.TRACING_LEVEL_CODE)) = '4'\n           THEN 'Verbose Data'\n           WHEN UPPER(TRIM(usp.TRACING_LEVEL_CODE)) = 'TERSE'\n           THEN 'Terse'\n           WHEN UPPER(TRIM(usp.TRACING_LEVEL_CODE)) = 'NORMAL'\n           THEN 'Normal'\n           WHEN UPPER(TRIM(usp.TRACING_LEVEL_CODE)) =\n                'VERBOSE INITIALIZATION'\n           THEN 'Verbose Initialization'\n           WHEN UPPER(TRIM(usp.TRACING_LEVEL_CODE)) =\n                'VERBOSE DATA'\n           THEN 'Verbose Data'\n           ELSE\n               'Unknown ('\n               || usp.TRACING_LEVEL_CODE\n               || ')'\n       END AS TRACING_LEVEL,\n\n       /* Metadata Extensions tab */\n       usme.EXTENSION_NAME,\n       usme.EXTENSION_DATATYPE_CODE,\n\n       CASE usme.EXTENSION_DATATYPE_CODE\n           WHEN 1 THEN 'String'\n           WHEN 2 THEN 'Number'\n           WHEN 3 THEN 'Boolean'\n           ELSE\n               CASE\n                   WHEN usme.EXTENSION_DATATYPE_CODE IS NULL\n                   THEN NULL\n                   ELSE\n                       'Other ('\n                       || TO_CHAR(usme.EXTENSION_DATATYPE_CODE)\n                       || ')'\n               END\n       END AS EXTENSION_DATATYPE,\n\n       usme.EXTENSION_PREC,\n       usme.EXTENSION_VALUE,\n       usme.EXTENSION_REUSABLE AS REUSABLE,\n       usme.EXTENSION_PERMISSIONS,\n       usme.EXTENSION_LINE_NO,\n       usme.EXTENSION_DOMAIN_NAME,\n       usme.EXTENSION_DOMAIN_USAGE,\n       usme.EXTENSION_DESCRIPTION,\n\n       /* Connected transformation ports */\n       pc.PREVIOUS_TRANSFORMATION,\n       pc.NEXT_TRANSFORMATION_NAME\n\nFROM update_strategy_instances usi\n\nJOIN M2R_REP_1053_P01.OPB_WIDGET_FIELD wf\n  ON wf.WIDGET_ID = usi.WIDGET_ID\n AND wf.VERSION_NUMBER = usi.VERSION_NUMBER\n\nLEFT JOIN update_strategy_properties usp\n  ON usp.SUBJECT_ID = usi.SUBJECT_ID\n AND usp.MAPPING_ID = usi.MAPPING_ID\n AND usp.INSTANCE_ID = usi.INSTANCE_ID\n AND usp.WIDGET_ID = usi.WIDGET_ID\n AND usp.VERSION_NUMBER = usi.VERSION_NUMBER\n\nLEFT JOIN update_strategy_metadata_extensions usme\n  ON usme.SUBJECT_ID = usi.SUBJECT_ID\n AND usme.WIDGET_ID = usi.WIDGET_ID\n AND usme.VERSION_NUMBER = usi.VERSION_NUMBER\n\nLEFT JOIN port_connections pc\n  ON pc.SUBJECT_ID = usi.SUBJECT_ID\n AND pc.MAPPING_ID = usi.MAPPING_ID\n AND pc.MAPPING_VERSION_NUMBER = usi.VERSION_NUMBER\n AND pc.INSTANCE_ID = usi.INSTANCE_ID\n AND pc.FIELD_NAME = wf.FIELD_NAME\n\nORDER BY\n       usi.SUBJECT_AREA,\n       usi.WORKFLOW_NAME,\n       usi.SESSION_INSTANCE_NAME,\n       usi.SESSION_NAME,\n       usi.MAPPING_NAME,\n       usi.TRANSFORMATION_NAME,\n       wf.FIELD_ORDER,\n       wf.FIELD_NAME,\n       usme.EXTENSION_NAME,\n       usme.EXTENSION_LINE_NO;"}, 'CUSTOMTRANSFORMATION': {'label': 'Custom Transformation', 'sql': "WITH workflow_mappings AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           s.SUBJECT_AREA,\n           s.SUBJECT_ID,\n           s.MAPPING_ID,\n           w.WORKFLOW_NAME,\n           ti.INSTANCE_NAME AS SESSION_INSTANCE_NAME,\n           s.SESSION_NAME\n    FROM M2R_REP_1053_P01.REP_WORKFLOWS w\n    JOIN M2R_REP_1053_P01.REP_TASK_INST ti\n      ON ti.WORKFLOW_ID = w.WORKFLOW_ID\n     AND ti.TASK_TYPE = 68\n    JOIN M2R_REP_1053_P01.REP_LOAD_SESSIONS s\n      ON s.SESSION_ID = ti.TASK_ID\n    WHERE w.SUBJECT_AREA = 'M2R_DTM'\n      AND w.WORKFLOW_NAME = 'WF_DTM_MMTR'\n),\ncustom_instances AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           wm.SUBJECT_AREA,\n           wm.SUBJECT_ID,\n           wm.WORKFLOW_NAME,\n           wm.SESSION_INSTANCE_NAME,\n           wm.SESSION_NAME,\n           wm.MAPPING_ID,\n           m.MAPPING_NAME,\n           wi.INSTANCE_ID,\n           wi.INSTANCE_NAME AS TRANSFORMATION_NAME,\n           wi.WIDGET_ID,\n           wi.WIDGET_TYPE,\n           wi.WIDGET_TYPE_NAME AS TRANSFORMATION_TYPE,\n           wi.VERSION_NUMBER\n    FROM workflow_mappings wm\n    JOIN M2R_REP_1053_P01.REP_ALL_MAPPINGS m\n      ON m.MAPPING_ID = wm.MAPPING_ID\n     AND m.SUBJECT_AREA = wm.SUBJECT_AREA\n    JOIN M2R_REP_1053_P01.REP_WIDGET_INST wi\n      ON wi.MAPPING_ID = wm.MAPPING_ID\n     AND wi.SUBJECT_ID = wm.SUBJECT_ID\n     AND\n         (\n             UPPER(TRIM(wi.WIDGET_TYPE_NAME)) LIKE '%CUSTOM%'\n             OR UPPER(TRIM(wi.WIDGET_TYPE_NAME)) LIKE '%UNION%'\n         )\n),\nrelevant_transformations AS\n(\n    SELECT /*+ MATERIALIZE */\n           DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           WIDGET_TYPE,\n           VERSION_NUMBER\n    FROM custom_instances\n),\ncustom_attribute_rows AS\n(\n    SELECT rt.SUBJECT_ID,\n           rt.MAPPING_ID,\n           rt.INSTANCE_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           wa.ATTR_ID,\n           UPPER(TRIM(wa.ATTR_NAME)) AS ATTR_NAME,\n           TRIM(wa.ATTR_VALUE) AS ATTR_VALUE\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_WIDGET_ATTR wa\n      ON wa.WIDGET_ID = rt.WIDGET_ID\n     AND wa.VERSION_NUMBER = rt.VERSION_NUMBER\n     AND\n         (\n             wa.WIDGET_TYPE = rt.WIDGET_TYPE\n             OR wa.WIDGET_TYPE IS NULL\n         )\n     AND\n         (\n             wa.INSTANCE_ID = rt.INSTANCE_ID\n             OR wa.INSTANCE_ID IS NULL\n             OR wa.INSTANCE_ID = 0\n         )\n     AND\n         (\n             wa.MAPPING_ID = rt.MAPPING_ID\n             OR wa.MAPPING_ID IS NULL\n             OR wa.MAPPING_ID = 0\n         )\n),\ncustom_properties AS\n(\n    SELECT SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'LANGUAGE'\n                   THEN ATTR_VALUE\n               END\n           ) AS LANGUAGE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'MODULE IDENTIFIER',\n                            'MODULE ID'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS MODULE_IDENTIFIER,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'FUNCTION IDENTIFIER',\n                            'FUNCTION ID'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS FUNCTION_IDENTIFIER,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'RUNTIME LOCATION'\n                   THEN ATTR_VALUE\n               END\n           ) AS RUNTIME_LOCATION,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'TRACING LEVEL'\n                   THEN ATTR_VALUE\n               END\n           ) AS TRACING_LEVEL_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'IS PARTITIONABLE',\n                            'PARTITIONABLE'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS IS_PARTITIONABLE_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'INPUTS MUST BLOCK',\n                            'INPUT MUST BLOCK'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS INPUTS_MUST_BLOCK_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'IS ACTIVE',\n                            'ACTIVE'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS IS_ACTIVE_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'UPDATE STRATEGY TRANSFORMATION',\n                            'IS UPDATE STRATEGY TRANSFORMATION'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS UPDATE_STRATEGY_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME = 'TRANSFORMATION SCOPE'\n                   THEN ATTR_VALUE\n               END\n           ) AS TRANSFORMATION_SCOPE_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'GENERATE TRANSACTION',\n                            'GENERATES TRANSACTION'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS GENERATE_TRANSACTION_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'OUTPUT IS REPEATABLE',\n                            'OUTPUT IS REPEATABLE.'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS OUTPUT_REPEATABLE_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'REQUIRES SINGLE THREAD PER PARTITION',\n                            'REQUIRE SINGLE THREAD PER PARTITION'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS SINGLE_THREAD_CODE,\n\n           MAX(\n               CASE\n                   WHEN ATTR_NAME IN\n                        (\n                            'OUTPUT IS DETERMINISTIC',\n                            'OUTPUT IS DETERMINISTIC.'\n                        )\n                   THEN ATTR_VALUE\n               END\n           ) AS OUTPUT_DETERMINISTIC_CODE\n\n    FROM custom_attribute_rows\n    GROUP BY\n           SUBJECT_ID,\n           MAPPING_ID,\n           INSTANCE_ID,\n           WIDGET_ID,\n           VERSION_NUMBER\n),\ncustom_metadata_extensions AS\n(\n    SELECT DISTINCT\n           rt.SUBJECT_ID,\n           rt.WIDGET_ID,\n           rt.VERSION_NUMBER,\n           mdx.METADATA_EXTN_NAME AS EXTENSION_NAME,\n           mdx.METADATA_EXTN_DATA_TYPE AS EXTENSION_DATATYPE_CODE,\n           mdx.METADATA_EXTN_VALUE AS EXTENSION_VALUE,\n           mdx.PERMISSIONS AS EXTENSION_PERMISSIONS,\n           mdx.LINE_NO AS EXTENSION_LINE_NO,\n           mdx.DOMAIN_NAME AS EXTENSION_DOMAIN_NAME,\n           mdx.DOMAIN_USAGE AS EXTENSION_DOMAIN_USAGE,\n           mdx.METADATA_EXTN_DESCRIPTION AS EXTENSION_DESCRIPTION,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NOT NULL\n               THEN LENGTH(mdx.METADATA_EXTN_VALUE)\n           END AS EXTENSION_PREC,\n\n           CASE\n               WHEN mdx.METADATA_EXTN_NAME IS NULL\n               THEN NULL\n               WHEN mdx.DOMAIN_ID IS NOT NULL\n                 OR mdx.DOMAIN_NAME IS NOT NULL\n               THEN 'YES'\n               ELSE 'NO'\n           END AS EXTENSION_REUSABLE\n\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_METADATA_EXTNS mdx\n      ON mdx.SUBJECT_ID = rt.SUBJECT_ID\n     AND mdx.METADATA_EXTN_OBJECT_ID = rt.WIDGET_ID\n     AND mdx.VERSION_NUMBER = rt.VERSION_NUMBER\n),\nincoming_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.TO_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.TO_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.FROM_OBJECT_NAME,\n           pc.FROM_OBJECT_FIELD_NAME,\n           pc.FROM_OBJECT_NAME\n               || '.'\n               || pc.FROM_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.TO_OBJECT_INSTANCE_ID\n    WHERE pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_NAME IS NOT NULL\n      AND pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n),\noutgoing_connections AS\n(\n    SELECT pc.SUBJECT_ID,\n           pc.MAPPING_ID,\n           pc.MAPPING_VERSION_NUMBER,\n           pc.FROM_OBJECT_INSTANCE_ID AS INSTANCE_ID,\n           pc.FROM_OBJECT_FIELD_NAME AS FIELD_NAME,\n           pc.TO_OBJECT_NAME,\n           pc.TO_OBJECT_FIELD_NAME,\n           pc.TO_OBJECT_NAME\n               || '.'\n               || pc.TO_OBJECT_FIELD_NAME AS CONNECTED_PORT\n    FROM M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n    JOIN relevant_transformations rt\n      ON rt.SUBJECT_ID = pc.SUBJECT_ID\n     AND rt.MAPPING_ID = pc.MAPPING_ID\n     AND rt.VERSION_NUMBER = pc.MAPPING_VERSION_NUMBER\n     AND rt.INSTANCE_ID = pc.FROM_OBJECT_INSTANCE_ID\n    WHERE pc.FROM_OBJECT_FIELD_NAME IS NOT NULL\n      AND pc.TO_OBJECT_NAME IS NOT NULL\n      AND pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n),\nincoming_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           FROM_OBJECT_NAME,\n           FROM_OBJECT_FIELD_NAME,\n           CONNECTED_PORT\n    FROM incoming_connections\n),\noutgoing_connections_distinct AS\n(\n    SELECT DISTINCT\n           SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FIELD_NAME,\n           TO_OBJECT_NAME,\n           TO_OBJECT_FIELD_NAME,\n           CONNECTED_PORT\n    FROM outgoing_connections\n),\ncustom_input_groups AS\n(\n    SELECT SUBJECT_ID,\n           MAPPING_ID,\n           MAPPING_VERSION_NUMBER,\n           INSTANCE_ID,\n           FROM_OBJECT_NAME AS INPUT_GROUP_NAME,\n           DENSE_RANK() OVER\n           (\n               PARTITION BY\n                   SUBJECT_ID,\n                   MAPPING_ID,\n                   MAPPING_VERSION_NUMBER,\n                   INSTANCE_ID\n               ORDER BY FROM_OBJECT_NAME\n           ) AS INPUT_GROUP_ORDER\n    FROM\n    (\n        SELECT DISTINCT\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FROM_OBJECT_NAME\n        FROM incoming_connections_distinct\n        WHERE FROM_OBJECT_NAME IS NOT NULL\n    )\n),\ncustom_group_ports AS\n(\n    SELECT icd.SUBJECT_ID,\n           icd.MAPPING_ID,\n           icd.MAPPING_VERSION_NUMBER,\n           icd.INSTANCE_ID,\n           cig.INPUT_GROUP_ORDER AS GROUP_ORDER,\n           cig.INPUT_GROUP_NAME AS GROUP_NAME,\n           'INPUT' AS GROUP_TYPE,\n           icd.FIELD_NAME,\n           icd.FROM_OBJECT_FIELD_NAME AS GROUP_SOURCE_PORT\n    FROM incoming_connections_distinct icd\n    JOIN custom_input_groups cig\n      ON cig.SUBJECT_ID = icd.SUBJECT_ID\n     AND cig.MAPPING_ID = icd.MAPPING_ID\n     AND cig.MAPPING_VERSION_NUMBER =\n         icd.MAPPING_VERSION_NUMBER\n     AND cig.INSTANCE_ID = icd.INSTANCE_ID\n     AND cig.INPUT_GROUP_NAME = icd.FROM_OBJECT_NAME\n\n    UNION ALL\n\n    SELECT rt.SUBJECT_ID,\n           rt.MAPPING_ID,\n           rt.VERSION_NUMBER AS MAPPING_VERSION_NUMBER,\n           rt.INSTANCE_ID,\n           0 AS GROUP_ORDER,\n           'OUTPUT' AS GROUP_NAME,\n           'OUTPUT' AS GROUP_TYPE,\n           wf.FIELD_NAME,\n           CAST(NULL AS VARCHAR2(4000)) AS GROUP_SOURCE_PORT\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.OPB_WIDGET_FIELD wf\n      ON wf.WIDGET_ID = rt.WIDGET_ID\n     AND wf.VERSION_NUMBER = rt.VERSION_NUMBER\n    WHERE BITAND(wf.PORTTYPE, 2) = 2\n),\nport_connections AS\n(\n    SELECT k.SUBJECT_ID,\n           k.MAPPING_ID,\n           k.MAPPING_VERSION_NUMBER,\n           k.INSTANCE_ID,\n           k.FIELD_NAME,\n           incoming.PREVIOUS_TRANSFORMATION,\n           outgoing.NEXT_TRANSFORMATION_NAME\n    FROM\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM incoming_connections_distinct\n\n        UNION\n\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n        FROM outgoing_connections_distinct\n    ) k\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS PREVIOUS_TRANSFORMATION\n        FROM incoming_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) incoming\n      ON incoming.SUBJECT_ID = k.SUBJECT_ID\n     AND incoming.MAPPING_ID = k.MAPPING_ID\n     AND incoming.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND incoming.INSTANCE_ID = k.INSTANCE_ID\n     AND incoming.FIELD_NAME = k.FIELD_NAME\n    LEFT JOIN\n    (\n        SELECT SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME,\n               LISTAGG(CONNECTED_PORT, ', ')\n                   WITHIN GROUP (ORDER BY CONNECTED_PORT)\n                   AS NEXT_TRANSFORMATION_NAME\n        FROM outgoing_connections_distinct\n        GROUP BY\n               SUBJECT_ID,\n               MAPPING_ID,\n               MAPPING_VERSION_NUMBER,\n               INSTANCE_ID,\n               FIELD_NAME\n    ) outgoing\n      ON outgoing.SUBJECT_ID = k.SUBJECT_ID\n     AND outgoing.MAPPING_ID = k.MAPPING_ID\n     AND outgoing.MAPPING_VERSION_NUMBER =\n         k.MAPPING_VERSION_NUMBER\n     AND outgoing.INSTANCE_ID = k.INSTANCE_ID\n     AND outgoing.FIELD_NAME = k.FIELD_NAME\n)\nSELECT DISTINCT\n       ci.SUBJECT_AREA,\n       ci.WORKFLOW_NAME,\n       ci.SESSION_INSTANCE_NAME,\n       ci.SESSION_NAME,\n       ci.MAPPING_NAME,\n\n       /* Transformation tab */\n       ci.TRANSFORMATION_NAME,\n       ci.TRANSFORMATION_TYPE,\n\n       /* Ports and Group Ports tabs */\n       cgp.GROUP_ORDER,\n       cgp.GROUP_NAME,\n       cgp.GROUP_TYPE,\n\n       wf.FIELD_ORDER AS PORT_ORDER,\n       wf.FIELD_NAME AS PORT_NAME,\n\n       CASE wf.WGT_DATATYPE\n           WHEN -5 THEN 'string'\n           WHEN -4 THEN 'text'\n           WHEN -3 THEN 'binary'\n           WHEN -2 THEN 'varbinary'\n           WHEN -1 THEN 'long varbinary'\n           WHEN 0  THEN 'unknown'\n           WHEN 1  THEN 'small integer'\n           WHEN 2  THEN 'integer'\n           WHEN 3  THEN 'decimal'\n           WHEN 4  THEN 'real'\n           WHEN 5  THEN 'double'\n           WHEN 6  THEN 'date/time'\n           WHEN 7  THEN 'date/time'\n           WHEN 8  THEN 'date/time'\n           WHEN 9  THEN 'date/time'\n           WHEN 10 THEN 'string'\n           WHEN 11 THEN 'string'\n           WHEN 12 THEN 'string'\n           WHEN 13 THEN 'binary'\n           WHEN 14 THEN 'bigint'\n           WHEN 15 THEN 'double'\n           WHEN 16 THEN 'decimal'\n           WHEN 17 THEN 'boolean'\n           ELSE\n               'Unknown ('\n               || TO_CHAR(wf.WGT_DATATYPE)\n               || ')'\n       END AS DATATYPE,\n\n       wf.WGT_DATATYPE AS DATATYPE_CODE,\n       wf.WGT_PREC AS PREC,\n       wf.WGT_SCALE AS SCALE,\n\n       CASE\n           WHEN cgp.GROUP_TYPE = 'INPUT'\n           THEN 'YES'\n           WHEN BITAND(wf.PORTTYPE, 1) = 1\n           THEN 'YES'\n           ELSE 'NO'\n       END AS I,\n\n       CASE\n           WHEN cgp.GROUP_TYPE = 'OUTPUT'\n           THEN 'YES'\n           WHEN BITAND(wf.PORTTYPE, 2) = 2\n           THEN 'YES'\n           ELSE 'NO'\n       END AS O,\n\n       CASE\n           WHEN BITAND(wf.PORTTYPE, 32) = 32\n           THEN 'YES'\n           ELSE 'NO'\n       END AS V,\n\n       wf.PORTTYPE AS PORTTYPE_CODE,\n       cgp.GROUP_SOURCE_PORT,\n\n       /* Properties tab */\n       cp.LANGUAGE,\n       cp.MODULE_IDENTIFIER,\n       cp.FUNCTION_IDENTIFIER,\n       cp.RUNTIME_LOCATION,\n\n       CASE\n           WHEN cp.TRACING_LEVEL_CODE IS NULL\n           THEN 'Normal'\n           WHEN UPPER(TRIM(cp.TRACING_LEVEL_CODE)) = '1'\n           THEN 'Terse'\n           WHEN UPPER(TRIM(cp.TRACING_LEVEL_CODE)) = '2'\n           THEN 'Normal'\n           WHEN UPPER(TRIM(cp.TRACING_LEVEL_CODE)) = '3'\n           THEN 'Verbose Initialization'\n           WHEN UPPER(TRIM(cp.TRACING_LEVEL_CODE)) = '4'\n           THEN 'Verbose Data'\n           WHEN UPPER(TRIM(cp.TRACING_LEVEL_CODE)) = 'TERSE'\n           THEN 'Terse'\n           WHEN UPPER(TRIM(cp.TRACING_LEVEL_CODE)) = 'NORMAL'\n           THEN 'Normal'\n           WHEN UPPER(TRIM(cp.TRACING_LEVEL_CODE)) =\n                'VERBOSE INITIALIZATION'\n           THEN 'Verbose Initialization'\n           WHEN UPPER(TRIM(cp.TRACING_LEVEL_CODE)) =\n                'VERBOSE DATA'\n           THEN 'Verbose Data'\n           ELSE\n               'Unknown ('\n               || cp.TRACING_LEVEL_CODE\n               || ')'\n       END AS TRACING_LEVEL,\n\n       CASE\n           WHEN UPPER(TRIM(cp.IS_PARTITIONABLE_CODE)) IN\n                ('1', 'YES', 'Y', 'TRUE', 'CHECKED')\n           THEN 'YES'\n           WHEN UPPER(TRIM(cp.IS_PARTITIONABLE_CODE)) IN\n                ('0', 'NO', 'N', 'FALSE', 'UNCHECKED')\n           THEN 'NO'\n           ELSE cp.IS_PARTITIONABLE_CODE\n       END AS IS_PARTITIONABLE,\n\n       CASE\n           WHEN UPPER(TRIM(cp.INPUTS_MUST_BLOCK_CODE)) IN\n                ('1', 'YES', 'Y', 'TRUE', 'CHECKED')\n           THEN 'YES'\n           WHEN UPPER(TRIM(cp.INPUTS_MUST_BLOCK_CODE)) IN\n                ('0', 'NO', 'N', 'FALSE', 'UNCHECKED')\n           THEN 'NO'\n           ELSE NVL(cp.INPUTS_MUST_BLOCK_CODE, 'NO')\n       END AS INPUTS_MUST_BLOCK,\n\n       CASE\n           WHEN UPPER(TRIM(cp.IS_ACTIVE_CODE)) IN\n                ('1', 'YES', 'Y', 'TRUE', 'CHECKED')\n           THEN 'YES'\n           WHEN UPPER(TRIM(cp.IS_ACTIVE_CODE)) IN\n                ('0', 'NO', 'N', 'FALSE', 'UNCHECKED')\n           THEN 'NO'\n           ELSE cp.IS_ACTIVE_CODE\n       END AS IS_ACTIVE,\n\n       CASE\n           WHEN UPPER(TRIM(cp.UPDATE_STRATEGY_CODE)) IN\n                ('1', 'YES', 'Y', 'TRUE', 'CHECKED')\n           THEN 'YES'\n           WHEN UPPER(TRIM(cp.UPDATE_STRATEGY_CODE)) IN\n                ('0', 'NO', 'N', 'FALSE', 'UNCHECKED')\n           THEN 'NO'\n           ELSE NVL(cp.UPDATE_STRATEGY_CODE, 'NO')\n       END AS UPDATE_STRATEGY_TRANSFORMATION,\n\n       CASE\n           WHEN cp.TRANSFORMATION_SCOPE_CODE IS NULL\n           THEN 'Row'\n           WHEN UPPER(TRIM(cp.TRANSFORMATION_SCOPE_CODE)) = '0'\n           THEN 'All Input'\n           WHEN UPPER(TRIM(cp.TRANSFORMATION_SCOPE_CODE)) = '1'\n           THEN 'Transaction'\n           WHEN UPPER(TRIM(cp.TRANSFORMATION_SCOPE_CODE)) = '2'\n           THEN 'Row'\n           WHEN UPPER(TRIM(cp.TRANSFORMATION_SCOPE_CODE)) =\n                'ALL INPUT'\n           THEN 'All Input'\n           WHEN UPPER(TRIM(cp.TRANSFORMATION_SCOPE_CODE)) =\n                'TRANSACTION'\n           THEN 'Transaction'\n           WHEN UPPER(TRIM(cp.TRANSFORMATION_SCOPE_CODE)) = 'ROW'\n           THEN 'Row'\n           ELSE cp.TRANSFORMATION_SCOPE_CODE\n       END AS TRANSFORMATION_SCOPE,\n\n       CASE\n           WHEN UPPER(TRIM(cp.GENERATE_TRANSACTION_CODE)) IN\n                ('1', 'YES', 'Y', 'TRUE', 'CHECKED')\n           THEN 'YES'\n           WHEN UPPER(TRIM(cp.GENERATE_TRANSACTION_CODE)) IN\n                ('0', 'NO', 'N', 'FALSE', 'UNCHECKED')\n           THEN 'NO'\n           ELSE NVL(cp.GENERATE_TRANSACTION_CODE, 'NO')\n       END AS GENERATE_TRANSACTION,\n\n       CASE\n           WHEN cp.OUTPUT_REPEATABLE_CODE IS NULL\n           THEN 'Never'\n           WHEN UPPER(TRIM(cp.OUTPUT_REPEATABLE_CODE)) = '0'\n           THEN 'Never'\n           WHEN UPPER(TRIM(cp.OUTPUT_REPEATABLE_CODE)) = '1'\n           THEN 'Always'\n           WHEN UPPER(TRIM(cp.OUTPUT_REPEATABLE_CODE)) = '2'\n           THEN 'Within Transaction'\n           WHEN UPPER(TRIM(cp.OUTPUT_REPEATABLE_CODE)) = 'NEVER'\n           THEN 'Never'\n           WHEN UPPER(TRIM(cp.OUTPUT_REPEATABLE_CODE)) = 'ALWAYS'\n           THEN 'Always'\n           WHEN UPPER(TRIM(cp.OUTPUT_REPEATABLE_CODE)) =\n                'WITHIN TRANSACTION'\n           THEN 'Within Transaction'\n           ELSE cp.OUTPUT_REPEATABLE_CODE\n       END AS OUTPUT_IS_REPEATABLE,\n\n       CASE\n           WHEN UPPER(TRIM(cp.SINGLE_THREAD_CODE)) IN\n                ('1', 'YES', 'Y', 'TRUE', 'CHECKED')\n           THEN 'YES'\n           WHEN UPPER(TRIM(cp.SINGLE_THREAD_CODE)) IN\n                ('0', 'NO', 'N', 'FALSE', 'UNCHECKED')\n           THEN 'NO'\n           ELSE NVL(cp.SINGLE_THREAD_CODE, 'NO')\n       END AS REQUIRES_SINGLE_THREAD_PER_PARTITION,\n\n       CASE\n           WHEN UPPER(TRIM(cp.OUTPUT_DETERMINISTIC_CODE)) IN\n                ('1', 'YES', 'Y', 'TRUE', 'CHECKED')\n           THEN 'YES'\n           WHEN UPPER(TRIM(cp.OUTPUT_DETERMINISTIC_CODE)) IN\n                ('0', 'NO', 'N', 'FALSE', 'UNCHECKED')\n           THEN 'NO'\n           ELSE cp.OUTPUT_DETERMINISTIC_CODE\n       END AS OUTPUT_IS_DETERMINISTIC,\n\n       /* Metadata Extensions tab */\n       cme.EXTENSION_NAME,\n       cme.EXTENSION_DATATYPE_CODE,\n\n       CASE cme.EXTENSION_DATATYPE_CODE\n           WHEN 1 THEN 'String'\n           WHEN 2 THEN 'Number'\n           WHEN 3 THEN 'Boolean'\n           ELSE\n               CASE\n                   WHEN cme.EXTENSION_DATATYPE_CODE IS NULL\n                   THEN NULL\n                   ELSE\n                       'Other ('\n                       || TO_CHAR(cme.EXTENSION_DATATYPE_CODE)\n                       || ')'\n               END\n       END AS EXTENSION_DATATYPE,\n\n       cme.EXTENSION_PREC,\n       cme.EXTENSION_VALUE,\n       cme.EXTENSION_REUSABLE AS REUSABLE,\n       cme.EXTENSION_PERMISSIONS,\n       cme.EXTENSION_LINE_NO,\n       cme.EXTENSION_DOMAIN_NAME,\n       cme.EXTENSION_DOMAIN_USAGE,\n       cme.EXTENSION_DESCRIPTION,\n\n       /* Connected transformation ports */\n       pc.PREVIOUS_TRANSFORMATION,\n       pc.NEXT_TRANSFORMATION_NAME\n\nFROM custom_instances ci\n\nJOIN M2R_REP_1053_P01.OPB_WIDGET_FIELD wf\n  ON wf.WIDGET_ID = ci.WIDGET_ID\n AND wf.VERSION_NUMBER = ci.VERSION_NUMBER\n\nLEFT JOIN custom_group_ports cgp\n  ON cgp.SUBJECT_ID = ci.SUBJECT_ID\n AND cgp.MAPPING_ID = ci.MAPPING_ID\n AND cgp.MAPPING_VERSION_NUMBER = ci.VERSION_NUMBER\n AND cgp.INSTANCE_ID = ci.INSTANCE_ID\n AND cgp.FIELD_NAME = wf.FIELD_NAME\n AND\n     (\n         (cgp.GROUP_TYPE = 'INPUT'\n          AND BITAND(wf.PORTTYPE, 1) = 1)\n         OR\n         (cgp.GROUP_TYPE = 'OUTPUT'\n          AND BITAND(wf.PORTTYPE, 2) = 2)\n     )\n\nLEFT JOIN custom_properties cp\n  ON cp.SUBJECT_ID = ci.SUBJECT_ID\n AND cp.MAPPING_ID = ci.MAPPING_ID\n AND cp.INSTANCE_ID = ci.INSTANCE_ID\n AND cp.WIDGET_ID = ci.WIDGET_ID\n AND cp.VERSION_NUMBER = ci.VERSION_NUMBER\n\nLEFT JOIN custom_metadata_extensions cme\n  ON cme.SUBJECT_ID = ci.SUBJECT_ID\n AND cme.WIDGET_ID = ci.WIDGET_ID\n AND cme.VERSION_NUMBER = ci.VERSION_NUMBER\n\nLEFT JOIN port_connections pc\n  ON pc.SUBJECT_ID = ci.SUBJECT_ID\n AND pc.MAPPING_ID = ci.MAPPING_ID\n AND pc.MAPPING_VERSION_NUMBER = ci.VERSION_NUMBER\n AND pc.INSTANCE_ID = ci.INSTANCE_ID\n AND pc.FIELD_NAME = wf.FIELD_NAME\n\nORDER BY\n       ci.SUBJECT_AREA,\n       ci.WORKFLOW_NAME,\n       ci.SESSION_INSTANCE_NAME,\n       ci.SESSION_NAME,\n       ci.MAPPING_NAME,\n       ci.TRANSFORMATION_NAME,\n       cgp.GROUP_ORDER,\n       cgp.GROUP_NAME,\n       wf.FIELD_ORDER,\n       wf.FIELD_NAME,\n       cme.EXTENSION_NAME,\n       cme.EXTENSION_LINE_NO;"}}

# Updated Target Definition query.
EMBEDDED_QUERIES["TARGETDEFINITION"]["sql"] = "WITH workflow_mappings AS\n(\n    SELECT /*+ MATERIALIZE */ DISTINCT\n           s.SUBJECT_AREA, s.SUBJECT_ID, s.MAPPING_ID,\n           w.WORKFLOW_NAME,\n           ti.INSTANCE_NAME AS SESSION_INSTANCE_NAME,\n           s.SESSION_NAME\n    FROM M2R_REP_1053_P01.REP_WORKFLOWS w\n    JOIN M2R_REP_1053_P01.REP_TASK_INST ti\n      ON ti.WORKFLOW_ID = w.WORKFLOW_ID AND ti.TASK_TYPE = 68\n    JOIN M2R_REP_1053_P01.REP_LOAD_SESSIONS s\n      ON s.SESSION_ID = ti.TASK_ID\n    WHERE w.SUBJECT_AREA = :subject_area\n      AND w.WORKFLOW_NAME = :workflow_name\n),\ntarget_definition_instances AS\n(\n    SELECT /*+ MATERIALIZE */ DISTINCT\n           wm.SUBJECT_AREA, wm.SUBJECT_ID, wm.WORKFLOW_NAME,\n           wm.SESSION_INSTANCE_NAME, wm.SESSION_NAME, wm.MAPPING_ID,\n           m.MAPPING_NAME, wi.INSTANCE_ID,\n           wi.INSTANCE_NAME AS TRANSFORMATION_NAME,\n           wi.WIDGET_ID, wi.WIDGET_TYPE,\n           wi.WIDGET_TYPE_NAME AS TRANSFORMATION_TYPE,\n           wi.VERSION_NUMBER\n    FROM workflow_mappings wm\n    JOIN M2R_REP_1053_P01.REP_ALL_MAPPINGS m\n      ON m.MAPPING_ID = wm.MAPPING_ID AND m.SUBJECT_AREA = wm.SUBJECT_AREA\n    JOIN M2R_REP_1053_P01.REP_WIDGET_INST wi\n      ON wi.MAPPING_ID = wm.MAPPING_ID AND wi.SUBJECT_ID = wm.SUBJECT_ID\n    WHERE UPPER(TRIM(wi.WIDGET_TYPE_NAME)) = 'TARGET DEFINITION'\n       OR REPLACE(REPLACE(UPPER(TRIM(wi.WIDGET_TYPE_NAME)), ' ', ''), '_', '') = 'TARGETDEFINITION'\n),\nrelevant_transformations AS\n(\n    SELECT /*+ MATERIALIZE */ DISTINCT\n           SUBJECT_ID, MAPPING_ID, INSTANCE_ID, WIDGET_ID,\n           WIDGET_TYPE, VERSION_NUMBER\n    FROM target_definition_instances\n),\ntarget_definition_attribute_rows AS\n(\n    SELECT rt.SUBJECT_ID, rt.MAPPING_ID, rt.INSTANCE_ID, rt.WIDGET_ID,\n           rt.VERSION_NUMBER, wa.ATTR_ID,\n           UPPER(TRIM(wa.ATTR_NAME)) AS ATTR_NAME,\n           TRIM(wa.ATTR_VALUE) AS ATTR_VALUE\n    FROM relevant_transformations rt\n    LEFT JOIN M2R_REP_1053_P01.REP_WIDGET_ATTR wa\n      ON wa.WIDGET_ID = rt.WIDGET_ID\n     AND wa.VERSION_NUMBER = rt.VERSION_NUMBER\n     AND (wa.WIDGET_TYPE = rt.WIDGET_TYPE OR wa.WIDGET_TYPE IS NULL)\n     AND (wa.INSTANCE_ID = rt.INSTANCE_ID OR wa.INSTANCE_ID IS NULL OR wa.INSTANCE_ID = 0)\n     AND (wa.MAPPING_ID = rt.MAPPING_ID OR wa.MAPPING_ID IS NULL OR wa.MAPPING_ID = 0)\n),\ntarget_definition_properties AS\n(\n    SELECT SUBJECT_ID, MAPPING_ID, INSTANCE_ID, WIDGET_ID, VERSION_NUMBER,\n           MAX(CASE WHEN ATTR_NAME IN\n               ('REJECT TRUNCATED/OVERFLOWED ROWS','REJECT TRUNCATED OR OVERFLOWED ROWS',\n                'REJECT TRUNCATED/OVERFLOW ROWS','REJECT OVERFLOWED ROWS')\n               THEN ATTR_VALUE END) AS REJECT_TRUNCATED_ROWS_CODE,\n           MAX(CASE WHEN ATTR_NAME IN ('UPDATE OVERRIDE','UPDATE OVERRIDE SQL')\n               THEN ATTR_VALUE END) AS UPDATE_OVERRIDE,\n           MAX(CASE WHEN ATTR_NAME IN ('TABLE NAME PREFIX','TARGET TABLE NAME PREFIX')\n               THEN ATTR_VALUE END) AS TABLE_NAME_PREFIX,\n           MAX(CASE WHEN ATTR_NAME IN ('PRE SQL','PRE-SQL')\n               THEN ATTR_VALUE END) AS PRE_SQL,\n           MAX(CASE WHEN ATTR_NAME IN ('POST SQL','POST-SQL')\n               THEN ATTR_VALUE END) AS POST_SQL,\n           MAX(CASE WHEN ATTR_NAME IN ('TARGET TABLE NAME','TABLE NAME','TARGET NAME')\n               THEN ATTR_VALUE END) AS TARGET_TABLE_NAME\n    FROM target_definition_attribute_rows\n    GROUP BY SUBJECT_ID, MAPPING_ID, INSTANCE_ID, WIDGET_ID, VERSION_NUMBER\n),\nincoming_target_connections AS\n(\n    SELECT DISTINCT rt.SUBJECT_ID, rt.MAPPING_ID,\n           rt.INSTANCE_ID AS TARGET_INSTANCE_ID,\n           rt.WIDGET_ID AS TARGET_WIDGET_ID,\n           rt.VERSION_NUMBER AS TARGET_VERSION_NUMBER,\n           pc.TO_OBJECT_FIELD_NAME AS PORT_NAME,\n           pc.FROM_OBJECT_INSTANCE_ID, pc.FROM_OBJECT_NAME,\n           pc.FROM_OBJECT_FIELD_NAME,\n           pc.FROM_OBJECT_NAME || '.' || pc.FROM_OBJECT_FIELD_NAME AS PREVIOUS_TRANSFORMATION\n    FROM relevant_transformations rt\n    JOIN M2R_REP_1053_P01.REP_MAPPING_CONN_PORTS pc\n      ON pc.SUBJECT_ID = rt.SUBJECT_ID\n     AND pc.MAPPING_ID = rt.MAPPING_ID\n     AND pc.TO_OBJECT_INSTANCE_ID = rt.INSTANCE_ID\n    WHERE pc.TO_OBJECT_FIELD_NAME IS NOT NULL\n),\nupstream_widget_instances AS\n(\n    SELECT DISTINCT itc.SUBJECT_ID, itc.MAPPING_ID,\n           itc.TARGET_INSTANCE_ID, itc.TARGET_WIDGET_ID,\n           itc.TARGET_VERSION_NUMBER, itc.PORT_NAME,\n           itc.FROM_OBJECT_INSTANCE_ID, itc.FROM_OBJECT_NAME,\n           itc.FROM_OBJECT_FIELD_NAME, itc.PREVIOUS_TRANSFORMATION,\n           uwi.WIDGET_ID AS UPSTREAM_WIDGET_ID,\n           uwi.VERSION_NUMBER AS UPSTREAM_INSTANCE_VERSION\n    FROM incoming_target_connections itc\n    LEFT JOIN M2R_REP_1053_P01.REP_WIDGET_INST uwi\n      ON uwi.SUBJECT_ID = itc.SUBJECT_ID\n     AND uwi.MAPPING_ID = itc.MAPPING_ID\n     AND uwi.INSTANCE_ID = itc.FROM_OBJECT_INSTANCE_ID\n),\nupstream_port_versions AS\n(\n    SELECT uwi.SUBJECT_ID, uwi.MAPPING_ID, uwi.TARGET_INSTANCE_ID,\n           uwi.TARGET_WIDGET_ID, uwi.TARGET_VERSION_NUMBER, uwi.PORT_NAME,\n           uwi.FROM_OBJECT_INSTANCE_ID, uwi.FROM_OBJECT_NAME,\n           uwi.FROM_OBJECT_FIELD_NAME, uwi.PREVIOUS_TRANSFORMATION,\n           uwi.UPSTREAM_WIDGET_ID, uwi.UPSTREAM_INSTANCE_VERSION,\n           NVL(MAX(CASE WHEN wf.VERSION_NUMBER = uwi.UPSTREAM_INSTANCE_VERSION\n                        THEN wf.VERSION_NUMBER END),\n               MAX(wf.VERSION_NUMBER)) AS UPSTREAM_PORT_VERSION\n    FROM upstream_widget_instances uwi\n    LEFT JOIN M2R_REP_1053_P01.OPB_WIDGET_FIELD wf\n      ON wf.WIDGET_ID = uwi.UPSTREAM_WIDGET_ID\n     AND UPPER(TRIM(wf.FIELD_NAME)) = UPPER(TRIM(uwi.FROM_OBJECT_FIELD_NAME))\n    GROUP BY uwi.SUBJECT_ID, uwi.MAPPING_ID, uwi.TARGET_INSTANCE_ID,\n             uwi.TARGET_WIDGET_ID, uwi.TARGET_VERSION_NUMBER, uwi.PORT_NAME,\n             uwi.FROM_OBJECT_INSTANCE_ID, uwi.FROM_OBJECT_NAME,\n             uwi.FROM_OBJECT_FIELD_NAME, uwi.PREVIOUS_TRANSFORMATION,\n             uwi.UPSTREAM_WIDGET_ID, uwi.UPSTREAM_INSTANCE_VERSION\n),\ntarget_ports_from_upstream AS\n(\n    SELECT DISTINCT upv.SUBJECT_ID, upv.MAPPING_ID,\n           upv.TARGET_INSTANCE_ID AS INSTANCE_ID,\n           upv.TARGET_WIDGET_ID AS WIDGET_ID,\n           upv.TARGET_VERSION_NUMBER AS VERSION_NUMBER,\n           upv.UPSTREAM_PORT_VERSION AS PORT_VERSION_NUMBER,\n           ROW_NUMBER() OVER\n           (PARTITION BY upv.SUBJECT_ID, upv.MAPPING_ID, upv.TARGET_INSTANCE_ID\n            ORDER BY upv.PORT_NAME) AS PORT_ORDER,\n           upv.PORT_NAME, wf.WGT_DATATYPE AS DATATYPE_CODE,\n           wf.WGT_PREC AS PREC, wf.WGT_SCALE AS SCALE,\n           'YES' AS I, 'NO' AS O, 1 AS PORTTYPE_CODE,\n           'UPSTREAM_WIDGET_FIELD' AS PORT_SOURCE,\n           upv.PREVIOUS_TRANSFORMATION\n    FROM upstream_port_versions upv\n    LEFT JOIN M2R_REP_1053_P01.OPB_WIDGET_FIELD wf\n      ON wf.WIDGET_ID = upv.UPSTREAM_WIDGET_ID\n     AND wf.VERSION_NUMBER = upv.UPSTREAM_PORT_VERSION\n     AND UPPER(TRIM(wf.FIELD_NAME)) = UPPER(TRIM(upv.FROM_OBJECT_FIELD_NAME))\n),\ntarget_port_summary AS\n(\n    SELECT SUBJECT_ID, MAPPING_ID, INSTANCE_ID, WIDGET_ID, VERSION_NUMBER,\n           PORT_VERSION_NUMBER, MIN(PORT_ORDER) AS PORT_ORDER, PORT_NAME,\n           MAX(DATATYPE_CODE) AS DATATYPE_CODE, MAX(PREC) AS PREC,\n           MAX(SCALE) AS SCALE, MAX(I) AS I, MAX(O) AS O,\n           MAX(PORTTYPE_CODE) AS PORTTYPE_CODE, MAX(PORT_SOURCE) AS PORT_SOURCE,\n           LISTAGG(PREVIOUS_TRANSFORMATION, ', ')\n             WITHIN GROUP (ORDER BY PREVIOUS_TRANSFORMATION) AS PREVIOUS_TRANSFORMATION\n    FROM\n    (\n        SELECT DISTINCT SUBJECT_ID, MAPPING_ID, INSTANCE_ID, WIDGET_ID,\n               VERSION_NUMBER, PORT_VERSION_NUMBER, PORT_ORDER, PORT_NAME,\n               DATATYPE_CODE, PREC, SCALE, I, O, PORTTYPE_CODE, PORT_SOURCE,\n               PREVIOUS_TRANSFORMATION\n        FROM target_ports_from_upstream\n    )\n    GROUP BY SUBJECT_ID, MAPPING_ID, INSTANCE_ID, WIDGET_ID,\n             VERSION_NUMBER, PORT_VERSION_NUMBER, PORT_NAME\n),\ntarget_definition_metadata_extensions AS\n(\n    SELECT rt.SUBJECT_ID, rt.MAPPING_ID, rt.INSTANCE_ID, rt.WIDGET_ID,\n           rt.VERSION_NUMBER, mdx.METADATA_EXTN_NAME,\n           mdx.METADATA_EXTN_DATA_TYPE, mdx.METADATA_EXTN_VALUE,\n           mdx.PERMISSIONS, mdx.LINE_NO, mdx.DOMAIN_NAME, mdx.DOMAIN_USAGE,\n           mdx.METADATA_EXTN_DESCRIPTION,\n           CASE WHEN mdx.METADATA_EXTN_NAME IS NOT NULL\n                THEN LENGTH(mdx.METADATA_EXTN_VALUE) END AS METADATA_EXTENSION_PRECISION,\n           CASE WHEN mdx.METADATA_EXTN_NAME IS NULL THEN NULL\n                WHEN mdx.DOMAIN_ID IS NOT NULL OR mdx.DOMAIN_NAME IS NOT NULL THEN 'YES'\n                ELSE 'NO' END AS REUSABLE\n    FROM relevant_transformations rt\n    LEFT JOIN M2R_REP_1053_P01.REP_METADATA_EXTNS mdx\n      ON mdx.SUBJECT_ID = rt.SUBJECT_ID\n     AND mdx.METADATA_EXTN_OBJECT_ID = rt.WIDGET_ID\n     AND mdx.VERSION_NUMBER = rt.VERSION_NUMBER\n)\nSELECT DISTINCT\n       tdi.SUBJECT_AREA, tdi.WORKFLOW_NAME, tdi.SESSION_INSTANCE_NAME,\n       tdi.SESSION_NAME, tdi.MAPPING_NAME, tdi.TRANSFORMATION_NAME,\n       tdi.TRANSFORMATION_TYPE, tdi.WIDGET_TYPE AS TRANSFORMATION_TYPE_CODE,\n       tdi.WIDGET_ID, tdi.INSTANCE_ID,\n       tdi.VERSION_NUMBER AS INSTANCE_VERSION_NUMBER,\n       p.PORT_VERSION_NUMBER, p.PORT_SOURCE, p.PORT_ORDER, p.PORT_NAME,\n       CASE p.DATATYPE_CODE\n           WHEN -5 THEN 'string' WHEN -4 THEN 'text' WHEN -3 THEN 'binary'\n           WHEN -2 THEN 'varbinary' WHEN -1 THEN 'long varbinary'\n           WHEN 0 THEN 'unknown' WHEN 1 THEN 'small integer'\n           WHEN 2 THEN 'integer' WHEN 3 THEN 'decimal' WHEN 4 THEN 'real'\n           WHEN 5 THEN 'double' WHEN 6 THEN 'date/time' WHEN 7 THEN 'date/time'\n           WHEN 8 THEN 'date/time' WHEN 9 THEN 'date/time' WHEN 10 THEN 'string'\n           WHEN 11 THEN 'string' WHEN 12 THEN 'string' WHEN 13 THEN 'binary'\n           WHEN 14 THEN 'bigint' WHEN 15 THEN 'double' WHEN 16 THEN 'decimal'\n           WHEN 17 THEN 'boolean'\n           ELSE CASE WHEN p.DATATYPE_CODE IS NULL THEN NULL\n                     ELSE 'Unknown (' || TO_CHAR(p.DATATYPE_CODE) || ')' END\n       END AS DATATYPE,\n       p.DATATYPE_CODE, p.PREC, p.SCALE, p.I, p.O, p.PORTTYPE_CODE,\n       CASE WHEN tdp.REJECT_TRUNCATED_ROWS_CODE IS NULL THEN 'NO'\n            WHEN UPPER(TRIM(tdp.REJECT_TRUNCATED_ROWS_CODE)) IN\n                 ('1','YES','Y','TRUE','CHECKED') THEN 'YES'\n            WHEN UPPER(TRIM(tdp.REJECT_TRUNCATED_ROWS_CODE)) IN\n                 ('0','NO','N','FALSE','UNCHECKED') THEN 'NO'\n            ELSE tdp.REJECT_TRUNCATED_ROWS_CODE\n       END AS REJECT_TRUNCATED_OVERFLOWED_ROWS,\n       tdp.UPDATE_OVERRIDE, tdp.TABLE_NAME_PREFIX, tdp.PRE_SQL, tdp.POST_SQL,\n       NVL(tdp.TARGET_TABLE_NAME, tdi.TRANSFORMATION_NAME) AS TARGET_TABLE_NAME,\n       tdme.METADATA_EXTN_NAME AS EXTENSION_NAME,\n       tdme.METADATA_EXTN_DATA_TYPE AS EXTENSION_DATATYPE_CODE,\n       CASE tdme.METADATA_EXTN_DATA_TYPE\n           WHEN 1 THEN 'String' WHEN 2 THEN 'Number' WHEN 3 THEN 'Boolean'\n           ELSE CASE WHEN tdme.METADATA_EXTN_DATA_TYPE IS NULL THEN NULL\n                     ELSE 'Other (' || TO_CHAR(tdme.METADATA_EXTN_DATA_TYPE) || ')' END\n       END AS EXTENSION_DATATYPE,\n       tdme.METADATA_EXTENSION_PRECISION AS EXTENSION_PREC,\n       tdme.METADATA_EXTN_VALUE AS EXTENSION_VALUE, tdme.REUSABLE,\n       tdme.PERMISSIONS AS EXTENSION_PERMISSIONS,\n       tdme.LINE_NO AS EXTENSION_LINE_NO,\n       tdme.DOMAIN_NAME AS EXTENSION_DOMAIN_NAME,\n       tdme.DOMAIN_USAGE AS EXTENSION_DOMAIN_USAGE,\n       tdme.METADATA_EXTN_DESCRIPTION AS EXTENSION_DESCRIPTION,\n       p.PREVIOUS_TRANSFORMATION,\n       CAST(NULL AS VARCHAR2(4000)) AS NEXT_TRANSFORMATION_NAME\nFROM target_definition_instances tdi\nLEFT JOIN target_port_summary p\n  ON p.SUBJECT_ID = tdi.SUBJECT_ID AND p.MAPPING_ID = tdi.MAPPING_ID\n AND p.INSTANCE_ID = tdi.INSTANCE_ID AND p.WIDGET_ID = tdi.WIDGET_ID\n AND p.VERSION_NUMBER = tdi.VERSION_NUMBER\nLEFT JOIN target_definition_properties tdp\n  ON tdp.SUBJECT_ID = tdi.SUBJECT_ID AND tdp.MAPPING_ID = tdi.MAPPING_ID\n AND tdp.INSTANCE_ID = tdi.INSTANCE_ID AND tdp.WIDGET_ID = tdi.WIDGET_ID\n AND tdp.VERSION_NUMBER = tdi.VERSION_NUMBER\nLEFT JOIN target_definition_metadata_extensions tdme\n  ON tdme.SUBJECT_ID = tdi.SUBJECT_ID AND tdme.MAPPING_ID = tdi.MAPPING_ID\n AND tdme.INSTANCE_ID = tdi.INSTANCE_ID AND tdme.WIDGET_ID = tdi.WIDGET_ID\n AND tdme.VERSION_NUMBER = tdi.VERSION_NUMBER\nORDER BY tdi.SUBJECT_AREA, tdi.WORKFLOW_NAME, tdi.SESSION_INSTANCE_NAME,\n         tdi.SESSION_NAME, tdi.MAPPING_NAME, tdi.TRANSFORMATION_NAME,\n         p.PORT_ORDER NULLS LAST, p.PORT_NAME NULLS LAST,\n         tdme.METADATA_EXTN_NAME NULLS LAST, tdme.LINE_NO NULLS LAST"

def canonical(v):
    k=re.sub(r"[^A-Z0-9]+","",str(v or "").upper())
    return ALIASES.get(k,k)
def args():
    p=argparse.ArgumentParser(description="Export workflow transformation metadata")
    p.add_argument("--subject-area",required=True); p.add_argument("--workflow",required=True)
    p.add_argument("--mapping",help="Optional mapping name; omit for the entire workflow")
    p.add_argument(
        "--transformation-name", action="append", default=[],
        help=("Transformation instance name to extract. Repeat the option or pass "
              "comma-separated names. The All Mappings query always validates them first.")
    )
    p.add_argument("--config",type=Path,default=Path("config.json")); p.add_argument("--output",type=Path)
    p.add_argument("--log-file",type=Path); p.add_argument("--schema")
    return p.parse_args()
def selected_transformation_names(values):
    """Return de-duplicated transformation names while preserving user order."""
    result=[]
    seen=set()
    for value in values or []:
        for name in str(value).split(","):
            name=name.strip()
            key=name.casefold()
            if name and key not in seen:
                seen.add(key); result.append(name)
    return result

def logging_setup(path):
    path.parent.mkdir(parents=True,exist_ok=True); root=logging.getLogger(); root.handlers.clear(); root.setLevel(logging.DEBUG)
    f=logging.Formatter(LOG_FORMAT); c=logging.StreamHandler(); c.setLevel(logging.INFO); c.setFormatter(f)
    h=logging.FileHandler(path,encoding="utf-8",mode="w"); h.setLevel(logging.DEBUG); h.setFormatter(f)
    root.addHandler(c); root.addHandler(h)
def config(path):
    with path.open(encoding="utf-8") as f: x=json.load(f)
    db=x.get("db"); missing=[k for k in ("user","password","dsn") if not isinstance(db,dict) or not db.get(k)]
    if missing: raise ValueError("Missing database keys: "+", ".join(missing))
    return db,x.get("options") or {},x.get("thick_mode") or {}
def schema(v):
    v=(v or "").strip().rstrip(".").upper()
    if v and not re.fullmatch(r"[A-Z][A-Z0-9_$#]*",v): raise ValueError(f"Invalid Oracle schema: {v!r}")
    return v+"." if v else ""
def connect(db,thick):
    if oracledb is None: raise RuntimeError("Missing dependency 'oracledb'. Run: pip install oracledb pandas openpyxl")
    if bool(thick.get("enabled",False)):
        d=str(thick.get("lib_dir") or "").strip() or None; oracledb.init_oracle_client(**({"lib_dir":d} if d else {}))
    log.info("Connecting to Oracle DSN %s as %s",db["dsn"],db["user"])
    return oracledb.connect(user=db["user"],password=db["password"],dsn=db["dsn"])
def prepare(sql,owner,mapping_mode):
    sql=sql.strip().rstrip(";")
    sql=re.sub(r"\b[A-Z][A-Z0-9_$#]*\.(?=(?:REP_|OPB_)[A-Z0-9_$#]+)",owner,sql,flags=re.I)

    # Support both w.SUBJECT_AREA and m.SUBJECT_AREA in embedded queries.
    sql=re.sub(
        r"(\b(?:w|m|s)\.SUBJECT_AREA\s*=\s*)'[^']*'",
        r"\1:subject_area", sql, flags=re.I
    )
    sql=re.sub(
        r"(\bw\.WORKFLOW_NAME\s*=\s*)'[^']*'",
        r"\1:workflow_name", sql, flags=re.I
    )

    # Lookup Procedure contains a hardcoded mapping predicate. In workflow mode
    # remove that predicate; otherwise Oracle sees :mapping_name without a bind.
    mapping_literal = r"\s+AND\s+m\.MAPPING_NAME\s*=\s*'[^']*'"
    if mapping_mode:
        sql=re.sub(
            r"(\bm\.MAPPING_NAME\s*=\s*)'[^']*'",
            r"\1:mapping_name", sql, flags=re.I
        )
        if ":mapping_name" not in sql:
            pred=("\n AND s.MAPPING_ID IN (SELECT fm.MAPPING_ID FROM " + owner +
                  "REP_ALL_MAPPINGS fm WHERE fm.SUBJECT_AREA=s.SUBJECT_AREA "
                  "AND fm.MAPPING_NAME=:mapping_name)")
            sql,n=re.subn(
                r"(\bw\.WORKFLOW_NAME\s*=\s*:workflow_name)",
                r"\1"+pred, sql, count=1, flags=re.I
            )
            if n!=1:
                raise ValueError("Could not inject mapping filter")
    else:
        sql=re.sub(mapping_literal, "", sql, flags=re.I)

    return sql

def bind_names(sql):
    # Remove quoted SQL strings before scanning, so POSIX expressions such as
    # [[:space:]] are not mistaken for Oracle bind variables.
    without_literals=re.sub(r"'(?:''|[^'])*'", "''", sql)
    return set(re.findall(r"(?<!:):([A-Za-z][A-Za-z0-9_$#]*)", without_literals))

def run(conn,name,sql,binds):
    required=bind_names(sql)
    missing=sorted(required-set(binds))
    if missing:
        raise ValueError(f"Missing Oracle bind value(s) for {name}: {', '.join(missing)}")
    execute_binds={key:binds[key] for key in required}
    log.debug("SQL [%s], required_binds=%s, binds=%s\n%s",name,sorted(required),execute_binds,sql)
    t=time.perf_counter()
    with conn.cursor() as cur:
        cur.execute(sql,execute_binds); cols=[x[0] for x in cur.description]; rows=cur.fetchall()
    df=pd.DataFrame(rows,columns=cols); elapsed=time.perf_counter()-t
    log.info("%s: %d rows, %.2f seconds",name,len(df),elapsed); return df,elapsed
def sheet_name(v,used):
    b=re.sub(r"[\\/*?:\[\]]","_",str(v)).strip()[:31] or "Transformation"; n=b; i=2
    while n.casefold() in used:
        s=f"_{i}"; n=b[:31-len(s)]+s; i+=1
    used.add(n.casefold()); return n
def style(ws,df,summary=False):
    fill=PatternFill("solid",fgColor="7030A0" if summary else "1F4E78"); font=Font(color="FFFFFF",bold=True)
    for c in ws[1]: c.fill=fill; c.font=font
    ws.freeze_panes="A2"; ws.sheet_view.showGridLines=False
    if ws.max_row and ws.max_column: ws.auto_filter.ref=ws.dimensions
    for i,col in enumerate(df.columns,1):
        sample=[str(col)]+["" if x is None else str(x) for x in df[col].head(300)]
        ws.column_dimensions[get_column_letter(i)].width=min(max(map(len,sample))+2,60)
def load_mapplet_module():
    """Load the companion mapplet extractor from the main script directory."""
    module_path=Path(__file__).resolve().with_name("mapplet_script.py")
    if not module_path.exists():
        raise FileNotFoundError(f"Mapplet extractor not found: {module_path}")
    spec=importlib.util.spec_from_file_location("informatica_mapplet_workflow",module_path)
    module=importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module

def write(path,sheets,summary,mapplet_result=None):
    path.parent.mkdir(parents=True,exist_ok=True); used=set()
    with pd.ExcelWriter(path,engine="openpyxl") as w:
        for name,df in sheets:
            n=sheet_name(name,used); df.to_excel(w,sheet_name=n,index=False); style(w.book[n],df)
        if mapplet_result:
            discovery,outputs,mapplet_summary,mapplet_status=mapplet_result
            mapplet_tabs=[("Mapplet_Transformations",discovery)]
            mapplet_tabs.extend(("Mapplet_"+str(label),df) for label,df in outputs.items())
            mapplet_tabs.extend([("Mapplet_Execution_Summary",mapplet_summary),
                                 ("Mapplet_Query_Status",mapplet_status)])
            for name,df in mapplet_tabs:
                n=sheet_name(name,used); df.to_excel(w,sheet_name=n,index=False)
                style(w.book[n],df,"Summary" in name or "Status" in name)
        n=sheet_name("Execution Summary",used); summary.to_excel(w,sheet_name=n,index=False); style(w.book[n],summary,True)
    log.info("Excel written: %s",path.resolve())
def main():
    a=args(); initial=a.output or Path("./output/informatica_workflow_transformations.xlsx")
    logging_setup(a.log_file or initial.with_suffix(".log")); conn=None; started=datetime.now()
    try:
        db,opt,thick=config(a.config)
        out=a.output or Path(opt.get("output_folder") or "./output")/"informatica_workflow_transformations.xlsx"
        owner=schema(a.schema if a.schema is not None else opt.get("schema_prefix"))
        binds={"subject_area":a.subject_area,"workflow_name":a.workflow}
        requested=selected_transformation_names(a.transformation_name)
        mf=""
        if a.mapping:
            binds["mapping_name"]=a.mapping
            mf=("AND s.MAPPING_ID IN (SELECT fm.MAPPING_ID FROM "+owner+
                "REP_ALL_MAPPINGS fm WHERE fm.SUBJECT_AREA=s.SUBJECT_AREA "
                "AND fm.MAPPING_NAME=:mapping_name)")

        conn=connect(db,thick)

        # Mandatory first query: discover and validate the workflow transformations.
        first=ALL_MAPPINGS_QUERY.format(schema=owner,mapping_filter=mf)
        all_df,e=run(conn,"All Mappings",first,binds)
        if all_df.empty:
            raise ValueError("No rows found for requested workflow/mapping")

        available={str(v).strip().casefold():str(v).strip()
                   for v in all_df["INSTANCE_NAME"].dropna() if str(v).strip()}
        missing=[name for name in requested if name.casefold() not in available]
        if missing:
            sample=", ".join(sorted(available.values(),key=str.casefold)[:30])
            raise ValueError(
                "Requested transformation(s) not available in the workflow: " +
                ", ".join(missing) + ". Available transformations include: " + sample
            )

        if requested:
            selected_keys={name.casefold() for name in requested}
            selected_all_df=all_df[
                all_df["INSTANCE_NAME"].astype(str).str.strip().str.casefold().isin(selected_keys)
            ].copy()
            work_df=selected_all_df
            log.info("Validated %d requested transformation(s): %s",
                     len(requested),", ".join(requested))
        else:
            selected_all_df=all_df
            work_df=all_df

        sheets=[("All Mappings",selected_all_df)]
        rows=[{"TRANSFORMATION_TYPE":"All Mappings","STATUS":"SUCCESS",
               "ROW_COUNT":len(selected_all_df),"ELAPSED_SECONDS":round(e,3),"MESSAGE":""}]
        types=sorted({str(x).strip() for x in work_df["WIDGET_TYPE_NAME"].dropna()
                      if str(x).strip()},key=str.casefold)

        for typ in types:
            # Mapplet instances are handled by the companion extractor below.
            if canonical(typ) == "MAPPLET":
                rows.append({"TRANSFORMATION_TYPE":typ,"STATUS":"DELEGATED_TO_MAPPLET_EXTRACTOR",
                             "ROW_COUNT":int((work_df["WIDGET_TYPE"]==44).sum()),
                             "ELAPSED_SECONDS":0,"MESSAGE":"See Mapplet_* tabs"})
                continue
            item=EMBEDDED_QUERIES.get(canonical(typ))
            if not item:
                msg=f"SQL Query for transformation '{typ}' is missing"
                log.warning(msg)
                rows.append({"TRANSFORMATION_TYPE":typ,"STATUS":"MISSING_SQL",
                             "ROW_COUNT":0,"ELAPSED_SECONDS":0,"MESSAGE":msg})
                continue
            try:
                sql=prepare(item["sql"],owner,bool(a.mapping))
                b=dict(binds)
                if ":mapping_name" not in sql: b.pop("mapping_name",None)
                df,e=run(conn,typ,sql,b)
                if a.mapping and "MAPPING_NAME" in df.columns and len(df[df["MAPPING_NAME"]!=a.mapping]):
                    raise ValueError("Query returned rows from another mapping")

                # Restrict each detail result to the validated transformation instances.
                if requested:
                    name_column=next((c for c in
                        ("TRANSFORMATION_NAME","LOOKUP_TRANSFORMATION","INSTANCE_NAME")
                        if c in df.columns),None)
                    if not name_column:
                        raise ValueError(
                            f"Cannot filter {typ}: transformation-name column is absent"
                        )
                    df=df[df[name_column].astype(str).str.strip().str.casefold().isin(selected_keys)].copy()

                sheets.append((typ,df))
                rows.append({"TRANSFORMATION_TYPE":typ,"STATUS":"SUCCESS",
                             "ROW_COUNT":len(df),"ELAPSED_SECONDS":round(e,3),"MESSAGE":""})
            except Exception as ex:
                log.exception("Transformation query failed: %s",typ)
                rows.append({"TRANSFORMATION_TYPE":typ,"STATUS":"FAILED",
                             "ROW_COUNT":0,"ELAPSED_SECONDS":0,"MESSAGE":str(ex)})

        # If the workflow contains mapplet instances (widget type 44), delegate
        # mapplet discovery and detail extraction to the companion script.
        mapplet_result=None
        mapplet_mask=(pd.to_numeric(all_df.get("WIDGET_TYPE"),errors="coerce")==44)
        if bool(mapplet_mask.any()):
            try:
                mapplet_module=load_mapplet_module()
                discovery,mapplet_summary=mapplet_module.discover_workflow_mapplets(
                    conn,owner,a.subject_area,a.workflow)
                mapplet_outputs,mapplet_status=mapplet_module.run_detail_queries(
                    conn,owner,discovery,a.subject_area,a.workflow)
                mapplet_result=(discovery,mapplet_outputs,mapplet_summary,mapplet_status)
                log.info("Mapplet extraction completed: mapplets=%d, detail_tabs=%d",
                         discovery["MAPPLET_NAME"].nunique() if not discovery.empty else 0,
                         len(mapplet_outputs))
            except Exception as ex:
                log.exception("Mapplet extraction failed")
                mapplet_summary=pd.DataFrame([{"MODE":"WORKFLOW_ALL_MAPPLETS",
                    "MAPPLET_NAME":"ALL_MAPPLETS","STATUS":"ERROR","ROW_COUNT":0,
                    "ELAPSED_SECONDS":0,"ERROR_MESSAGE":str(ex)}])
                mapplet_result=(pd.DataFrame(),{},mapplet_summary,pd.DataFrame())
                rows.append({"TRANSFORMATION_TYPE":"Mapplet","STATUS":"FAILED",
                             "ROW_COUNT":0,"ELAPSED_SECONDS":0,"MESSAGE":str(ex)})
        else:
            log.info("No mapplet instances found for workflow; companion extractor skipped")

        summary=pd.DataFrame(rows)
        summary.insert(0,"SUBJECT_AREA",a.subject_area)
        summary.insert(1,"WORKFLOW_NAME",a.workflow)
        summary.insert(2,"MAPPING_NAME",a.mapping or "ALL")
        summary.insert(3,"SELECTED_TRANSFORMATIONS",", ".join(requested) if requested else "ALL")
        summary["STARTED_AT"]=started; summary["FINISHED_AT"]=datetime.now()
        write(out,sheets,summary,mapplet_result)
        return 2 if summary["STATUS"].eq("FAILED").any() else 0
    except Exception:
        log.exception("Extraction failed"); return 1
    finally:
        if conn is not None: conn.close(); log.info("Oracle connection closed")
if __name__=="__main__": sys.exit(main())
